// ---------------------------------------------------------------- 写面范围（#1016 批次 B 使能面）
//
// 本块从写入口径验两件机制层的事：① 还原与校验取到的存量必须是**队列内那一刻**的
// （基线漂移会让「原样带回」判成「本次改动」）；② 机制本身**不新增任何拒绝**——
// 存量里非法的值原样带回时仍按今天的判据走，本次改动触碰的字段也仍走今天的判据。

describe("写面：存量基线在写队列内取（#1016 批次 B）", () => {
  // 机制的地基用例：并发的两次写里，后一次必须拿前一次**落盘后**的存量去还原掩码。
  // 还原在队列外做的话，后一次会用前一次落盘前的 deviceKey 覆盖回去——前一次的改动被吃掉，
  // 而界面上看不出任何异常。
  it("并发两次写：后一次在队列内取基线，不会把前一次刚落盘的凭据用旧值盖回去", async () => {
    assemble();
    expect((await writeConfig({ channels: [...BUILTINS, BARK] })).ok).toBe(true);

    // 两次写都不带 expectedRevision：乐观并发不参与，这里只看基线取的时刻。
    const results = await Promise.all([
      // 第一次：把 deviceKey 换成新值。
      writeConfig({ channels: [...BUILTINS, { ...BARK, deviceKey: "key-2" }] }),
      // 第二次：凭据原样带回（掩码），别的字段改一个无关的。
      writeConfig({ channels: [...BUILTINS, { ...BARK, deviceKey: MASK, name: "改名" }] }),
    ]);
    expect(results[0].ok).toBe(true);
    expect(results[1].ok).toBe(true);

    // 关键断言：后一次的「原样带回」必须还原成前一次刚落盘的 key-2，而不是最初的 key-1。
    // 还原在队列外做时这里会是 key-1 —— 前一次的改动被静默吃掉。
    expect(channelOfType(diskChannels(), "bark").deviceKey).toBe("key-2");
    expect(channelOfType(diskChannels(), "bark").name).toBe("改名");
  });

  // 回归护栏：一条**非法**的提交，带不带存量基线，判据结论都必须与今天逐字相同。
  //
  // 提交体是手拼的（照抄视图里的原样存储形态）：真实客户端不会产出这种 payload——它的草稿
  // 来自归一化视图，半坏条目压根不在草稿里（真实往返链的形态见
  // test/integration/config-merge-roundtrip.test.ts）。这里要断的是**判据结论不变**，
  // 而不是某一类客户端会不会这么发。
  it("手拼的非法提交（半坏条目 baseUrl 为空）：仍按今天的判据 400——机制不放行也不加拒", async () => {
    // 手写配置文件造出半坏条目：baseUrl 为空但 deviceKey 在。
    writeConfigFile(
      JSON.stringify({
        channels: [...BUILTINS, { type: "bark", id: "bark:half", baseUrl: "", deviceKey: "key-1" }],
      }),
    );
    assemble();

    // 前提事实：这条频道在生效设置里不存在（归一化丢弃），但在存储视图里看得见。
    expect(readConfig().channels.some((c) => c.id === "bark:half")).toBe(false);
    const view = readSettingsView();
    expect(channelsOf(view.user).some((c) => c.id === "bark:half")).toBe(true);

    // 原样提交（凭据是掩码，其余逐字照抄视图）。
    const before = readFileSync(configFile, "utf8");
    const result = await writeConfig({ channels: channelsOf(view.user) });

    // 结论：仍然按今天的判据 400（本 PR 不加也不减任何判据）。
    // 后续的边界 PR 才是把这一条放行的那一方——它会查 scope 而不是查值。
    expect(invalidOf(result).key).toBe("channels");
    expect(readFileSync(configFile, "utf8")).toBe(before);
  });

  // 回归护栏：本次改动触碰的字段仍走现有判据。机制在这里必须**没有**任何话语权。
  it("本次改动触碰的非法字段仍被现有判据拒（机制不放行任何东西）", async () => {
    assemble();
    expect((await writeConfig({ channels: [...BUILTINS, BARK] })).ok).toBe(true);
    const before = readFileSync(configFile, "utf8");

    // level 非法：当前就会 400，本次改动与否都该 400。
    const result = await writeConfig({
      channels: [...BUILTINS, { ...BARK, level: "urgent" }],
    });
    expect(invalidOf(result).hint).toContain("level");
    expect(readFileSync(configFile, "utf8")).toBe(before);

    // 顶层的非法值同理：机制只管频道字段，但结论必须一个字都没变。
    const topLevel = await writeConfig({ historyMaxAgeDays: -1 });
    expect(invalidOf(topLevel).key).toBe("historyMaxAgeDays");
    expect(readFileSync(configFile, "utf8")).toBe(before);
  });

  // 合法保存照常成功：机制不是「多一个拒绝口」。这条守住「不得引入任何新的拒绝行为」。
  it("合法保存照常成功：既有的凭据往返与掩码还原行为一字未变", async () => {
    assemble();
    expect((await writeConfig({ channels: [...BUILTINS, BARK] })).ok).toBe(true);
    const view = readSettingsView();

    const submitted = channelsOf(view.user).map((channel) => ({ ...channel, name: "手机" }));
    const result = await writeConfig({ channels: submitted }, view.revision);

    expect(result.ok).toBe(true);
    expect(channelOfType(diskChannels(), "bark").name).toBe("手机");
    // 未编辑的凭据仍是原值（掩码还原路径没被本 PR 动过）。
    expect(channelOfType(diskChannels(), "bark").deviceKey).toBe("key-1");
  });
});

// ---------------------------------------------------------------- 缺陷 A（#1016 S0）：空串被掩码
//
// 完整因果链（四步，每一步都在既有代码里）：① 读面把磁盘上**缺席**的凭据补成空串
// （input/index.ts 的 `asString(raw.token, "")` 兜底）→ ② redact/index.ts 的 maskChannel 把空串
// 也掩成占位（`typeof "" === "string"`）→ ③ 客户端剥空串剥不掉占位（值不是空串），原样带回
// → ④ 写面 unmaskChannels 按 id 取回的 `original.channel[field]` 是 undefined，
// `typeof value !== "string"` → 整批被拒，400「新增频道不能提交掩码占位」。
//
// 真实用户路径：设置页新建一条 webhook（落盘只有 url/auth/timeoutSec/enabled，三个密钥键全无）
// → 第一次保存成功 → **只切一下 enabled 开关就再也存不下去**。死锁的是整份配置，不是那一条频道。

describe("空串凭据不被掩码（#1016 缺陷 A）", () => {
  // 提交体一律过 stripChannelEmpties：那是客户端 diff.ts 提交前对每个频道实例做的那一步，
  // 直接用共享面同一份实现（客户端提交、服务端写面基线、比较规范形是同一处），不在测试里另写
  // 一份剥除逻辑——手写副本会让这条用例在客户端真的不再剥空串时继续绿。
  it("磁盘上缺席的凭据：客户端只改 enabled 也能存下去，且磁盘上仍无这三个键（不是被写成空串）", async () => {
    // 磁盘形态：设置页新建的 webhook 存下来就是这样——三个凭据键一个都没有。
    // 两条内置条目照真实文件那样在场：#1016 S3 之后「内置恒在场」由 upgrade 域的形态清理保证，
    // 读面不再物化它们，而写面仍会对缺内置的提交 400（内置渠道不能删除）。
    writeConfigFile(
      JSON.stringify({
        channels: [
          ...BUILTINS,
          {
            type: "webhook",
            id: "webhook:hook",
            url: "https://example.test/hook",
            auth: "none",
            enabled: true,
          },
        ],
      }),
    );
    assemble();

    // #1016 S3：视图不再补默认值，磁盘上缺席的键在视图里就**缺席**（不再是空串）。
    // 两种形态对客户端等价（输入框里 undefined 与空串同显空，剥空串对两者是同一条判据），
    // 而「缺席」让写面在合并时把它读成「不动」——这正是本用例要的落盘结果。
    const view = readSettingsView();
    const shown = channelOfType(channelsOf(view.effective), "webhook");
    expect("token" in shown).toBe(false);
    expect("password" in shown).toBe(false);
    expect("headerValue" in shown).toBe(false);

    // 用户手势只有切 enabled；整组 channels 照常提交，每项先过共享面的空串剥除。
    const submitted = channelsOf(view.effective).map(
      (channel) =>
        stripChannelEmpties(
          channel.type === "webhook" ? { ...channel, enabled: false } : channel,
        ) as Record<string, RawSettingValue>,
    );
    const result = await writeConfig({ channels: submitted }, view.revision);

    // 空串原样透出 → 客户端剥空串剥掉了这三个键 → 写面看不到占位，还原不触发，整批不拒。
    // 空串被掩码时这里拿到的是 400「新增频道不能提交掩码占位，请填写真实凭据」。
    expect(result.ok).toBe(true);
    const stored = channelOfType(diskChannels(), "webhook");
    expect(stored.enabled).toBe(false);
    // 落盘后仍是**键缺席**，不是被补成空串：空串与缺席在读面同形，写面却要保住这个区别。
    expect("token" in stored).toBe(false);
    expect("password" in stored).toBe(false);
    expect("headerValue" in stored).toBe(false);
  });

  // 反例钉住：把掩码通道整条关掉（另一种同样像样的「修法」）会让这一条变红。
  // 非空的真凭据在读面必须是占位、原样带回必须还原成真实值——这次改动只放宽空串那一侧。
  it("反例：磁盘上有真凭据时掩码通道照旧工作——读面出占位、原样带回还原成真实值", async () => {
    writeConfigFile(
      JSON.stringify({
        channels: [
          ...BUILTINS,
          {
            type: "webhook",
            id: "webhook:hook",
            url: "https://example.test/hook",
            auth: "bearer",
            enabled: true,
            token: "REAL",
          },
        ],
      }),
    );
    assemble();

    const view = readSettingsView();
    // 脱敏没开口子：非空的 token 仍然只出占位。
    expect(channelOfType(channelsOf(view.effective), "webhook").token).toBe(MASK);

    // 用户只改显示名。占位不是空串，剥不掉它，原样带回走还原路径。
    const submitted = channelsOf(view.effective).map(
      (channel) =>
        stripChannelEmpties(
          channel.type === "webhook" ? { ...channel, name: "改名" } : channel,
        ) as Record<string, RawSettingValue>,
    );
    const result = await writeConfig({ channels: submitted }, view.revision);

    expect(result.ok).toBe(true);
    const stored = channelOfType(diskChannels(), "webhook");
    expect(stored.name).toBe("改名");
    // 还原回真实值，而不是把占位字面量写进文件（那等于凭据从此报废）。
    expect(stored.token).toBe("REAL");
  });
});

// ---------------------------------------------------------------- #1016 S2：写面按字段合并
//
// 本块逐条钉住「键缺席 = 不动」这条新语义的十个面。每条都是**端到端**的（真实写面 → 真实落盘），
// 因为这条语义横跨两处代码：服务端合并（写面）与客户端手势（diff.ts / index.tsx）；只断一侧，
// 另一侧改坏时用例照样绿。客户端那一半在 test/client-unit/settings-diff.test.ts。
//
// 提交体一律照真实往返链的形态造：从 `GET /config` 的 `effective` 取草稿 → 改一个字段 → 整组
// 提交。凭空手拼的「只交一个键」的提交在真实链路上不存在，而它恰好是旧语义（整组替换）下唯一
// 不会丢字段的那种——用它写判据会把「服务端支持按键合并」这件事测成假。

/** 磁盘上的一条 webhook：url + auth，credential 键按用例再加。 */
const HOOK = {
  type: "webhook",
  id: "webhook:hook",
  url: "https://example.test/hook",
  auth: "none",
  enabled: true,
} as const;

/** 频道数组里按 id 取那一条（两条同类型时不能按类型取——那只会拿到第一条）。 */
function channelById(
  list: readonly RawSettingValue[],
  id: string,
): Record<string, RawSettingValue> {
  const found = (list as ReadonlyArray<Record<string, RawSettingValue>>).find(
    (item) => item.id === id,
  );
  if (found === undefined) throw new Error(`数组里没有 id=${id} 的频道`);
  return found;
}

/** 造一份磁盘：给 channels 的每条补上两条内置条目（真实文件里也有）。 */
function diskOf(...channels: ReadonlyArray<Record<string, RawSettingValue>>): string {
  return JSON.stringify({ channels: [...BUILTINS, ...channels] });
}

/** 提交面：从 effective 取草稿后逐条应用 part（part 里写 null = 用户清空了那个字段）。 */
function submitOf(
  part: (channel: Record<string, RawSettingValue>) => Record<string, RawSettingValue>,
  type = "webhook",
): Array<Record<string, RawSettingValue>> {
  return channelsOf(readSettingsView().effective).map((channel) =>
    channel.type === type ? part(channel) : channel,
  );
}

describe("写面按字段合并：键缺席 = 不动（#1016 S2）", () => {
  // 判据 #1（**安全**）：用户清空 token，磁盘上必须**没有** token 键。
  // 改坏方向：客户端清空改回「删键」→ 提交里没有这个键 → 合并判「不动」→ 旧凭据留在磁盘上继续
  // 被投递，而界面显示空。那是本次重构里唯一一条会造成「看起来删了、其实还在用」的面。
  it("判据 #1：清空 token 落盘后磁盘上没有 token 键（不是空串，也不是原样留着）", async () => {
    writeConfigFile(diskOf({ ...HOOK, auth: "bearer", token: "REAL" }));
    assemble();
    expect(channelOfType(diskChannels(), "webhook").token).toBe("REAL");

    // 草稿里 token 是掩码，用户清空 → 客户端写 null（显式删除）。
    const submitted = submitOf((channel) => ({ ...channel, token: null }));
    const result = await writeConfig({ channels: submitted }, readSettingsView().revision);

    expect(result.ok).toBe(true);
    const stored = channelOfType(diskChannels(), "webhook");
    expect("token" in stored).toBe(false);
    expect(stored.token).toBeUndefined();
  });

  // 判据 #2：存量本来就没有这个键时，一次无关保存不该「追责存量」——更不该凭空造一个出来。
  it("判据 #2：磁盘本就无 token、只改 name，落盘后仍无 token 键", async () => {
    writeConfigFile(diskOf(HOOK));
    assemble();
    expect("token" in channelOfType(diskChannels(), "webhook")).toBe(false);

    const submitted = submitOf((channel) => ({ ...channel, name: "群机器人" }));
    const result = await writeConfig({ channels: submitted }, readSettingsView().revision);

    expect(result.ok).toBe(true);
    const stored = channelOfType(diskChannels(), "webhook");
    expect(stored.name).toBe("群机器人");
    expect("token" in stored).toBe(false);
  });

  // 判据 #3：存量 template 恰超上界一字符。只改 name 必须**放行**——「拒新增、不动存量」的
  // 双轨。放行的理由是那条 template 与磁盘逐字相同：客户端把它原样带回来了，而「原样带回」
  // 不是本次改动。上界取自共享 schema（见 TEMPLATE_OVER_LIMIT），故本判据在上限值变化后仍然
  // 判的是同一条语义，而不是「恰好没变的那个数字」。
  it("判据 #3：存量 template 恰超上界 + 只改 name → 放行（不动存量）", async () => {
    const long = "x".repeat(TEMPLATE_OVER_LIMIT);
    writeConfigFile(diskOf({ ...HOOK, template: long }));
    assemble();
    expect(channelOfType(diskChannels(), "webhook").template).toBe(long);

    const submitted = submitOf((channel) => ({ ...channel, name: "群机器人" }));
    // 前提事实：客户端确实把那条超界 template 原样带回来了（不是「没带」才躲过判据）。
    expect(channelOfType(submitted, "webhook").template).toBe(long);

    const result = await writeConfig({ channels: submitted }, readSettingsView().revision);
    expect(result.ok).toBe(true);
    expect(channelOfType(diskChannels(), "webhook").template).toBe(long);
    expect(channelOfType(diskChannels(), "webhook").name).toBe("群机器人");
  });

  // 判据 #4：同一份存量，本次把它改成另一个更长的值即 400。#3/#4 的分界就是「本次动没动过
  // 这个值」，不是「它超没超上界」。
  it("判据 #4：存量 template 恰超上界 → 本次改成更长的另一个值 → 400 且不落盘", async () => {
    writeConfigFile(diskOf({ ...HOOK, template: "x".repeat(TEMPLATE_OVER_LIMIT) }));
    assemble();
    const before = readFileSync(configFile, "utf8");

    const submitted = submitOf((channel) => ({
      ...channel,
      template: "y".repeat(TEMPLATE_OVER_LIMIT_EDITED),
    }));
    const result = await writeConfig({ channels: submitted }, readSettingsView().revision);

    const error = invalidOf(result);
    expect(error.key).toBe("channels");
    expect(error.hint).toContain("template");
    // 话术里的上界取自共享 schema：改上界不必改这条断言，而话术忘了跟上共享值会被这条打红。
    expect(error.hint).toContain(String(WEBHOOK_TEMPLATE_MAX_CHARS));
    expect(readFileSync(configFile, "utf8")).toBe(before);
  });

  // 判据 #5：存量 levels 恰超上界若干项，只改**另一条**频道的名字，不得连坐。
  // 连坐的机制：客户端整组提交，于是这条的越界项数也进了提交面；它之所以不被拒，是因为它与
  // 磁盘逐字相同（沿用存量），不是「客户端没带」。
  it("判据 #5：存量 levels 恰超上界 + 只改另一条 bark 的 name → 放行（不连坐）", async () => {
    const levels: Record<string, string> = {};
    for (let i = 0; i < LEVELS_OVER_LIMIT; i += 1) levels[`kind-${i}`] = "active";
    writeConfigFile(diskOf({ ...BARK, levels }, { ...BARK, id: "bark:pad", name: "B" }));
    assemble();

    const submitted = submitOf(
      (channel) => (channel.id === "bark:pad" ? { ...channel, name: "平板" } : channel),
      "bark",
    );
    // 前提事实：越界项数确实进了提交面（整组提交），且与磁盘逐字相同。
    expect(Object.keys(channelById(submitted, "bark:phone").levels as object)).toHaveLength(
      LEVELS_OVER_LIMIT,
    );

    const result = await writeConfig({ channels: submitted }, readSettingsView().revision);
    expect(result.ok).toBe(true);
    // 一项不少（沿用存量），被改的是**另一条**频道的名字。
    expect(Object.keys(channelById(diskChannels(), "bark:phone").levels as object)).toHaveLength(
      LEVELS_OVER_LIMIT,
    );
    expect(channelById(diskChannels(), "bark:phone").name).toBe("A");
    expect(channelById(diskChannels(), "bark:pad").name).toBe("平板");
  });

  // 判据 #6：改小是修复动作。超上界 → 删到界内判「本次改动」，但界内在上界内故放行，且落盘确实变小。
  it("判据 #6：存量 levels 恰超上界 → 本次删到界内 → 放行且落盘真的变小", async () => {
    const levels: Record<string, string> = {};
    for (let i = 0; i < LEVELS_OVER_LIMIT; i += 1) levels[`kind-${i}`] = "active";
    writeConfigFile(diskOf({ ...BARK, levels }));
    assemble();

    const trimmed: Record<string, string> = {};
    for (let i = 0; i < LEVELS_UNDER_LIMIT; i += 1) trimmed[`kind-${i}`] = "active";
    const submitted = submitOf((channel) => ({ ...channel, levels: trimmed }), "bark");
    const result = await writeConfig({ channels: submitted }, readSettingsView().revision);

    expect(result.ok).toBe(true);
    expect(Object.keys(channelById(diskChannels(), "bark:phone").levels as object)).toHaveLength(
      LEVELS_UNDER_LIMIT,
    );
  });

  // 判据 #7：必填键的两种删除手势都 400，话术指向「必填键，不能删除」——与「没交」分开。
  //
  // id / type / url / auth 在这里两种手势都试；baseUrl / deviceKey 只试 null（空串那一支客户端已经剥掉了，见下方注释）。
  // `auth` 是**取值域类**必填键（判据是「值在不在 WEBHOOK_AUTHS 里」而不是「键在不在」），与在场必填键
  // 不可删这一点同形：它同样列在 shared 的 VALUE_DOMAIN_REQUIRED_KEYS 里，两种手势都走「必填键，不能删除」。
  // 它**刻意不在客户端空串剥除清单**（shared/channel-compare.ts），所以空串那一支也能真实抵达写面。
  it("判据 #7：必填键传 null 或空串一律 400，话术点名该键且说的是「不能删除」", async () => {
    writeConfigFile(diskOf({ ...HOOK, auth: "bearer", token: "REAL" }, BARK));
    assemble();
    const before = readFileSync(configFile, "utf8");

    // 身份键（id / type）与投递必需键（webhook 的 url、以及取值域类的 auth）同样不可删：
    // 删了它条目就不是同一条了；删 `auth` 造出的那条频道还会被输入闸门以「auth 非法」拒收，
    // 写面对缺席与非法共用一句话，于是同一个手势的两种落点给出两句话（见 roundtrip 的同名判据组）。
    for (const [key, value] of [
      ["url", null],
      ["url", ""],
      ["auth", null],
      ["auth", ""],
      ["type", null],
      ["type", ""],
    ] as ReadonlyArray<readonly [string, RawSettingValue]>) {
      const submitted = submitOf((channel) => ({ ...channel, [key]: value }));
      const error = invalidOf(await writeConfig({ channels: submitted }));
      expect(error.key, key).toBe("channels");
      expect(error.hint, key).toContain(key);
      expect(error.hint, key).toContain("必填键");
      expect(error.hint, key).toContain("不能删除");
    }
    // baseUrl / deviceKey 只剩 null 这一支：#1016 P2-1 之后客户端**不再**把它们以空串提交——空串在客户端的
    // 空串剥除清单里（跨类型并集：bark 的 url / webhook 的 baseUrl 同理），提交前就变成键缺席，落在
    // preexisting 的放行路径上。真实客户端表达「清空」用的是 assignChannelFields 写的 null，那一支照旧 400。
    // 走真实客户端链的那一对在 test/integration/config-merge-roundtrip.test.ts（判据五 / 判据六）。
    for (const key of ["baseUrl", "deviceKey"]) {
      const submitted = submitOf((channel) => ({ ...channel, [key]: null }), "bark");
      const error = invalidOf(await writeConfig({ channels: submitted }));
      expect(error.hint, key).toContain(key + " 是必填键，不能删除");
    }
    expect(readFileSync(configFile, "utf8")).toBe(before);
  });

  // 判据 #8 的后一半（顶层那一半见上面「写面：合并与凭据」块）。
  it("判据 #8：频道条目内的陌生键 400，存量条目上已有的陌生键不连坐", async () => {
    writeConfigFile(diskOf({ ...HOOK, myCustom: "kept" }));
    assemble();
    const before = readFileSync(configFile, "utf8");

    const submitted = submitOf((channel) => ({ ...channel, myCustom: "submitted" }));
    const error = invalidOf(await writeConfig({ channels: submitted }));
    expect(error.key).toBe("channels");
    expect(error.hint).toContain("myCustom");
    expect(error.hint).toContain("不是已知键");
    expect(readFileSync(configFile, "utf8")).toBe(before);

    // 前提事实：只改 name 时那条陌生键不在提交面里，落盘后原样还在（#1016 缺陷 B 的正解）。

    const ok = await writeConfig({
      channels: submitOf((channel) => ({ ...channel, name: "改名" })),
    });
    expect(ok.ok).toBe(true);
    expect(channelOfType(diskChannels(), "webhook").myCustom).toBe("kept");
  });

  // 判据 #9：掩码通道没被破坏。掩码在合并里解（五态之一），落盘的必须是真实值而不是占位符。
  it("判据 #9：提交掩码占位 → 落盘还原成存量原值（不是占位符本身）", async () => {
    writeConfigFile(diskOf({ ...HOOK, auth: "bearer", token: "REAL" }));
    assemble();
    expect(channelOfType(channelsOf(readSettingsView().effective), "webhook").token).toBe(MASK);

    const submitted = submitOf((channel) => ({ ...channel, name: "群机器人" }));
    expect(channelOfType(submitted, "webhook").token).toBe(MASK);
    const result = await writeConfig({ channels: submitted }, readSettingsView().revision);

    expect(result.ok).toBe(true);
    expect(channelOfType(diskChannels(), "webhook").token).toBe("REAL");
  });

  // 判据 #9 的另一半（**安全**）：掩码**没有原值可还原**时必须 400，而不是把它当普通值写进磁盘。
  // 换型残留的跨 type 掩码是活生生的一例：存量那条 webhook 的 id 被改成 bark，于是同 id 却换了
  // 一条，bark 的 deviceKey 在存量里没有对应原值——而客户端草稿里它就是占位（读出口按类型掩码，
  // 类型一变该键的凭据来源就断了）。落盘即报废：磁盘上从此是 `********`，投递必然失败，而用户
  // 界面上看着「已填写」。新频道带掩码（上一条）走同一个出口、同一句话——两条链路不许两个答案。
  it("判据 #9b：存量条目换 type 后带掩码（无原值可还原）→ 400，磁盘上占位符与换型结果都没有", async () => {
    writeConfigFile(diskOf({ ...HOOK, auth: "bearer", token: "REAL" }));
    assemble();
    expect(channelOfType(diskChannels(), "webhook").token).toBe("REAL");

    // 同一个 id 换成 bark：换型 = 换了一条（字段集随 type 变），deviceKey 在存量里没有原值。
    const submitted = submitOf(
      (channel) =>
        channel.type === "webhook"
          ? { id: "hook:1", type: "bark", baseUrl: "https://api.day.app", deviceKey: MASK }
          : channel,
      "webhook",
    );
    const error = invalidOf(
      await writeConfig({ channels: submitted }, readSettingsView().revision),
    );

    expect(error.key).toBe("channels");
    expect(error.hint).toContain("不能提交掩码占位");
    // 拒绝发生在落盘之前：存量那条 webhook 原封不动，磁盘上既没有占位符、也没有换型结果。
    const stored = channelOfType(diskChannels(), "webhook");
    expect(stored.token).toBe("REAL");
    expect(stored.type).toBe("webhook");
    expect(JSON.stringify(diskChannels())).not.toContain(MASK);
  });

  // 判据 #10：顶层键仍是整值替换——`kindRoutes` 不参与按键合并，删条目就是「这张表里没有它」。
  it("判据 #10：清掉一个 kindRoutes 条目 → 200 且落盘没有该键（顶层是整值替换，不是 null）", async () => {
    writeConfigFile(
      JSON.stringify({ kindRoutes: { done: ["webhook:hook"], error: ["webhook:hook"] } }),
    );
    assemble();
    expect(onDisk().kindRoutes).toEqual({ done: ["webhook:hook"], error: ["webhook:hook"] });

    const result = await writeConfig({ kindRoutes: { done: ["webhook:hook"] } });
    expect(result.ok).toBe(true);
    expect(onDisk().kindRoutes).toEqual({ done: ["webhook:hook"] });

    // 反例钉住方向：写 null 会被顶层值域拒（每项必须是 string[]）——顶层没有「显式删除」这一说。
    const rejected = invalidOf(
      await writeConfig({ kindRoutes: { done: null } as unknown as SettingsPatch }),
    );
    expect(rejected.key).toBe("kindRoutes");
  });

  // 这一条是整段重构的地基：提交**只带一个键**时，存量其余的键必须原样留下。
  // 旧语义（整组替换）下这条会红：落盘只剩 id/type/name，baseUrl 与 deviceKey 一起消失，
  // 频道当场变成一个打不通的空壳。
  it("地基：提交只带 id/type/name 时，存量的其余字段逐字留下（整组替换会把它洗成空壳）", async () => {
    writeConfigFile(diskOf({ ...BARK, name: "旧名", group: "家人", sound: "ding", icon: "i" }));
    assemble();

    const result = await writeConfig({
      channels: [...BUILTINS, { type: "bark", id: "bark:phone", name: "新名" }],
    });
    expect(result.ok).toBe(true);
    expect(channelOfType(diskChannels(), "bark")).toEqual({
      type: "bark",
      id: "bark:phone",
      name: "新名",
      baseUrl: "https://api.day.app",
      deviceKey: "key-1",
      level: "active",
      group: "家人",
      sound: "ding",
      icon: "i",
    });
  });

  // 换型 = 换了一条：字段集随 type 变，按字段继承会把 bark 的 baseUrl 带进 webhook（变陌生键 → 400）。
  it("换型不继承：同 id 改成另一种 type 时，存量那批键不带过去", async () => {
    writeConfigFile(diskOf({ ...BARK, group: "家人" }));
    assemble();

    const result = await writeConfig({ channels: [...BUILTINS, { ...HOOK, id: "bark:phone" }] });
    expect(result.ok).toBe(true);
    const stored = channelOfType(diskChannels(), "webhook");
    expect(stored.baseUrl).toBeUndefined();
    expect(stored.group).toBeUndefined();
    expect(stored.url).toBe("https://example.test/hook");
  });
});

/**
 * 半坏条目不许把用户锁死在设置页外（#1016 S3 的回归修复，端到端经写面本身）。
 *
 * 上一组走的是纯函数链（磁盘 → 视图 → 客户端 → 合并 → 判据），这一组补上**真落盘**那一段：
 * 用户在设置页上点保存，`writeConfig` 会不会 400。前一段全对而这里 400，用户体感仍然是「设置页坏了」。
 *
 * 半坏条目来自**升级之后手改文件**：0.2.9 的形态清理只在刻度推进时跑一次，救不了这条路
 * （该步的职责见 upgrade/impl/steps/canonical-keys.ts）。
 */
describe("半坏存量条目：保存不被锁死（#1016 S3 回归修复）", () => {
  /** 磁盘上的一条半坏 bark：缺 baseUrl——用户在升级之后手改文件造出来的那种形态。 */
  const HALF_BARK = { type: "bark", id: "bark:half", deviceKey: "key-half" } as const;
  /** 磁盘：两条内置 + 一条合法 webhook + 那条半坏 bark。 */
  const HALF_DISK = diskOf(HOOK, HALF_BARK);

  it("改**另一条**频道的名字即保存成功；半坏条目在磁盘上逐字未变（不补 baseUrl、不删键、凭据不回退成掩码）", async () => {
    revisionOfFile(HALF_DISK);
    // 用户改的是那条**合法 webhook** 的名字，与半坏 bark 毫无关系。客户端保存频道域时把整个
    // channels 整组带上（diffSettingsPayload 的 channels 整组语义），那条半坏条目于是也进了提交面
    // ——锁死正是在这一步发生的。只改顶层键反而不触发：提交里没有 channels，判据压根不重判它。
    const submitted = submitOf((channel) => ({ ...channel, name: "群机器人" }), "webhook");
    const result = await writeConfig({ channels: submitted }, readSettingsView().revision);

    expect(result.ok).toBe(true);
    // 半坏条目：存量有的键一条不少、值一字未改，**且没有凭空多出 baseUrl**（写面不猜值）。
    expect(channelById(diskChannels(), "bark:half")).toEqual(HALF_BARK);
    expect("baseUrl" in channelById(diskChannels(), "bark:half")).toBe(false);
    // 前提事实：同一次保存里那条合法 webhook 的改名**确实落盘了**——否则这条可能在测「什么都没发生」。
    expect(channelById(diskChannels(), HOOK.id).name).toBe("群机器人");
  });

  it("视图里看得见那条半坏条目（读面不丢弃），且补上 baseUrl 之后它自此合法", async () => {
    revisionOfFile(HALF_DISK);
    // 前提事实：客户端能看见它——「用户看不见」与「用户改不动」是同一种锁死。
    const shown = channelById(channelsOf(readSettingsView().effective), "bark:half");
    expect(shown.baseUrl).toBeUndefined();
    expect(shown.deviceKey).toBe(MASK);

    // 出路一：把它补全再保存（同一 id 同 type，合并按 id 认这条），不必重启、不必手改文件。
    const submitted = submitOf(
      (channel) =>
        channel.type === "bark" ? { ...channel, baseUrl: "https://api.day.app" } : channel,
      "bark",
    );
    const fixed = await writeConfig({ channels: submitted }, readSettingsView().revision);

    expect(fixed.ok).toBe(true);
    expect(channelById(diskChannels(), "bark:half").baseUrl).toBe("https://api.day.app");
  });

  it("显式删除半坏条目的必填键仍 400（放行的是「存量本就残缺」，不是「删必填键」）", async () => {
    revisionOfFile(HALF_DISK);
    const submitted = submitOf(
      (channel) => (channel.type === "bark" ? { ...channel, baseUrl: null } : channel),
      "bark",
    );
    const error = invalidOf(
      await writeConfig({ channels: submitted }, readSettingsView().revision),
    );
    expect(error.hint).toContain("baseUrl 是必填键，不能删除");
    // 拒绝发生在落盘之前：半坏条目原封不动。
    expect(channelById(diskChannels(), "bark:half")).toEqual(HALF_BARK);
  });

  it("只改顶层键的那次保存不重判 channels —— 这不是「半坏豁免」，是 channels 压根没进提交面", async () => {
    // 记下这条事实是为了不误读上一条：锁死只在**提交面带着 channels** 时才发生（频道域保存 / 全部保存）。
    // 少了它，下一个读代码的人会以为半坏豁免覆盖了「任何一次保存」，而那不是判据的形状。
    revisionOfFile(HALF_DISK);
    const result = await writeConfig({ notifyTaskDone: false }, readSettingsView().revision);

    expect(result.ok).toBe(true);
    expect(channelById(diskChannels(), "bark:half")).toEqual(HALF_BARK);
  });
});

packages/dsh-notifier/test/integration/r.source:
/**
 * dsh-notifier — 组合根（`src/index.ts`）的真实 cordis Context 集成测试。
 *
 * 面口径：这里测的是**宿主看见的那一面**——`apply` 收窄宿主上下文、按序装配八个域、卸载逆序释放；
 * 「按序」里唯一在运行期无观测量的那一段（升级链 await 跑完才轮到读文件的域）以源码文本先后锁定。
 * 这些行为只有放进真实 cordis 才成立：`inject` 门（未就绪不装配）、两条 waterfall 的 `prepend`
 * 链序、`{ global: true }` 的作用域过滤、`ctx.effect` 的卸载时机、`internal/service` 的晚到通知。
 * 假宿主只提供 `webServer`（组合根唯一触碰的宿主服务）与可选的 `settings`；事件总线、落盘、
 * 裁决管线全是真的——**不 mock `@deepseek-ai/cordis`**，也不用 `vi.mock`/`vi.fn`。
 *
 * 落盘隔离（红线）：config / stores / stream 的单例在**模块加载期**就用 `notifierFile()` 定死了
 * 路径，所以必须先把 `DSH_HOME` 指到 `mkdtempSync` 出的临时目录，再用**动态 `import()`** 拉组合根。
 * 写反了本节全部落盘就进真实 `~/.dsh`——那正是正在跑的 `dsh web` 的 home。
 *
 * 写队列纪律：历史与配置的落盘是 fire-and-forget（写队列是模块级字段，`release` 不清它），故每个
 * 产生落盘的用例都要等到自己那一条在磁盘上可见才算完；需要「没有新写入」这类否定判据时，用
 * `stores` 域自己的写口排一次队当**界碑**——队列串行，界碑落盘即此前排队的全部落盘。
 *
 * 时间纪律：本文件不钉系统时钟，`pollUntil` 的 deadline 读的正是 `Date.now()`，钉住它失败会从
 * 「断言红」退化成挂死。`afterEach` 仍还原一次，防将来有人在用例里钉。
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { Context } from "@deepseek-ai/cordis";
import type { Events, Fiber, ThisType as EventThis } from "@deepseek-ai/cordis";
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { Session, SessionEvent } from "@deepseek-ai/dsh-session";
import type { ApprovalOutcome, ApprovalRequest } from "@deepseek-ai/dsh-user-approval";
import type {
  AskUserQuestionAnswer,
  AskUserQuestionRequest,
} from "@deepseek-ai/dsh-user-questions";

import {
  assertEventReachability,
  assertRealCordisContextSemantics,
} from "../../../../test/smoke-lib.ts";
import { DEFAULT_CONFIG } from "../../src/server/config/impl/model/index.ts";
import { pollUntil, settleMicrotasks, tempDshHome } from "../helpers.ts";

// DSH_HOME 必须先于被测模块求值：三个单例的落盘路径在构造时定下，而静态 import 会在任何语句
// 之前执行——顺序反了，本节全部落盘就写进真实 `~/.dsh`。
const home = tempDshHome();
const notifier = await import("../../src/index.ts");
const apiApi = await import("../../src/server/api/interface.ts");
const configApi = await import("../../src/server/config/interface.ts");
const sdkApi = await import("../../src/server/sdk/interface.ts");
const storesApi = await import("../../src/server/stores/interface.ts");
const sharedApi = await import("../../src/server/shared/interface.ts");

/** 本插件的落盘位置（新布局：包私有目录，见 `shared/paths.ts`）。 */
const storageDir = join(home.dir, "@wingsky-1", "dsh-notifier");
const configFile = sharedApi.notifierFile(sharedApi.CONFIG_FILE_NAME);
const historyFile = sharedApi.notifierFile(sharedApi.HISTORY_FILE_NAME);
const seqFile = sharedApi.notifierFile(sharedApi.SEQ_FILE_NAME);
const versionFile = sharedApi.notifierFile(sharedApi.VERSION_FILE_NAME);

/** 种下的那份配置的原文：否定判据用它比对「一个字节都没动过」。 */
function seededConfig(): string {
  return `${JSON.stringify(BASE_SETTINGS, null, 2)}\n`;
}

/** 宿主契约冻结的 8 条浏览器端点（客户端锁定，独立抄写才守得住改路径）。 */
const ROUTE_PATHS: readonly string[] = [
  "/api/dsh-notifier/config",
  "/api/dsh-notifier/history",
  "/api/dsh-notifier/status",
  "/api/dsh-notifier/kinds",
  "/api/dsh-notifier/test",
  "/api/dsh-notifier/health",
  "/api/dsh-notifier/diagnostics",
  "/api/dsh-notifier/events",
];

/**
 * 基础设置：系统出口整个关掉、浏览器出口只弹不响。
 *
 * 系统出口在 Linux 会真的 spawn `notify-send`——测试不该在开发机上弹通知；浏览器出口的帧则
 * 经组合根的 `FrameBus` 进 api 域的流（只写 `seq.json`），是本文件观察「帧走出去了」的唯一手段。
 * 两条内置频道的形态**显式写出来**：`enabled` 是频道唯一的投递闸门，靠 `systemNotify:false`
 * 之类的弹窗键关不掉它（那只让出口无事可做，仍会留下一条 skipped 明细）。
 * `historyMaxAgeDays` 取**非默认值**：逆序释放那条判据要一个与默认值不同的可辨读数。
 */
const BASE_SETTINGS = {
  channels: [
    {
      type: "browser",
      id: "browser",
      enabled: true,
      popup: true,
      sound: false,
      whenVisible: false,
    },
    { type: "system", id: "system", enabled: false, popup: false, sound: false },
  ],
  historyMaxAgeDays: 7,
} as const;

/** 历史行：只取本文件当判据的字段（整体比较会把域内文案变化变成假红）。 */
interface HistoryLine {
  kind?: string;
  message?: string;
  suppressed?: string;
  channels?: ReadonlyArray<{ channelId: string; status: string }>;
}

/** 磁盘上的历史记录。 */
function historyLines(): HistoryLine[] {
  let text: string;
  try {
    text = readFileSync(historyFile, "utf8");
  } catch {
    return [];
  }
  return text
    .split("\n")
    .filter(Boolean)
    .flatMap((line) => {
      try {
        return [JSON.parse(line) as HistoryLine];
      } catch {
        // 坏行不当判据，也不吞掉同行之外的记录
        return [];
      }
    });
}

/** 某一种通知落了几条。 */
function countKind(kind: string): number {
  return historyLines().filter((line) => line.kind === kind).length;
}

/** 磁盘上第一条某一种通知：`beforeEach` 清过历史，所以不受上一个用例干扰。 */
function kindLine(kind: string): HistoryLine | undefined {
  return historyLines().find((line) => line.kind === kind);
}

/** 界碑用的种类名：只出现在界碑行里，任何通知判据都不会撞上它。 */
const SENTINEL_KIND = "itest-sentinel";

/**
 * 排一次界碑并等它落盘，用来给**否定**判据划界。
 *
 * 写队列串行，界碑在磁盘上可见即此前排队的写入全部落盘；没有界碑的「没有新记录」只是抢跑得来的
 * ——它证明的是「还没写完」，不是「不会写」。
 */
async function settleHistory(): Promise<void> {
  storesApi.appendHistory({ ts: Date.now(), kind: SENTINEL_KIND, title: "界碑", message: "-" });
  await pollUntil(() => historyLines().some((line) => line.kind === SENTINEL_KIND), "界碑落盘");
}

/** 浏览器出口的序号：`seq.json` 前进一格 = 帧真的走完了 FrameBus → api 域 → 流。 */
function seqValue(): number {
  try {
    const parsed = Number.parseInt(readFileSync(seqFile, "utf8").trim(), 10);
    return Number.isFinite(parsed) ? parsed : 0;
  } catch {
    return 0;
  }
}

/**
 * 本用例的序号锚点（每轮 +1000）。
 *
 * 序号是 fire-and-forget 写，「等于锚点 +1」这类判据要挡得住上一个用例迟到的那一笔——递增的锚点
 * 让迟到的值必然小于本轮的起点，于是「文件里出现了本轮的格子」只可能由本轮自己的广播产生。
 */
let seqAnchor = 0;

function seedSeqAnchor(): void {
  seqAnchor += 1000;
  mkdirSync(dirname(seqFile), { recursive: true });
  writeFileSync(seqFile, `${seqAnchor}\n`);
}

/** 写一份设置文件（组合根装配时同步读它，故必须用同步写）。 */
function seed(settings: Record<string, unknown>): void {
  mkdirSync(dirname(configFile), { recursive: true });
  writeFileSync(configFile, `${JSON.stringify(settings, null, 2)}\n`);
}

/** 假会话日志条目：本块只读 `type` 与 `data`（与 events 域单测同一口径）。 */
function turnEndEvent(turn: number, kind: string): SessionEvent {
  return { type: "turn/end", data: { turn, reason: { kind } } } as unknown as SessionEvent;
}

/** 假 agent：只露出 events 域真的会读的几处（`id` 与 `session` 的 header / 日志快照）。 */
function fakeAgent(
  id: string,
  events: SessionEvent[] = [],
  header: Record<string, unknown> = {},
): Agent {
  return {
    id,
    session: { header, snapshotEvents: () => events },
  } as unknown as Agent;
}

/** 假会话：`session/event` 的载荷带整份会话对象，而本插件只用它的 `id`。 */
function fakeSession(id: string): Session {
  return { id } as unknown as Session;
}

/**
 * 宿主按作用域派发时传的 `this`：`agent/*` 声明的是 `Scoped<Agent>`、`session/event` 是
 * `Scoped<Session>`，而那个 brand 不是本包的依赖，故从事件签名上取 `this` 位。测试要造的正是
 * `{ [Context.filter]: … }` 这一个成员——直接抄 `Scoped<…>` 会把它变成第二份事实源。
 */
type ScopedThis<K extends keyof Events> = EventThis<Events[K]>;

/** 作用域收紧的派发载体：filter 恒假，于是**只有** `{ global: true }` 的订阅能收到。 */
function scopeRejecting<K extends keyof Events>(): ScopedThis<K> {
  return { [Context.filter]: () => false } as unknown as ScopedThis<K>;
}

/**
 * 假 settings 服务只提供 describe 低优先级兜底；正式历史来源由 upgrade 域直接读取 DSH_HOME 双文件。
 * `describe()` 在真实宿主里只列**已注册**的命名空间，所以这里的 `user` 用三种取值对应三种真实形态：
 * `undefined` = 没注册这条命名空间（新架构的常态，服务面读不到）；`{}` = 注册了但 user 层为空；有键 = 注册且用户设过。
 */
function fakeSettings(user: Record<string, unknown> | undefined): { describe: () => unknown[] } {
  return {
    describe: () => (user === undefined ? [] : [{ ns: "dsh-notifier", user }]),
  };
}

/**
 * 假宿主 webServer：只实现组合根够得着的那一面（`register`），并记下摘除时的现场。
 *
 * `failAt` 让第 N 条摘除器抛错——宿主摘路由失败是真实会发生的（路由已被别人摘掉、宿主换实现），
 * 组合根的释放壳对它的承诺是「不阻断其余」。
 */
function fakeWebServer(
  observe: () => { configDays: number; serviceAlive: boolean },
  options: { failAt?: number } = {},
) {
  const routes: WebRoute[] = [];
  const removals: Array<{ path: string; configDays: number; serviceAlive: boolean }> = [];
  const service = {
    register(route: WebRoute) {
      routes.push(route);
      return () => {
        removals.push({ path: route.path, ...observe() });
        if (removals.length === options.failAt) throw new Error(`摘除失败：${route.path}`);
      };
    },
  } as unknown as Context["webServer"];
  return { service, routes, removals };
}

/** 假宿主 agent 注册表：只实现组合根读的两处（`get` 与 `isOwnedBy`）。 */
function fakeAgents(parent: Agent, child: Agent): Context["agents"] {
  return {
    get: (id: string) => (id === parent.id ? parent : undefined),
    isOwnedBy: (id: string, owner: Agent) => id === child.id && owner === parent,
  } as unknown as Context["agents"];
}

/**
 * 日志出口：`LoggerService` 的公开扩展点，用它把 warn 收进数组。
 *
 * 为什么不读内置的 `ctx.logger.buffer`：那个出口的阈值是 INFO，warn（级别 2）落在它之外，
 * buffer 里永远看不到本文件的判据文案。阈值按 `levels.default` 给——它是出口自己的约定。
 */
function captureWarnings(root: Context): string[] {
  const warnings: string[] = [];
  root.logger.exporter({
    levels: { default: 2 },
    export: (message) => {
      if (message.type === "warn") warnings.push(String(message.args[0]));
    },
  });
  return warnings;
}

/** 一次挂载的全部观测物。 */
interface Mounted {
  readonly root: Context;
  readonly fiber: Fiber;
  readonly host: ReturnType<typeof fakeWebServer>;
  /** 宿主日志出口收到的 warn 文案（组合根只经它报错）。 */
  readonly warns: string[];
  unmount(): Promise<void>;
}

/** 已挂载但用例没显式卸载的实例：`afterEach` 兜底收掉，免得路由/心跳漏到下一个用例。 */
let live: Fiber | null = null;

/**
 * 按宿主的真实挂载顺序装配：先 provide 宿主服务，再 `ctx.plugin(插件)`。
 *
 * `settings` 是本插件的**显式依赖**（组合根的 `inject`）：宿主保证它在插件装配前就绪，所以这里
 * 总是先 provide 一个假的；`settings` 的值就是那份 0.2.3 存量命名空间的 user 层（缺省 = 有服务
 * 但没存量）。「服务没来」这条分支已不属于本插件——它变成 cordis 的 inject 门（见 inject 门用例）。
 * `services` 是其余宿主服务（如 `agents`）——装与不装是两条不同的判定路径。
 */
async function mount(options: {
  config?: { enabled?: boolean };
  settings?: Record<string, unknown>;
  services?: Record<string, unknown>;
}): Promise<Mounted> {
  const root = new Context();
  root.provide("settings", fakeSettings(options.settings));
  for (const [name, value] of Object.entries(options.services ?? {})) root.provide(name, value);
  const warns = captureWarnings(root);
  const host = fakeWebServer(() => ({
    configDays: configApi.readConfig().historyMaxAgeDays,
    serviceAlive: root.get("wingsky.notifier", false) !== undefined,
  }));
  root.provide("webServer", host.service);
  const fiber = await root.plugin(notifier, options.config);
  live = fiber;
  return {
    root,
    fiber,
    host,
    warns,
    unmount: async () => {
      live = null;
      await fiber.dispose();
    },
  };
}

/**
 * 模拟宿主内置 answerer：链上**更早注册**的那一个，它给出的判定就是这次请求的最终结果。
 * 它不调 `next()`——宿主自己的应答者拿到判定后即短路，这正是本插件必须 prepend 的理由。
 */
async function mountApprovalAnswerer(
  root: Context,
  calls: string[],
  outcome: ApprovalOutcome,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("approval/request", () => {
      calls.push("answerer");
      return Promise.resolve(outcome);
    });
  });
}

/** 同上，提问那条链上的 answerer（两条 waterfall 同构，夹具分开写以免一条覆盖另一条）。 */
async function mountQuestionAnswerer(
  root: Context,
  calls: string[],
  answer: AskUserQuestionAnswer,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("user-questions/request", () => {
      calls.push("answerer");
      return Promise.resolve(answer);
    });
  });
}

beforeEach(() => {
  // 单例的落盘路径跨用例不变，能重置的只有文件：不重置的话上一个用例的配置/历史就是本用例的起点。
  rmSync(historyFile, { force: true });
  rmSync(configFile, { force: true });
  // 正式历史来源也落在这个共享的临时 DSH_HOME 里；清掉双文件，避免上个用例的存量进入下个用例。
  rmSync(join(home.dir, "settings.yaml.imported"), { force: true });
  rmSync(join(home.dir, "settings.yaml"), { force: true });
  seedSeqAnchor();
  seed(BASE_SETTINGS);
});

afterEach(async () => {
  vi.useRealTimers();
  if (live) {
    const fiber = live;
    live = null;
    await fiber.dispose();
  }
  // 无条件补一次 api 域收尾：域释放幂等，正常用例上是空转。不放在用例里是因为用例前面任何一条
  // 断言红了就会跳过补偿（路由/心跳会漏到下一个用例，症状是「上一条用例弄脏了这条」）。
  apiApi.releaseApi();
});

afterAll(() => {
  home.dispose();
});

describe("装配与暴露", () => {
  it("装配即暴露：服务面挂在宿主上下文上（声明合并的读法可用），登记与发送当场可用", async () => {
    const { root, fiber, unmount } = await mount({});
    // 声明合并的读法可用，而且读到的是**同一个**对象：服务面经 `ctx.provide` 挂在宿主上下文上，
    // 不是又造了一份（再造一份就会有两个 apiVersion、两套登记表）。
    const service = root.get("wingsky.notifier", false);
    expect(fiber.ctx["wingsky.notifier"]).toBe(service);
    expect(service?.apiVersion).toBe(2);
    // 管理面（清单 / 确认）不进服务面：多给一样，兄弟插件就能替用户放行自己的通知种类。
    expect("confirmKind" in (service ?? {})).toBe(false);

    service?.registerKind({ id: "itest:face", label: "集成测试" });
    expect(sdkApi.listKinds()).toContainEqual({
      id: "itest:face",
      label: "集成测试",
      confirmed: false,
    });
    // 未确认的外部种类：送进的是真管线，出去的是一条「unlisted」归档（不是静默丢弃）。
    await service?.send({ kind: "itest:face", body: "正文" });
    await pollUntil(() => countKind("itest:face") === 1, "登记后的发送落史");
    expect(kindLine("itest:face")?.suppressed).toBe("unlisted");

    await unmount();
    // 卸载后消费方按「通知中心不在」降级：`get` 拿空而不是拿到半死对象。
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
  });

  it("inject 门：两条宿主服务（webServer / settings）都就绪才装配，缺一条都不跑", async () => {
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    const fiber = await root.plugin(notifier);
    live = fiber;

    // 缺依赖时的现场：插件没跑（路由为空、服务面没上），也没有装配失败的声音。
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();

    // 只补一条还不够：settings 是显式依赖（存量配置的读取面），缺它时装配体一步都不该走。
    root.provide("webServer", host.service);
    await settleMicrotasks();
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();

    root.provide("settings", fakeSettings({}));
    await fiber.await();
    expect(host.routes.map((route) => route.path)).toHaveLength(8);
    expect(root.get("wingsky.notifier", false)?.apiVersion).toBe(2);
  });

  /**
   * 宿主契约 canary——**不是本插件的判据**：两个共用 helper 都只在自己临时挂的监听器上断言 cordis
   * 的语义（未注入访问抛错 / 缺位 get 安全 / effect 真实清理 / 作用域过滤只放行 global），
   * 它们不触本插件的任何代码。放在一个用例里是因为两者共用同一次装配，判据互不相干。
   */
  it("宿主契约 canary：真实 Context 语义 + `{global:true}` 的作用域过滤语义（非本插件行为判据）", async () => {
    const { fiber, unmount } = await mount({});
    // 插件 fiber 的运行时上下文才是「真实」的那一份：root 语义下未注入访问会静默给 undefined，
    // 断言①在那里恒真——历史教训（根因 A：fake-ctx 把服务当普通属性注入）正是靠这条堵住的。
    // 断恒等而非断存在：`root.fiber` 也存在，只有插件 fiber 才带 `runtime`（根为 null）。
    expect(fiber.ctx.fiber).toBe(fiber);
    assertRealCordisContextSemantics(fiber.ctx);
    assertEventReachability(fiber.ctx, Context, "agent/status", {
      agent: fakeAgent("itest-reach"),
      status: "running",
    });
    await unmount();
  });

  it("挂载点总开关 enabled:false 抵达裁决层：请求照进管线，但记的是 disabled 而不是照常投递", async () => {
    const { root, unmount } = await mount({ config: { enabled: false } });
    root.emit("agent/error", {
      agent: fakeAgent("itest-disabled"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });
    await pollUntil(() => countKind("error") === 1, "总开关关闭时的归档");
    expect(kindLine("error")?.suppressed).toBe("disabled");
    // 关掉的是「投递」，不是「记录」：帧的写排在归档之前，归档已在磁盘上时序号若前进过就已可见
    // ——所以这里断「没走到下一格」而不是「等于锚点」，免得受上一个用例迟到的那一笔影响。
    expect(seqValue()).not.toBe(seqAnchor + 1);
    await unmount();
  });
});

/**
 * 装配顺序（源码序锁定）：升级链必须 await 跑完，才轮到任何读文件的域。
 *
 * 为什么只能钉源码顺序：运行期能观测到的只有「apply 返回时链已跑完」，而各域的**装配先后**在运行期
 * 没有观测量——把它挪到 config/stores 之后，变坏的只是「各域读着被搬走一半的磁盘跑起来」这件事，
 * 假 ctx 装配照样成功。组合根里唯一可判的形态就是源码文本的先后（同先例：
 * dsh-provider-usage test/integration/report-routes/composition-root.test.ts 的装配序锁定）。
 */
describe("装配顺序：升级链 await 跑完才装其它域", () => {
  const applySrc = readFileSync(
    join(dirname(fileURLToPath(import.meta.url)), "..", "..", "src", "index.ts"),
    "utf8",
  );

  it("升级域是 await 装配方（漏掉 await 即红）", () => {
    expect(applySrc.indexOf("await installUpgrade({")).toBeGreaterThan(-1);
  });

  it("先复位 upgrade 装配标记再装配（release 晚于 install 即红）", () => {
    const release = applySrc.indexOf("releaseUpgrade();");
    const install = applySrc.indexOf("await installUpgrade({");
    expect(release).toBeGreaterThan(-1);
    expect(release).toBeLessThan(install);
  });

  it("升级链早于 config 域（迁移必须早于任何读文件的域）", () => {
    const install = applySrc.indexOf("await installUpgrade({");
    const config = applySrc.indexOf("configApi.installConfig(");
    expect(install).toBeGreaterThan(-1);
    expect(config).toBeGreaterThan(-1);
    expect(install).toBeLessThan(config);
  });
});

describe("宿主路由注册与摘除", () => {
  it("apply 期间宿主收到恰好 8 条 exact 路由，路径集合就是客户端锁定的那一份", async () => {
    const { host, unmount } = await mount({});
    expect(host.routes.map((route) => route.path).sort()).toEqual([...ROUTE_PATHS].sort());
    expect(host.routes.every((route) => route.kind === "exact")).toBe(true);
    expect(host.removals).toHaveLength(0);
    await unmount();
  });

  it("卸载摘除全部 8 条路由，重复卸载不再摘第二次（卸载链可能走到不止一次）", async () => {
    const { host, fiber, unmount } = await mount({});
    await unmount();
    expect(host.removals.map((removal) => removal.path).sort()).toEqual([...ROUTE_PATHS].sort());

    await fiber.dispose();
    expect(host.removals).toHaveLength(ROUTE_PATHS.length);
  });
});

describe("waterfall 契约（审批 / 提问）", () => {
  it("approval/request：链头可达，且 next() 把判定原样交还给更早注册的短路 answerer", async () => {
    const root = new Context();
    const calls: string[] = [];
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    // 宿主的形态：内置 answerer 在本插件之前注册，并且**不调 next()**（GUI 应答后即短路）。
    await mountApprovalAnswerer(root, calls, "rejected");
    const fiber = await root.plugin(notifier);
    live = fiber;
    // 反向固化：不带 prepend 的后来者排在这个短路 answerer 之后，整条链对它不可见。
    const control: string[] = [];
    root.on("approval/request", async () => {
      control.push("late");
      return "cancelled";
    });

    const request = { toolName: "bash", reason: "要写文件" } as unknown as ApprovalRequest;
    const outcome = await root.waterfall("approval/request", request, async () => "unavailable");

    // ② 链路结果没被吞：最终判定仍来自 answerer（插件自己返回 undefined 时这里会是 undefined）。
    expect(outcome).toBe("rejected");
    // ③ answerer 确实被调用：插件的 next() 真的把判定交了回来。
    expect(calls).toEqual(["answerer"]);
    // ① 插件的处理器被调用：可达性只有它自己的副作用能证明（审批通知落史）。
    await pollUntil(() => countKind("ask") === 1, "审批通知落史");
    // 反向固化：同一个事件、同一次派发里，后注册的无 prepend 监听器被短路挡在外面。
    // （`control` 空是**夹具前提**——answerer 短路后链不再往下走，不是本插件的判据。）
    expect(control).toEqual([]);
    await fiber.dispose();
    live = null;
  });

  it("user-questions/request：第二条 waterfall 与审批同构（同一个链头与交还契约）", async () => {
    const root = new Context();
    const calls: string[] = [];
    const answer: AskUserQuestionAnswer = { answers: [{ id: "q1", selected: ["是"] }] };
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    await mountQuestionAnswerer(root, calls, answer);
    const fiber = await root.plugin(notifier);
    live = fiber;

    // 只给必需的 questions：形状合法，值与文案无关（文案归 translate 域的单测）。
    const request: AskUserQuestionRequest = { questions: [{ id: "q1", question: "选哪个？" }] };
    const outcome = await root.waterfall("user-questions/request", request, async () => ({
      answers: [],
    }));

    // 交还的是 answerer 的**整份**判定，不是被本插件加工过的形状。
    expect(outcome).toEqual(answer);
    expect(calls).toEqual(["answerer"]);
    await pollUntil(() => countKind("question") === 1, "提问通知落史");
    await fiber.dispose();
    live = null;
  });

  it("guard：处理器内部抛错不向宿主抛——提问链路照旧交出判定，只留一条 warn", async () => {
    const root = new Context();
    const calls: string[] = [];
    const warns = captureWarnings(root);
    const answer: AskUserQuestionAnswer = { answers: [{ id: "q1", selected: ["是"] }] };
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    await mountQuestionAnswerer(root, calls, answer);
    const fiber = await root.plugin(notifier);
    live = fiber;

    // 上游形状漂移：一条缺 `question` 文本的提问。它在编译期本就被拦住，而守卫存在的理由正是
    // 编译期管不到的那一侧——载荷跨宿主边界不受信。
    const drifted = { questions: [{ id: "q1" }] } as unknown as AskUserQuestionRequest;

    // 宿主链不被打断：本插件只是旁观者，抛出去会让 next() 不被调用（症状是「提问框不弹了」）。
    const outcome = await root.waterfall("user-questions/request", drifted, async () => ({
      answers: [],
    }));
    expect(outcome).toEqual(answer);
    expect(calls).toEqual(["answerer"]);

    // 不静默：文案只此一处，吞掉之后「通知不工作」会变成查不出原因的现象。
    const guardWarn = warns.find((line) => line.includes("宿主事件处理失败"));
    expect(guardWarn?.startsWith("dsh-notifier: 宿主事件处理失败 —— ")).toBe(true);

    // 同一层壳的另一支：宿主抛出来的可以**不是** Error（官方那边失败类型本就是 unknown），
    // 文案得照样出得来，而不是把一次宿主异常消化成空字符串。
    const hostile = {
      get toolName(): string {
        throw "宿主抛出的字符串";
      },
    } as unknown as ApprovalRequest;
    const second = await root.waterfall("approval/request", hostile, async () => "unavailable");
    expect(second).toBe("unavailable");
    expect(warns.some((line) => line.endsWith("宿主抛出的字符串"))).toBe(true);
    await fiber.dispose();
    live = null;
  });
});

describe("宿主事件可达性", () => {
  it("多会话派发下本插件的订阅仍可达：漏掉 {global:true} 的表现是「有些会话不通知」", async () => {
    const { root, unmount } = await mount({});
    const control: string[] = [];
    // 对照：同一个事件、同一次派发，没有 {global:true} 的订阅会被作用域过滤掉。
    // （`control` 空是**夹具前提**——cordis 的 filter 真的在拒人，不是本插件的判据。）
    root.on("agent/error", () => {
      control.push("untagged");
    });

    // 宿主按 agent 作用域派发时传的就是这样一个 thisArg（filter 决定哪些订阅可见）。
    const scoped = scopeRejecting<"agent/error">();
    root.emit(scoped, "agent/error", {
      agent: fakeAgent("itest-scope"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });

    await pollUntil(() => countKind("error") === 1, "作用域收紧下仍到达管线");
    // （`control` 空是**夹具前提**——cordis 的 filter 真的在拒人，不是本插件的判据。）
    expect(control).toEqual([]);
    await unmount();
  });

  /**
   * 余下四条全局订阅**各自**可证伪：上面 `agent/error` 那条只覆盖了一条订阅，而宿主契约 canary 里
   * 的 `assertEventReachability` 测的是 cordis 的过滤语义本身（它自己临时挂监听器），都没能证明这
   * 四条带没带 `{global:true}`——**旧版同名文件是靠扫 `src/index.ts` 源码文本断言「全部 `ctx.on`
   * 注册处带 `{global:true}`」的**（还带 `// @ts-nocheck`），重写改成纯运行时行为后这块守卫缺了一
   * 个口子，下面就是它的行为版替身。四条写在同一个用例里是为了省掉四次装配，但每一段都独立成立：
   * 删掉对应那行的 `GLOBAL_LISTEN`，只有该段会红。
   */
  it("四条全局订阅各自可证伪（旧源码文本扫描的行为版替身）：收紧派发下状态 / 会话 / turn / 消亡都仍到达", async () => {
    const { root, unmount } = await mount({});
    // agent/* 共用同一个 this 位类型，会话那条在会话那一侧，故造两个载体。
    const scopedAgent = scopeRejecting<"agent/status">();
    const scopedSession = scopeRejecting<"session/event">();
    const signal = new AbortController().signal;

    // ① agent/status：两跳判定照旧产出完成通知（证据取自日志快照，与会话推送无关）。
    const statusEvents: SessionEvent[] = [];
    const statusAgent = fakeAgent("itest-scope-status", statusEvents);
    root.emit(scopedAgent, "agent/status", { agent: statusAgent, status: "running" });
    statusEvents.push(turnEndEvent(1, "completed"));
    root.emit(scopedAgent, "agent/status", { agent: statusAgent, status: "idle" });
    await pollUntil(() => countKind("done") === 1, "① 作用域收紧下 agent/status 仍产出完成通知");

    // ② session/event：这条会话的日志快照是空的，完成判定只能靠推送来的那笔证据——收不到就没有通知。
    // 用「比前一段多一条」而不是绝对值：这一段的成立与否不该被上一段的条数绑住。
    const doneBeforePush = countKind("done");
    const pushAgent = fakeAgent("itest-scope-session");
    root.emit(scopedAgent, "agent/status", { agent: pushAgent, status: "running" });
    root.emit(
      scopedSession,
      "session/event",
      fakeSession("itest-scope-session"),
      turnEndEvent(1, "completed"),
    );
    root.emit(scopedAgent, "agent/status", { agent: pushAgent, status: "idle" });
    await pollUntil(
      () => countKind("done") === doneBeforePush + 1,
      "② 作用域收紧下 session/event 的推送证据仍被记账",
    );

    // ③ agent/turn-stopping：同一 turn 只发一次（去重状态机在收紧的派发下也要吃到这两跳）。
    // 本段只证明「到达并被记账」：本例的 notifyTurnEnd 是默认的 false，所以这条 turn-end 是以
    // suppressed 落的史——它分不出「发了」与「被压制」，投递面的判据在下面那条用例里。
    const turnAgent = fakeAgent("itest-scope-turn");
    root.emit(scopedAgent, "agent/turn-stopping", { agent: turnAgent, turn: 7, signal });
    await pollUntil(() => countKind("turn-end") === 1, "③ 作用域收紧下 turn 边界仍到达状态机");
    expect(kindLine("turn-end")?.suppressed).toBe("kind-off");
    root.emit(scopedAgent, "agent/turn-stopping", { agent: turnAgent, turn: 7, signal });
    await settleHistory();
    expect(countKind("turn-end")).toBe(1);

    // ④ agent/disposed：清账把那笔去重记录抹掉，否则同一个 id 复用后这一 turn 永远不再通知。
    const disposed = scopeRejecting<"agent/disposed">();
    root.emit(disposed, "agent/disposed", { agent: turnAgent });
    root.emit(scopedAgent, "agent/turn-stopping", { agent: turnAgent, turn: 7, signal });
    await pollUntil(() => countKind("turn-end") === 2, "④ 作用域收紧下消亡事件仍清账");
    await unmount();
  });

  it("agent/error：真实 emit 到达管线，错误原文经组合根收窄成文本落进历史", async () => {
    const { root, unmount } = await mount({});
    root.emit("agent/error", {
      agent: fakeAgent("itest-error"),
      turn: 2,
      step: 3,
      error: new Error("磁盘满了"),
    });
    // 宽类型（unknown）在这里做唯一一次收窄：域内拿到的必须是可展示的文本。
    root.emit("agent/error", {
      agent: fakeAgent("itest-error"),
      turn: 2,
      step: 4,
      error: 42,
    });
    await pollUntil(() => countKind("error") === 2, "两条错误通知落史");
    const lines = historyLines().filter((line) => line.kind === "error");
    expect(lines).toHaveLength(2);
    // 收窄的两支：Error 取 `message`，非 Error 用 `String()`。判据必须咬住「取 message」这个动作——
    // 正文模板是 `…：${文本}`，而 `String(new Error("磁盘满了"))` 是 `"Error: 磁盘满了"`，
    // 只断包含「磁盘满了」的话两种写法都过（恒真），故断紧贴前缀冒号的那一段 + 反断整对象形态。
    const messages = lines.map((line) => line.message ?? "").join("\n");
    expect(messages).toContain("：磁盘满了");
    expect(messages).not.toContain("Error: 磁盘满了");
    expect(messages).toContain("42");
    await unmount();
  });

  it("agent/status：裸 idle 不发通知，running→idle 两跳且日志里有本轮新证据才产出 done", async () => {
    const { root, unmount } = await mount({});
    // 会话日志是一段可增长的快照，本轮结束的证据在 running 之后才追加进来。
    // 「进入 running 时日志里已有的 turn/end 是上一轮的、不许当成本轮完成」（`证据源=快照冻结`）
    // 有专门的主：`test/unit/events/listen.test.ts`，此处不重复覆盖。
    const events: SessionEvent[] = [];
    const agent = fakeAgent("itest-done", events);

    // 「只有 running 被看见过，idle 才算一轮结束」这条已由 test/unit/events/listen.test.ts 单测
    // 守死（那边还多断了一条「不留诊断」），这里只走本层独有的两跳：running → turn/end → idle。
    root.emit("agent/status", { agent, status: "running" });
    events.push(turnEndEvent(1, "completed"));
    root.emit("agent/status", { agent, status: "idle" });
    await pollUntil(() => countKind("done") === 1, "完成通知落史");
    await unmount();
  });

  it("session/event：推送的 turn/end 被记账，缺了它完成判定退化成不发（唯一可辨的副作用）", async () => {
    const { root, warns, unmount } = await mount({});
    // 快照里没有 turn/end：完成判定只能靠 session/event 推来的那一条证据。
    const agent = fakeAgent("itest-push");
    const session = fakeSession("itest-push");

    root.emit("agent/status", { agent, status: "running" });
    root.emit("agent/status", { agent, status: "idle" });
    await pollUntil(
      () => warns.some((line) => line.includes("完成判定跳过")),
      "无证据时的跳过诊断",
    );
    expect(countKind("done")).toBe(0);

    root.emit("agent/status", { agent, status: "running" });
    root.emit("session/event", session, turnEndEvent(1, "completed"));
    root.emit("agent/status", { agent, status: "idle" });
    await pollUntil(() => countKind("done") === 1, "推送证据驱动的完成通知");
    await unmount();
  });

  it("agent/turn-stopping 与 agent/disposed：同一 turn 只发一次，agent 消亡后清账", async () => {
    seed({ ...BASE_SETTINGS, notifyTurnEnd: true });
    const { root, unmount } = await mount({});
    const agent = fakeAgent("itest-turn");
    const signal = new AbortController().signal;

    root.emit("agent/turn-stopping", { agent, turn: 7, signal });
    await pollUntil(() => countKind("turn-end") === 1, "turn-end 落史");

    // 落史本身只证明「事件到了状态机并写了一行」：notifyTurnEnd 关着时同一条也会以 turn-end 落史，
    // 只是带 suppressed。投递面要有自己的判据——出站明细与浏览器帧的序号。
    const delivered = kindLine("turn-end");
    expect(delivered?.suppressed).toBeUndefined();
    expect(delivered?.channels).toEqual([{ channelId: "browser", status: "ok" }]);
    await pollUntil(() => seqValue() === seqAnchor + 1, "帧经 FrameBus 出去");

    // 同一 turn 再来一次：去重状态机在真实事件链上也要成立（否则每步都弹一条）。
    root.emit("agent/turn-stopping", { agent, turn: 7, signal });
    // 界碑划界：不然「没有第二条」是抢跑得来的。
    await settleHistory();
    expect(countKind("turn-end")).toBe(1);

    // 消亡事件清掉去重记录：否则同一 id 复用后这一 turn 永远不再通知。
    root.emit("agent/disposed", { agent });
    root.emit("agent/turn-stopping", { agent, turn: 7, signal });
    await pollUntil(() => countKind("turn-end") === 2, "清账后同一 turn 可再发");
    await unmount();
  });

  it("浏览器出口拿到帧：投递经组合根 FrameBus 走到 api 域，序号前进一格", async () => {
    const { root, unmount } = await mount({});
    root.emit("agent/error", {
      agent: fakeAgent("itest-frame"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });
    await pollUntil(() => countKind("error") === 1, "投递归档");
    // 序号只在 api 域订阅到帧之后才前进：这一格同时证明 FrameBus 的 emit 与 onFrame 两端接上了。
    await pollUntil(() => seqValue() === seqAnchor + 1, "帧经 FrameBus 出去");
    const delivered = kindLine("error")?.channels?.[0];
    expect(delivered?.channelId).toBe("browser");
    expect(delivered?.status).toBe("ok");
    await unmount();
  });
});

describe("宿主 agent 注册表（子代理归属）", () => {
  it("注册表缺位：带 parentSession 的会话按主任务处理（宁可多报一条 done，不静默用户自己的任务）", async () => {
    const { root, unmount } = await mount({});
    // header 有 parentSession，但宿主没装 agents 服务：`ctx.get("agents", false)` 必须缺位安全，
    // 而不是抛错或把「查不到」当成「是子代理」——后者会让子代理的完成通知永远发不出去。
    const events: SessionEvent[] = [];
    const child = fakeAgent("itest-orphan", events, { parentSession: "itest-gone" });

    root.emit("agent/status", { agent: child, status: "running" });
    events.push(turnEndEvent(1, "completed"));
    root.emit("agent/status", { agent: child, status: "idle" });
    await pollUntil(() => countKind("done") === 1, "查不到父 agent 时按主任务报完成");
    expect(countKind("subagent-done")).toBe(0);
    await unmount();
  });

  it("注册表有据：确由父 agent 创建的会话落 subagent-done，而不是当成主任务再报一次", async () => {
    const parent = fakeAgent("itest-parent");
    const events: SessionEvent[] = [];
    const child = fakeAgent("itest-child", events, { parentSession: "itest-parent" });
    const { root, unmount } = await mount({ services: { agents: fakeAgents(parent, child) } });

    root.emit("agent/status", { agent: child, status: "running" });
    events.push(turnEndEvent(1, "completed"));
    root.emit("agent/status", { agent: child, status: "idle" });
    // 两跳判定的产物只有 kind 能区分：`done` 会让每个子代理都伪装成用户的主任务。
    await pollUntil(() => countKind("subagent-done") === 1, "子代理完成通知落史");
    expect(countKind("done")).toBe(0);
    await unmount();
  });
});

describe("宿主 settings 服务：装配期同步割接存量配置", () => {
  /**
   * 链跑完之后磁盘上两条内置条目的形态（0.2.4 割接 + 0.2.9 形态清理的**终态**）。
   *
   * 逐字取自默认表而不是手抄：0.2.9 的补齐值就是默认表的值（#1016 P1-1），同源由 steps.test.ts 钉住。
   * `over` 用来表达「用户当年在旧顶层键上表过态」的字段——它必须是**用户那个值**而不是默认值，
   * 否则这条用例就分不出「搬了旧键」与「补了默认」。
   */
  function builtinEntries(over: Record<string, unknown>): unknown[] {
    return DEFAULT_CONFIG.channels.map((channel) => ({ ...channel, ...over }));
  }

  it("服务先于插件就绪：装配期读到存量并割接进当前配置文件（同步，没有「等一会儿」的窗口）", async () => {
    // 0.2.4 那一步只在刻度未到的装机上跑：真实升级场景就是把刻度退回起点；而 0.2.3 的装机
    // 没有这份配置文件（配置住在宿主 settings 里），割接就落在这一份新文件上。
    rmSync(versionFile, { force: true });
    rmSync(configFile, { force: true });
    const { unmount } = await mount({
      settings: { notifyTaskDone: false, notifySound: false, configFile: "/legacy/config.json" },
    });

    // 割接在装配期同步走完：装配返回时读面已经是割接后的形态，不需要轮询。
    expect(configApi.readConfig().notifyTaskDone).toBe(false);
    const stored = JSON.parse(readFileSync(configFile, "utf8")) as Record<string, unknown>;
    expect(stored.notifyTaskDone).toBe(false);
    // 旧键搬完即删：文件里只留条目一处表达
    expect("notifySound" in stored).toBe(false);
    // 两条内置条目被割接出来，旧的全局音效键摊到各自的 `sound` 上；其余字段由 0.2.9 的形态清理
    // 按默认表补齐（#1016 P1-1）——所以这里是**链的终态**，不是 0.2.4 那一步的中间形态。
    expect(stored.channels).toEqual(builtinEntries({ sound: false }));
    // 装配键（configFile）不进新配置：它在旧格式里就属于组合层的启动参数。
    expect("configFile" in stored).toBe(false);
    await unmount();
  });

  it("命名空间未注册时也能割接：存量只在 DSH_HOME 正式 settings.yaml 里", async () => {
    rmSync(versionFile, { force: true });
    rmSync(configFile, { force: true });
    writeFileSync(
      join(home.dir, "settings.yaml"),
      "dsh-notifier:\n  notifyTaskDone: false\n  notifySound: false\n",
      "utf8",
    );
    // `settings` 缺省 = 服务面里没有这条命名空间（新架构不注册它）：正式文件仍直接提供存量。
    const { unmount } = await mount({});

    const stored = JSON.parse(readFileSync(configFile, "utf8")) as Record<string, unknown>;
    expect(stored.notifyTaskDone).toBe(false);
    // 旧键搬完即删，且装配键不进新配置。
    expect("notifySound" in stored).toBe(false);
    expect(stored.channels).toEqual(builtinEntries({ sound: false }));
    await unmount();
  });

  it("服务缺席即不装配：缺 settings 的 inject 门一步都不走，配置原样躺着；就绪后同一次装配里割接", async () => {
    rmSync(versionFile, { force: true });
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    const fiber = await root.plugin(notifier);
    live = fiber;
    await settleMicrotasks();

    // 缺依赖：装配没跑，也就没有人去读写配置——种下的那份逐字未动。
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
    expect(readFileSync(configFile, "utf8")).toBe(seededConfig());

    // 服务随后就绪：装配开始，割接与它同一次走完。
    root.provide("settings", fakeSettings({ notifyTaskDone: false }));
    await fiber.await();
    expect(host.routes).toHaveLength(ROUTE_PATHS.length);
    const stored = JSON.parse(readFileSync(configFile, "utf8")) as Record<string, unknown>;
    expect(stored.notifyTaskDone).toBe(false);
  });

  it("名字对不上与卸载后到来的服务都不触发割接（inject 认的是服务名，不是形状）", async () => {
    rmSync(versionFile, { force: true });
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    root.provide("webServer", host.service);
    const fiber = await root.plugin(notifier);

    // ① 名字对不上：另一个恰好也带 describe 的服务不满足 inject，装配一步都不走。
    root.provide("otherHostService", fakeSettings({ notifyTaskDone: false }));
    await settleMicrotasks();
    expect(host.routes).toHaveLength(0);

    // ② 卸载之后才来的真服务：装配体已卸载，不会再被拉起来。
    await fiber.dispose();
    root.provide("settings", fakeSettings({ notifyTaskDone: false }));
    await settleMicrotasks();
    expect(host.routes).toHaveLength(0);
    expect(root.get("wingsky.notifier", false)).toBeUndefined();

    // 否定判据要一个界碑：config 域的写队列串行，本用例自己排一次队，它的落盘即此前全部落盘。
    const written = await configApi.writeConfig({ historyMaxAgeDays: 5 });
    expect(written.ok).toBe(true);
    const stored = JSON.parse(readFileSync(configFile, "utf8")) as Record<string, unknown>;
    expect("notifyTaskDone" in stored).toBe(false);
    expect(stored.historyMaxAgeDays).toBe(5);
  });
});

describe("释放", () => {
  it("卸载逆序：api 域先放（摘路由时设置读面与服务面都还在），服务面随 sdk 域最后消失", async () => {
    const { root, host, unmount } = await mount({});
    await unmount();

    // 摘除发生在 api 域释放的那一刻。正序释放会让 config 域（先于 api 装配）已经放开入参，
    // 症状是「api 域在别人已放开的入参上继续服务」——这里读到的就是那个入参。
    expect(host.removals).toHaveLength(ROUTE_PATHS.length);
    for (const removal of host.removals) {
      expect(removal.configDays).toBe(7);
      expect(removal.serviceAlive).toBe(true);
    }
    // 全链走完之后：服务面收回、设置回落默认（config 域也释放了）。
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
    expect(configApi.readConfig().historyMaxAgeDays).toBe(0);
  });

  it("卸载后事件与提交都不再进管线：没有新的历史落盘", async () => {
    const { root, warns, unmount } = await mount({});
    const payload = {
      agent: fakeAgent("itest-unload"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    };
    root.emit("agent/error", payload);
    await pollUntil(() => countKind("error") === 1, "卸载前的归档");
    const service = root.get("wingsky.notifier", false);

    await unmount();
    root.emit("agent/error", payload);
    // 消费方可能握着卸载前的服务引用：那时 submit 必须被丢弃（不抛），而不是写进一个已释放的域。
    await service?.send({ kind: "done", body: "卸载后发送" });

    // 否定判据要界碑：重新装配一次，用 stores 域自己的写口排队，界碑落盘即此前排队的写入全部落盘
    // ——卸载后若真有人在服务且还写得动磁盘，那条 done 会排在界碑之前浮现。
    const again = await mount({});
    await settleHistory();
    expect(countKind("error")).toBe(1);
    expect(countKind("done")).toBe(0);
    // 光看历史不够：卸载后 stores 的写会被它自己的 UNINSTALLED 出口吞掉，泄漏的请求于是「写了但没
    // 落下」。投递那条路不会静默——真跑到投递层会撞上「投递块尚未装配」并出声，而界碑（pollUntil
    // 至少等过一个定时器）已保证在飞的那条链全部落定，所以这里读 warn 不是抢跑。
    expect(warns.filter((line) => line.includes("投递失败"))).toEqual([]);
    await again.unmount();
  });

  it("宿主 webServer 被收回（热重载）：本插件随之卸载，路由全部摘除、服务面收回", async () => {
    const root = new Context();
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }));
    const webServer = root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    const fiber = await root.plugin(notifier);
    live = fiber;
    expect(host.routes).toHaveLength(ROUTE_PATHS.length);

    // 宿主收回服务：依赖它的 fiber 必须自己卸载——挂着不走的症状是「宿主已经换了 webServer，
    // 旧路由还挂在新服务器上」，而插件看起来一切正常。
    await webServer();
    live = null;
    expect(host.removals.map((removal) => removal.path).sort()).toEqual([...ROUTE_PATHS].sort());
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
  });

  it("单个域释放失败不阻断其余：一条路由摘除抛错，卸载链照样走完", async () => {
    const root = new Context();
    // 第 3 条摘除器抛错：宿主摘不掉路由是真实会发生的（路由已被别人摘掉、宿主换实现），
    // 组合根的安全释放壳必须继续走完 sdk / events / pipeline / stores / config——否则一次清理
    // 失败就拖垮整条卸载链。
    const host = fakeWebServer(() => ({ configDays: 0, serviceAlive: false }), { failAt: 3 });
    root.provide("webServer", host.service);
    root.provide("settings", fakeSettings({}));
    const fiber = await root.plugin(notifier);
    live = fiber;

    await fiber.dispose();
    live = null;
    // 两层隔离都在这里看得见：**域内**逐条摘除互不阻断（8 条路由全摘，抛错那条自己已记账），
    // **组合根**的释放壳也不被这个失败拖住（下面两个凭据）。缺了域内那层，这里会是 3。
    expect(host.removals.map((removal) => removal.path).sort()).toEqual([...ROUTE_PATHS].sort());
    // 链走完的两个凭据：服务面收回（sdk 域放过了）与设置回落默认（config 域也放过了）。
    expect(root.get("wingsky.notifier", false)).toBeUndefined();
    expect(configApi.readConfig().historyMaxAgeDays).toBe(0);
  });
});

/**
 * 隔离自证：本节全部落盘都必须住进临时 DSH_HOME。
 *
 * 它守的是本文件的**红线纪律**：单例在模块加载期定死路径，一旦动态 `import()` 排到了
 * `tempDshHome()` 之前，三个域的写入就全进真实 `~/.dsh`（正在跑的 `dsh web` 的 home），
 * 而那时下面这些读会当场落空。
 */
describe("落盘隔离", () => {
  it("历史、配置、序号三个域的文件都落在临时 DSH_HOME 的包私有目录里", async () => {
    const { root, unmount } = await mount({});
    root.emit("agent/error", {
      agent: fakeAgent("itest-home"),
      turn: 1,
      step: 1,
      error: new Error("炸了"),
    });
    await pollUntil(() => countKind("error") === 1, "归档落盘");
    await pollUntil(() => seqValue() === seqAnchor + 1, "序号落盘");

    // 路径同源：三个域名下的文件都是 `notifierFile()` 从同一个 DSH_HOME 拼出来的。
    expect(historyFile).toBe(join(storageDir, sharedApi.HISTORY_FILE_NAME));
    expect(configFile).toBe(join(storageDir, sharedApi.CONFIG_FILE_NAME));
    // 原子写会先落一个同目录临时文件（`<目标>.tmp-<pid>`），status 的防抖落盘可能正在飞：那是
    // 实现的中间物，不是布局的一部分，剔掉再比对。**要轮询**：清单在防抖窗口内本来就不齐，
    // 直接比会读到「前一个用例留下的文件」而看不出状态落盘整条坏掉（实测：把 status 的 debounce
    // 写改成永不执行，e2e 那条红、这条不轮询的版本全绿）。
    await pollUntil(() => {
      const names = readdirSync(storageDir).filter((name) => !name.includes(".tmp-"));
      return names.length === 5 && names.includes(sharedApi.STATUS_FILE_NAME);
    }, "五个存储文件落齐");
    expect(
      readdirSync(storageDir)
        .filter((name) => !name.includes(".tmp-"))
        .sort(),
    ).toEqual([
      sharedApi.CONFIG_FILE_NAME,
      sharedApi.HISTORY_FILE_NAME,
      sharedApi.SEQ_FILE_NAME,
      sharedApi.STATUS_FILE_NAME,
      sharedApi.VERSION_FILE_NAME,
    ]);
    // 内容也要对：路径存在不代表这次投递真的写进去了（status 是防抖落盘的，初值 `{}` 会先出现）。
    await pollUntil(() => {
      try {
        return readFileSync(join(storageDir, sharedApi.STATUS_FILE_NAME), "utf8").includes(
          "browser",
        );
      } catch {
        return false;
      }
    }, "状态里出现本次投递的频道");
    // 配置读的是本用例种下的那份（临时目录里的），落的历史也是本次 run 写的。
    expect(configApi.readConfig().historyMaxAgeDays).toBe(7);
    expect(readFileSync(historyFile, "utf8")).toContain('"kind":"error"');
    await unmount();
  });
});

packages/dsh-notifier/test/unit/upgrade/.source:
/**
 * dsh-notifier upgrade 域 steps 块 —— 0.2.3 → 0.2.4 的存储布局归位。
 *
 * 判据面：这是唯一**动用户数据**的一步。搬错的表现是静默丢数据——历史读空、状态表回默认、旧文件
 * 留在 home 根目录，而用户只会看到「通知记录没了」。故逐条锁：内容逐字保留、旧文件留痕、
 * 目标已存在时**不覆盖**（用户可能已经在新位置改过东西）、重跑不累积归档。
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import {
  BARK_KNOWN_KEYS,
  BARK_LEVELS,
  BARK_LEVELS_LIMIT,
  BARK_TIMEOUT_MS_LIMIT,
  DEFAULTS,
  HISTORY_MAX_AGE_DAYS_LIMIT,
  REQUIRED_KEYS,
  VALUE_DOMAIN_REQUIRED_KEYS,
  WEBHOOK_AUTHS,
  WEBHOOK_KNOWN_KEYS,
  WEBHOOK_PRESETS,
  WEBHOOK_TEMPLATE_MAX_CHARS,
  WEBHOOK_TIMEOUT,
} from "../../../src/shared/interface.ts";
import { normalizeConfig } from "../../../src/server/config/impl/input/index.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type {
  RawSettingValue,
  StoredSettings,
} from "../../../src/server/config/impl/model/type.ts";
import { projectForView } from "../../../src/server/config/impl/service/view.ts";
import {
  CONFIG_FILE_NAME,
  HISTORY_FILE_NAME,
  SEQ_FILE_NAME,
  STATUS_FILE_NAME,
  legacyFile,
  notifierFile,
  writeTextAtomicSync,
} from "../../../src/server/shared/interface.ts";
import { migrateCanonicalKeys } from "../../../src/server/upgrade/impl/steps/canonical-keys.ts";
import { migrateStorageLayout } from "../../../src/server/upgrade/impl/steps/storage-layout.ts";
import { tempDshHome } from "../../helpers.ts";

/** 本文件内建过的隔离环境，逐个在 afterEach 还原并删除。 */
const cleanups: Array<() => void> = [];

afterEach(() => {
  for (const dispose of cleanups.splice(0)) dispose();
});

/** 建一个隔离 DSH_HOME（迁移的读端与写端都从它解析路径）。 */
function isolatedHome(): string {
  const home = tempDshHome();
  cleanups.push(home.dispose);
  return home.dir;
}

function writeLegacy(name: string, text: string): void {
  writeFileSync(legacyFile(name), text, "utf8");
}

/** 旧文件名 → 新文件名 → 一份有代表性的内容（jsonl 是多行、json 是单行、seq 是数字）。 */
const ENTRIES = [
  ["dsh-notifier-history.jsonl", HISTORY_FILE_NAME, '{"ts":1,"kind":"done"}\n{"ts":2}\n'],
  [
    "dsh-notifier-status.json",
    STATUS_FILE_NAME,
    '{"bark:main":{"lastTs":9,"lastStatus":"ok","failStreak":0}}\n',
  ],
  ["notifier-seq.json", SEQ_FILE_NAME, "7\n"],
] as const;

/**
 * 0.2.8 → 0.2.9：配置形态清理（#1016 S3）。
 *
 * 判据面：读面自 S3 起不再兜底（视图只做键子集 + 原样 + 掩码），兜底搬到本步。搬错的表现分两种，
 * 都很安静：**该删的没删**——磁盘上留着越界 / 非法枚举 / 缺必填键的条目，此后每一次无关保存都可能被
 * 拒，或者设置页把它原样交给客户端再原样带回（读面曾经会替它收敛，现在是原样往返）；**该留的删了**——
 * 合法但非默认的取值（配满的 levels、8000 字符的 template、凭据空串）被当成脏值清掉，用户配的东西
 * 无声消失。故逐条锁判据方向，并且逐条钉住「重跑一个字不写」。
 */
describe("配置形态清理（canonical-keys）", () => {
  const BARK = { type: "bark", id: "bark:1", baseUrl: "https://x", deviceKey: "k" };
  const HOOK = { type: "webhook", id: "hook:1", url: "https://y" };
  /**
   * 两条内置条目的**干净**形态（0.2.9 清理之后磁盘上就是这个样子），取自默认表而不是手抄一份——与默认表
   * 同源由末尾那条同源守卫钉住。
   *
   * **刻意用完整形态而不是 `{type,id}`**：0.2.4 割接在用户没设过任何旧键时写出的确实是
   * `{type,id}`，而本步现在会把它补齐（判据 #8 的第二格）。让多数用例拿干净形态当输入，
   * 「残缺形态会被补」这件事才由那一条单独断，而不是散落在每条断言的差异里。
   */
  function builtinDefault(type: string): Record<string, unknown> {
    const found = DEFAULT_CONFIG.channels.find((channel) => channel.type === type);
    if (found === undefined) throw new Error("默认表里没有内置频道 " + type);
    return found as unknown as Record<string, unknown>;
  }
  const BROWSER = builtinDefault("browser");
  const SYSTEM = builtinDefault("system");

  /** 落盘后的频道数组（存储层形状不受契约约束，按原始值看）。 */
  function channelsOnDisk(stored: Record<string, unknown>): Array<Record<string, unknown>> {
    return stored.channels as Array<Record<string, unknown>>;
  }

  /** 任意一份设置（视图投影）里的频道数组；存储层形状不受契约约束，按原始值看。 */
  function channelsOf(config: unknown): Array<Record<string, RawSettingValue>> {
    const picked = (config as { channels?: RawSettingValue }).channels;
    return (picked ?? []) as Array<Record<string, RawSettingValue>>;
  }

  /** 种一份磁盘配置并跑一步清理，返回落盘后的内容。 */
  function clean(stored: Record<string, unknown>): Record<string, unknown> {
    isolatedHome();
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), `${JSON.stringify(stored, null, 2)}\n`);
    migrateCanonicalKeys();
    return JSON.parse(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")) as Record<
      string,
      unknown
    >;
  }

  /** 磁盘原文（跑之前），用于「一个字不写」的逐字比对。 */
  function seedRaw(text: string): void {
    isolatedHome();
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), text);
  }

  it("判据 #1：顶层不在已知键集内的键删除（0.2.3 的旧顶层渠道键、退役的 maxConnections、手写的未来键）", () => {
    const out = clean({
      channels: [BROWSER, SYSTEM, BARK],
      notifySound: false,
      maxConnections: 64,
      futureFlag: true,
    });
    expect(Object.keys(out)).toEqual(["channels"]);
  });

  it("判据 #2：频道条目内不在该 type 字段名集合内的键删除（含凭据别名保留键）", () => {
    const out = clean({
      channels: [
        BROWSER,
        SYSTEM,
        { ...BARK, volume: 5, device_key: "别名" },
        { ...HOOK, retries: 2, auth_token: "别名" },
      ],
    });
    expect(out.channels).toEqual([BROWSER, SYSTEM, BARK, HOOK]);
  });

  // 判据 #2 的**反向那一格**：上面那条用的全是从未出现在任一已知键表里的键（volume / device_key /
  // retries / auth_token），它证明不了「按 type 取表」这件事——把 `knownKeysOf` 改成返回**两类型并集**
  // （BARK_KNOWN_KEYS ∪ WEBHOOK_KNOWN_KEYS），上面那条照样全绿。
  //
  // 这一条补的正是那一格：bark 的键挂在 webhook 条目上（deviceKey 是跨 type 残留掩码的落点、
  // baseUrl / levels 是投递必需键与映射表），反向亦然（token / headerValue / timeoutSec 挂到 bark 上）。
  // 它是**跨 type 残留的清道夫**——磁盘上留着这些键，读面就把它们原样外发、客户端原样带回，
  // 写面随后要么 400（陌生键）要么被当普通值写回，而带掩码的那一种正是写面拒收话术要解释的情形。
  it("判据 #2 的反向格：别的 type 的已知键挂在条目上同样删除（按 type 取表，不是取并集）", () => {
    const out = clean({
      channels: [
        BROWSER,
        SYSTEM,
        { ...HOOK, deviceKey: "跨类型残留", baseUrl: "https://x", levels: { done: "passive" } },
        { ...BARK, token: "跨类型残留", headerValue: "跨类型残留", timeoutSec: 30 },
      ],
    });
    expect(out.channels).toEqual([BROWSER, SYSTEM, HOOK, BARK]);
    // 前提事实：这些键确实在**另一张**已知键表里（否则这条就只是在测「陌生键删除」，与 #2 同义）。
    expect(BARK_KNOWN_KEYS).toContain("deviceKey");
    expect(BARK_KNOWN_KEYS).toContain("baseUrl");
    expect(BARK_KNOWN_KEYS).toContain("levels");
    expect(WEBHOOK_KNOWN_KEYS).toContain("token");
    expect(WEBHOOK_KNOWN_KEYS).toContain("headerValue");
    expect(WEBHOOK_KNOWN_KEYS).toContain("timeoutSec");
  });

  it("判据 #3：类型不符的标量删键不夹值（notifyAsk 写成字符串、allowKinds 写成数字）", () => {
    const out = clean({
      channels: [BROWSER, SYSTEM],
      notifyAsk: "yes",
      allowKinds: 3,
    });
    expect("notifyAsk" in out).toBe(false);
    expect("allowKinds" in out).toBe(false);
  });

  it("判据 #4：越界与非法枚举删键不夹值（timeoutSec / timeoutMs / level / preset / historyMaxAgeDays）", () => {
    // auth 刻意不在这条用例里：它是**取值域必填键**，白名单外删的是整条而不是键（判据 #5 第三格）。
    const out = clean({
      channels: [
        BROWSER,
        SYSTEM,
        { ...BARK, timeoutMs: 999_999, level: "urgent" },
        { ...HOOK, timeoutSec: 99_999, preset: "nope" },
      ],
      historyMaxAgeDays: 4000,
    });
    expect(out.channels).toEqual([BROWSER, SYSTEM, BARK, HOOK]);
    expect("historyMaxAgeDays" in out).toBe(false);
  });

  it("判据 #4 的另一面：界内取值**不动**（timeoutSec: 60 / timeoutMs: 0 / historyMaxAgeDays: 3650）", () => {
    const out = clean({
      channels: [
        BROWSER,
        SYSTEM,
        { ...BARK, timeoutMs: 0, level: "critical" },
        { ...HOOK, timeoutSec: 60, preset: "ntfy", auth: "bearer" },
      ],
      historyMaxAgeDays: 3650,
    });
    expect(out.channels).toEqual([
      BROWSER,
      SYSTEM,
      { ...BARK, timeoutMs: 0, level: "critical" },
      { ...HOOK, timeoutSec: 60, preset: "ntfy", auth: "bearer" },
    ]);
    expect(out.historyMaxAgeDays).toBe(3650);
  });

  // 判据 #5 的两格。**格与格的分界是「这个键是不是必填」**，读的是 shared 的 REQUIRED_KEYS。
  //
  // 第一格（非必填键形态不符 → 只删键）：token / headerValue 是凭据字段但不是投递必需键，删掉它们之后
  // 这条 webhook 仍然投递得了（url 还在），留着条目是对的。password 是**空串**——形态合法，空串表达
  // 「未设置」，一个字都不动。
  //
  // 改坏方向（退回「一律只删键」）：bark 那条会剩下 `{type,id,baseUrl}`——本步**自己**造出一条残缺条目，
  // 而判据 #6 承诺的恰恰是半坏条目整条保留。两条判据相隔不到十行、方向相反，用户看到的现象是
  // 「升级后我那条频道打不通了」，而罪魁是升级本身。
  it("判据 #5：非必填键值形态不符只删该键（凭据字段的空串**不动**——它表达的是「未设置」）", () => {
    const hook = { ...HOOK, token: null, password: "", headerValue: 7, name: "钩子" };
    const out = clean({ channels: [BROWSER, SYSTEM, BARK, hook] });
    // token / headerValue 两个键消失（值形态不对），password 是空串（留），条目与 name 一起留着。
    expect(out.channels).toEqual([
      BROWSER,
      SYSTEM,
      BARK,
      { type: "webhook", id: "hook:1", url: "https://y", password: "", name: "钩子" },
    ]);
  });

  // 判据 #5 的第二格（#1016 单一事实源收口）：**必填键**值形态不符 → **删整条**。
  //
  // 为什么不是「只删键」：删掉 baseUrl 就是本步当场造出一条残缺条目。磁盘上原本只有这一个字段不对
  // （用户手滑打成了数字），清理之后整条都投递不了，而 S3 自己修通的三条路（视图可见 / 写面
  // preexisting 放行 / 投递投影丢弃）会把这条半坏条目永久接住——代价由用户承担，原因是升级。
  //
  // 与判据 #6 的边界是**「键在不在」**，不是「这条条目完整不完整」：缺席 / 空串是用户手改出来的残缺，
  // 原样保留；形态不符是本步造出来的，不能留。这条用例与下一条（判据 #6）合起来才是完整边界。
  it("判据 #5 第二格：必填键值形态不符 → 删整条（本步不造残缺条目）", () => {
    const badBaseUrl = { ...BARK, baseUrl: 12345, name: "地址写成数字" };
    const badDeviceKey = {
      type: "bark",
      id: "bark:2",
      baseUrl: "https://x",
      deviceKey: null,
      name: "凭据写成 null",
    };
    const badUrl = { type: "webhook", id: "hook:2", url: 7, name: "地址写成数字" };
    const kept = { ...HOOK, name: "完好" };
    const out = clean({ channels: [BROWSER, SYSTEM, badBaseUrl, badDeviceKey, badUrl, kept] });
    // 三条全没了，完好那条与它的 name 一起留着——判据从「删键」升级成「删整条」时，删的必须是整条。
    expect(out.channels).toEqual([BROWSER, SYSTEM, kept]);
  });

  // 判别力（#1016 单一事实源，硬要求 #1）：清理步遇必填键值形态不符时**不产生**残缺条目。
  //
  // 这一条与上一条不是同一件事：上一条断言「整条消失」，这一条断言「磁盘上不留任何半成品」——
  // 改坏方向是「删键但条目留着」，那种实现下上一条会红吗？会（多出一条），这一条则给出正面证据：
  // 跑完之后**逐条**检查没有任何一条少了必填键。
  it("判别力 #1：必填键值形态不符的条目，清理后磁盘上不存在「少一个必填键」的条目", () => {
    const out = clean({
      channels: [
        BROWSER,
        SYSTEM,
        { ...BARK, baseUrl: 12345 },
        { ...BARK, id: "bark:2", deviceKey: { nested: true } },
        { type: "webhook", id: "hook:2", url: 7 },
        { type: "webhook", id: "hook:3", url: null },
      ],
    });
    for (const channel of channelsOnDisk(out)) {
      const type = channel.type as string;
      for (const key of REQUIRED_KEYS[type] ?? []) {
        // 「键不在」与「键在但是空串」是**用户手改出来的**残缺，判据 #6 明确保留——
        // 判别力只针对「本步会不会新造出半成品」，故只钉「本该存在的必填键一个都不许被本步删掉」。
        expect(Object.hasOwn(channel, key), type + "." + key).toBe(true);
      }
    }
  });

  // 判别力（硬要求 #2）：非必填键值形态不符 → 只删该键、条目保留。
  //
  // 与判据 #5 第一格同向但断言面不同：那条钉具体三个键，这一条钉「除该键外逐字不动」——
  // 改坏方向是把非必填键也升级成删整条，那症状是「用户一条好端端的频道，升级后不见了」。
  it("判别力 #2：非必填键值形态不符只删该键，条目连其余字段逐字保留", () => {
    const hook = {
      type: "webhook",
      id: "h:1",
      url: "https://y",
      name: "我的钩子",
      enabled: true,
      token: 42,
      timeoutSec: 30,
    };
    expect(clean({ channels: [BROWSER, SYSTEM, hook] }).channels).toEqual([
      BROWSER,
      SYSTEM,
      {
        type: "webhook",
        id: "h:1",
        url: "https://y",
        name: "我的钩子",
        enabled: true,
        timeoutSec: 30,
      },
    ]);
  });

  // 判据 #5 的第三格（取值域类必填键，webhook 的 `auth`）：值不在 WEBHOOK_AUTHS 里 → **删整条**。
  //
  // 与第二格同形，区别只在判据用哪个谓词：`auth` 不在 REQUIRED_KEYS 里是因为它的判据是取值域而不是「在场」，
  // 不因为处置可以更轻。**删键的后果是本步自己造出残缺**：写面 `validateWebhookChannel` 对「auth 缺席」与
  // 「auth 非法」是同一句拒收，于是磁盘上剩下那条「url 齐全、只是没有 auth」的频道，此后每一次无关保存
  // 都被 400 拒收——与 baseUrl 被删时的症状逐字相同，而罪魁同样是升级本身。
  //
  // 改坏方向（退回「只删 auth 键」）：磁盘上多出一条此后永远存不下的频道，本条立刻红（多出一个条目）。
  it("判据 #5 第三格：取值域必填键（auth）值不在白名单 → 删整条，不是只删 auth 键", () => {
    const badNumber = {
      type: "webhook",
      id: "hook:number",
      url: "https://y",
      auth: 123,
      name: "认证写成数字",
    };
    const badString = {
      type: "webhook",
      id: "hook:string",
      url: "https://y",
      auth: "magic",
      name: "白名单外的串",
    };
    const badNull = {
      type: "webhook",
      id: "hook:null",
      url: "https://y",
      auth: null,
      name: "空值",
    };
    const kept = { ...HOOK, auth: "bearer", name: "完好" };
    const out = clean({ channels: [BROWSER, SYSTEM, badNumber, badString, badNull, kept] });
    // 三条全没了（连 name 一起），白名单内的 auth 那条逐字留着——处置与在场必填键一字不差。
    expect(out.channels).toEqual([BROWSER, SYSTEM, kept]);
  });

  // 第三格与判据 #6 的边界仍是「键在不在 + 空串」：键缺席、值为空串都是**用户手改**出来的「没填」，
  // 原样保留——`auth` 不在 REQUIRED_KEYS 里不改变判据 #6 对它的承诺。
  //
  // 改坏方向（把空串也算成白名单外）：用户手改坏一次配置，升级就把他的频道连 name 一起删掉，而他在设置页
  // 里从头到尾见过它——那正是判据 #6 拒绝付的「看不见的代价」。
  it("判据 #5 第三格的边界：auth 键缺席或空串逐字保留（判据 #6 对取值域必填键同样生效）", () => {
    const absent = { type: "webhook", id: "h:absent", url: "https://y", name: "缺 auth" };
    const empty = { type: "webhook", id: "h:empty", url: "https://y", auth: "", name: "auth 空串" };
    expect(clean({ channels: [BROWSER, SYSTEM, HOOK, absent, empty] }).channels).toEqual([
      BROWSER,
      SYSTEM,
      HOOK,
      absent,
      empty,
    ]);
  });

  // #1016 P1-2 选 (a) 的落点：投递必需键空串或缺席**不再删整条**，原样留在磁盘上。
  //
  // **本条是本轮唯一一处「编号保留、语义反转」的判据**：S3 任务书（#1016 P1-2）给 #6 的原文是「频道
  // 条目缺必填键（bark 缺 baseUrl/deviceKey、webhook 缺 url）→ 删整条条目」，实现时发现它与 S3 自己刚
  // 修通的半坏条目三条路自相矛盾（见 canonical-keys.ts 文件头），遂反转成「整条保留」。
  //
  // **号不重排**（S4 裁决）：#1–#8 是一份闭合清单，把被否决的那条「另起编号」或整段重排都不解决
  // 问题、只把陷阱挪位置——重排之后清单里从此没有 #6，评审得靠数才看得出这里曾有一条被否决，而
  // 「半坏条目该不该删」这个决定本身在代码里也就没了着落。真正能掐掉陷阱的是**把反转写在编号旁边**
  // （就是本段），不是换号。号仍是稳定句柄：谁引用过「判据 #6」都还指得到这一条。
  //
  // 改坏方向（回到旧实现）：整条消失、连 name 一起丢，而用户在设置页里从头到尾没见过它——S3 刚把半坏
  // 条目的三条路（视图看得见 / 写面 preexisting 放行 / 投递投影整条丢弃）修通，升级步再把它删掉是自相矛盾。
  it("判据 #6：半坏条目（必填键空串或缺席）整条保留、逐字不动 —— 反转自 #1016 P1-2 的「删整条」；deviceKey 空串的 bark 连 name 一起留着", () => {
    const emptyDeviceKey = {
      type: "bark",
      id: "bark:empty-key",
      baseUrl: "https://x",
      deviceKey: "",
      name: "凭据空串",
    };
    const emptyBaseUrl = {
      type: "bark",
      id: "bark:empty",
      baseUrl: "",
      deviceKey: "k",
      name: "地址空串",
    };
    const absentBaseUrl = { type: "bark", id: "bark:no-url", deviceKey: "k", name: "缺地址" };
    const absentUrl = { type: "webhook", id: "hook:no-url", name: "缺 url" };
    const out = clean({
      channels: [BROWSER, SYSTEM, BARK, emptyDeviceKey, emptyBaseUrl, absentBaseUrl, absentUrl],
    });
    expect(out.channels).toEqual([
      BROWSER,
      SYSTEM,
      BARK,
      emptyDeviceKey,
      emptyBaseUrl,
      absentBaseUrl,
      absentUrl,
    ]);
  });

  // 判别力（硬要求 #3）：手改出来的残缺条目（键**缺席**）→ 原样保留，判据 #6 不变。
  //
  // 这一条是判据 #5 第二格那半边的对照：同样是「这条投递不了」，**成因**不同、处置就不同——
  //   - 键缺席 / 空串：**用户**手改出来的。本步不制造它，也不假装它不存在，删它等于替用户做决定。
  //   - 键在但形态不对：**本步**的正对面。若这时还只删键，本步就成了残缺条目的生产者。
  //
  // 改坏方向：把缺席也升级成删整条（回到 S3 任务书原文），本条立刻红——用户手改坏一次配置，
  // 升级就把他的频道连 name 一起删掉，而他在设置页里从头到尾见过它。
  it("判别力 #3：手改出来的残缺条目（必填键缺席）原样保留，与形态不符的处置分界清晰", () => {
    const absent = [
      { type: "bark", id: "bark:no-url", deviceKey: "k", name: "缺 baseUrl" },
      { type: "bark", id: "bark:no-key", baseUrl: "https://x", name: "缺 deviceKey" },
      { type: "webhook", id: "h:no-url", name: "缺 url" },
    ];
    const out = clean({ channels: [BROWSER, SYSTEM, BARK, ...absent] });
    // 三条半坏条目逐字留着（BARK 是完好的对照），一条都没少。
    expect(out.channels).toEqual([BROWSER, SYSTEM, BARK, ...absent]);
  });

  // 判别力（硬要求 #3 的第二半）：必填键**空串**同样原样保留。
  //
  // 空串走的是「形态合法」那一条路（`typeof "" === "string"`），所以它与「形态不符」的处置天然分开——
  // 删键逻辑压根不看它。这条把它钉住：改坏方向是「把空串也算成形态不符」，症状是用户把凭据清空后
  // 升级，那条频道连同 name 一起消失。
  it("判别力 #3 续：必填键空串逐字保留（空串是合法形态，不是形态不符）", () => {
    const empties = [
      { type: "bark", id: "bark:e1", baseUrl: "", deviceKey: "k", name: "地址空串" },
      { type: "bark", id: "bark:e2", baseUrl: "https://x", deviceKey: "", name: "凭据空串" },
      { type: "webhook", id: "h:e1", url: "", name: "钩子地址空串" },
    ];
    expect(clean({ channels: [BROWSER, SYSTEM, BARK, ...empties] }).channels).toEqual([
      BROWSER,
      SYSTEM,
      BARK,
      ...empties,
    ]);
  });

  // 判据 #7 **已反转**（#1016 残留 2）：迁移**不得**按重复身份去重。
  //
  // 原行为「重复 id 保留首条」在这里是数据销毁：升级那一刻把用户第二条频道连凭据一起从磁盘删掉，
  // 设置页上它还在（视图原样外发），而任何一次无关保存又立刻被写面 400 说「身份重复」——数据没了，
  // 理由还指向一个用户没做过的操作。issue #1016 批次 B 明禁「迁移不得静默取首项」。
  //
  // 现在的分工：写面绝对拒（用户删掉其中一条即可自救），投递投影取首项只为不再双投，两处都不改磁盘。
  it("判据 #7：重复身份的条目原样保留（迁移不得静默取首项）", () => {
    const out = clean({
      channels: [
        BROWSER,
        SYSTEM,
        { ...BARK, name: "首条" },
        { ...BARK, name: "次条" },
        { type: "webhook", id: "hook:1", url: "https://a" },
        { type: "webhook", id: "hook:1", url: "https://b" },
      ],
    });
    // 逐条都在，且次序不变：包括那两条凭据不同的 webhook（url 就是它们的凭据面）。
    expect(out.channels).toEqual([
      BROWSER,
      SYSTEM,
      { ...BARK, name: "首条" },
      { ...BARK, name: "次条" },
      { type: "webhook", id: "hook:1", url: "https://a" },
      { type: "webhook", id: "hook:1", url: "https://b" },
    ]);
  });

  // 去掉去重**不等于**跳过逐条清理：重复身份的那一条仍然要照常清陌生键，只是**不再被整条丢掉**。
  // 去掉 `seenIds` 的改法很容易顺手把第二条漏在清理之外（把 `continue` 提到了 `cleanEntry` 之前），
  // 那会让升级给磁盘留下一条带陌生键的重复条目——本条专钉这个方向。
  it("判据 #7：重复身份的那一条仍照常清陌生键（去重去掉 ≠ 跳过逐条清理）", () => {
    const out = clean({
      channels: [BROWSER, SYSTEM, BARK, { ...BARK, name: "次条", 陌生键: 1 }],
    });
    expect(out.channels).toEqual([BROWSER, SYSTEM, BARK, { ...BARK, name: "次条" }]);
  });

  // 判据 #8 的第二格（#1016 P1-1）：**在场但字段残缺**。0.2.4 割接在用户没设过任何旧键时写出的就是
  // `{type,id}`——那是「用户从没碰过这条内置」的真实磁盘形态。
  //
  // 改坏方向（回到只补整条的旧实现）：字段缺席 → 客户端按 `ch.popup === true` 判开关 → 渲染成全关，
  // 而投递投影按默认表照发，于是**界面显示全关、实际照发**。最后那条判别力用例是这道题的正脸。
  it("判据 #8 的第二格：内置条目在场但字段残缺 → 补缺席字段，值取内置默认表", () => {
    const out = clean({ channels: [{ type: "system", id: "system" }, BARK] });
    expect(channelsOnDisk(out)[0]).toEqual(BROWSER);
    expect(channelsOnDisk(out)[1]).toEqual(SYSTEM);
  });

  // 补字段只补「键不在」，不覆盖显式值：用户把内置显式关掉是在表态，抹回默认 true 是静默改写用户的输入。
  // 改坏方向（把判据写成「值不等于默认就补」）：用户关掉的系统通知在升级后自己又开了，且没有任何提示。
  it("补字段不覆盖显式值：enabled:false / popup:false 的内置条目升级后仍是 false", () => {
    const off = { type: "system", id: "system", enabled: false, popup: false };
    const out = clean({ channels: [off, BARK] });
    expect(channelsOnDisk(out)[0]).toEqual(BROWSER);
    expect(channelsOnDisk(out)[1]).toEqual({ ...off, sound: true });
  });

  // 判别力 #1（#1016 P1-1 的正脸）：**视图与投递投影对两条内置逐字段一致**。
  //
  // 这条之所以不是「补齐了就算完」：读面自 S3 起有两条通道——视图逐字外发、投递投影按默认表物化。补齐只
  // 保证磁盘上是完整形态，而「用户看到的开关」与「实际发不发」是两条通道各自的解释；它们在残缺形态上会
  // 给出相反的答案（视图全关 / 投递照发），补齐之后必须同形。
  it("判别力 #1：残缺的内置条目清理后，视图与投递投影对两条内置逐字段一致", () => {
    const stored = clean({
      channels: [BARK, { type: "browser", id: "browser" }, { type: "system", id: "system" }],
    }) as StoredSettings;
    const shown = channelsOf(projectForView(stored));
    // 投递投影按已知键物化成 `ChannelConfig` 联合；本用例只比**字段值**，故按原始记录读（两侧口径相同）。
    const sent = normalizeConfig(stored).channels as unknown as Array<
      Record<string, RawSettingValue>
    >;
    for (const type of ["browser", "system"]) {
      const one = shown.find((channel) => channel.type === type);
      const other = sent.find((channel) => channel.type === type);
      expect(one, type).toBeDefined();
      expect(other, type).toBeDefined();
      for (const field of ["enabled", "popup", "sound", "whenVisible"] as const) {
        // 两边都没有这个键时跳过（system 本来就没有 whenVisible——「都不给」仍是一致的）。
        if (one?.[field] === undefined && other?.[field] === undefined) continue;
        expect(one?.[field], type + "." + field).toBe(other?.[field]);
      }
    }
  });
  it("判据 #8：两条内置缺哪补哪，且恒排在最前", () => {
    const onlySystem = clean({ channels: [SYSTEM, BARK] });
    expect(channelsOnDisk(onlySystem)[0]).toEqual({
      type: "browser",
      id: "browser",
      enabled: true,
      popup: true,
      sound: true,
      whenVisible: false,
    });
    const none = clean({ channels: [BARK] });
    expect(channelsOnDisk(none).slice(0, 2)).toEqual([
      {
        type: "browser",
        id: "browser",
        enabled: true,
        popup: true,
        sound: true,
        whenVisible: false,
      },
      { type: "system", id: "system", enabled: true, popup: true, sound: true },
    ]);
  });

  // 判据方向的反面：合法但**非默认**的取值一个字都不许动。写面「拒新增、不动存量」的语义是 S2 立的，
  // 本步若把它们当脏值清掉，用户配的东西会无声消失——那是本步能造成的最贵的一次错误。
  //
  // 两条尺寸上界取自 src/shared/config-schema.ts（与写面同一个事实源）：本步判的是「这个值在
  // 本版本有没有这种**形态**」，尺寸不属于形态，故贴着上界的取值同样一个字不动。抄一份数字就等于
  // 测试里另开一处第二事实源——上界改了而这里没改，断言就从「判不清理」退化成「判恰好没变的常量」。
  it("合法但非默认的取值**不清理**：满配的 levels / 贴上界的 template / 过头名 / 凭据空串", () => {
    const levels = Object.fromEntries(
      Array.from({ length: BARK_LEVELS_LIMIT }, (_unused, index) => [`kind-${index}`, "passive"]),
    );
    const bark = { ...BARK, levels };
    const hook = {
      ...HOOK,
      template: "x".repeat(WEBHOOK_TEMPLATE_MAX_CHARS),
      headerName: "X-Very-Long-Custom-Header-Name",
      password: "",
    };
    const out = clean({ channels: [BROWSER, SYSTEM, bark, hook] });
    expect(out.channels).toEqual([BROWSER, SYSTEM, bark, hook]);
  });

  // 判别力 #4：干净形态重跑一个字不写。这里用**压缩格式**种文件——重新序列化必然带缩进，
  // 于是「白写一次」会以字节差异暴露，而不是以「内容一样」蒙过去。
  it("判别力 #4：干净形态返回 null、一个字不写（连缩进都不变）", () => {
    const before = JSON.stringify({
      channels: [
        {
          type: "browser",
          id: "browser",
          enabled: true,
          popup: true,
          sound: true,
          whenVisible: false,
        },
        { type: "system", id: "system", enabled: true, popup: true, sound: true },
        BARK,
        HOOK,
      ],
      notifyAsk: true,
      historyMaxAgeDays: 30,
      quietHours: { enabled: true, windows: [{ start: "22:00", end: "08:00" }] },
    });
    seedRaw(before);

    migrateCanonicalKeys();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });

  // 幂等：清理跑过一遍之后再跑一遍，第二个字都不写——链在「每步成功后立刻回写刻度」的骨架下要求
  // 每一步自身可重入（失败后从同一步重跑），而每次启动都重写文件就是静默改写用户的格式。
  it("判别力 #4：同一份输入连跑两次，第二次不写盘（幂等）", () => {
    isolatedHome();
    writeTextAtomicSync(
      notifierFile(CONFIG_FILE_NAME),
      `${JSON.stringify({ channels: [SYSTEM, { ...BARK, level: "urgent", volume: 5 }] }, null, 2)}\n`,
    );

    migrateCanonicalKeys();
    const afterFirst = readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8");

    migrateCanonicalKeys();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(afterFirst);
  });

  it("没有配置文件：不凭空建一份（默认值被读成「用户改过」是另一条语义的反面）", () => {
    isolatedHome();

    migrateCanonicalKeys();

    expect(existsSync(notifierFile(CONFIG_FILE_NAME))).toBe(false);
  });

  it("空配置：一个键都没有的文件逐字不动", () => {
    seedRaw("{}\n");

    migrateCanonicalKeys();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe("{}\n");
  });

  it("坏 JSON：不抛，文件逐字不动（一份读不动的文件不该让启动失败）", () => {
    seedRaw("{ 坏掉的\n");

    expect(() => migrateCanonicalKeys()).not.toThrow();
    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe("{ 坏掉的\n");
  });

  // 同源守卫：本步的顶层键集、字段形态表、补齐的内置默认值都派生自共享表 / 默认表，
  // 派生点写错一处，用户配置会在升级里**静默消失**。三条断言各钉一个派生点。
  it("同源守卫：顶层键集与共享表的默认值键集同源（DEFAULTS 加 channels，一个不多一个不少）", () => {
    const stored: Record<string, unknown> = { channels: [BROWSER, SYSTEM] };
    for (const [key, value] of Object.entries(DEFAULTS)) stored[key] = value;
    const out = clean(stored);
    expect(Object.keys(out).sort()).toEqual([...Object.keys(DEFAULTS), "channels"].sort());
  });

  it("同源守卫：出站字段形态表**覆盖**两张已知键表的全部键（否则新增字段静默不过形态清理）", () => {
    // 每张已知键表都取一个**合法值**种进条目：清理后逐字不变，就证明该键既没被当成陌生键删掉、
    // 也没被形态表判成非法。加字段却忘了进形态表时，这一条会以「键消失」打红。
    const bark = {
      ...BARK,
      enabled: true,
      level: "active",
      levels: { error: "critical" },
      group: "g",
      sound: "ding",
      icon: "i",
      url: "https://u",
      badge: 0,
      timeoutMs: 1,
      name: "n",
    };
    const hook = {
      ...HOOK,
      enabled: true,
      preset: "custom",
      auth: "bearer",
      token: "t",
      username: "u",
      password: "p",
      headerName: "X",
      headerValue: "v",
      template: "{}",
      headers: { "X-A": "1" },
      timeoutSec: 10,
      name: "n",
    };
    expect(Object.keys(bark).sort()).toEqual([...BARK_KNOWN_KEYS].sort());
    expect(Object.keys(hook).sort()).toEqual([...WEBHOOK_KNOWN_KEYS].sort());
    expect(clean({ channels: [BROWSER, SYSTEM, bark, hook] }).channels).toEqual([
      BROWSER,
      SYSTEM,
      bark,
      hook,
    ]);
  });

  it("同源守卫：补齐的内置条目与默认表里的那两条逐字相等（防它与 config 域的默认表漂）", () => {
    const out = clean({ channels: [BARK] });
    expect(channelsOnDisk(out).slice(0, 2)).toEqual(DEFAULT_CONFIG.channels);
  });

  // 同源守卫（#1016 单一事实源，硬要求 #4）：清理步的**必填键**逐条读 shared 的 REQUIRED_KEYS。
  //
  // 这条断言的形状是「数据驱动」而不是「抄一份清单」：它遍历 REQUIRED_KEYS 的每一项，给那个键种一个
  // 形态不对的值，断言**整条消失**。改坏方向有两类，两类都红：
  //   ① 清理步退回自维护一份必填键清单而它与 REQUIRED_KEYS 漂了 → 本条某个键种进去却留着；
  //   ② 清理步把「必填键形态不符」又退回「只删键」 → 条目还在（且少了那个键），本条红。
  // 反向也成立：REQUIRED_KEYS 新增一个键时本条自动跟着走，不需要改这里——**这正是单一来源的形状**。
  it("同源守卫：必填键逐条读 shared 的 REQUIRED_KEYS（清单漂了或退回删键都红）", () => {
    for (const [type, keys] of Object.entries(REQUIRED_KEYS)) {
      for (const key of keys) {
        const seed: Record<string, unknown> = {
          type,
          id: type + ":" + key,
          name: "种子 " + key,
        };
        // 另一种类型不会带的键补齐成合法值，让本条只测「那个键形态不符」这一个变量。
        for (const other of keys) if (other !== key) seed[other] = "ok";
        seed[key] = 12345;
        const out = clean({ channels: [BROWSER, SYSTEM, seed] });
        expect(
          channelsOnDisk(out).map((c) => c.id),
          type + "." + key + " 值形态不符时整条应消失",
        ).toEqual([BROWSER.id, SYSTEM.id]);
      }
    }
  });

  // 同源守卫（#1016 单一事实源，硬要求 #4 的另一半）：**取值域必填键**逐条读 shared 的
  // VALUE_DOMAIN_REQUIRED_KEYS，形状与上一条对 REQUIRED_KEYS 的守卫同款。
  //
  // 种子条目只种**被测的那一个键**，同表里其它取值域必填键一律缺席——缺席是判据 #6 那一侧（保留），
  // 于是本条只测「那个键值不在取值域」这一个变量。改坏方向仍是两类：清理步退回自维护一份清单而它与
  // shared 漂了（某个键种进去却留着），或把这一格退回「只删键」（条目还在，且少了那个键）。
  it("同源守卫：取值域必填键逐条读 shared 的 VALUE_DOMAIN_REQUIRED_KEYS（清单漂了或退回删键都红）", () => {
    for (const [type, keys] of Object.entries(VALUE_DOMAIN_REQUIRED_KEYS)) {
      for (const key of keys) {
        const seed: Record<string, unknown> = { type, id: type + ":" + key, name: "种子 " + key };
        seed[key] = 12345;
        const out = clean({ channels: [BROWSER, SYSTEM, seed] });
        expect(
          channelsOnDisk(out).map((channel) => channel.id),
          type + "." + key + " 值不在取值域时整条应消失",
        ).toEqual([BROWSER.id, SYSTEM.id]);
      }
    }
  });

  // 同源守卫（硬要求 #4 的另一半）：**数值边界**也读 shared，不在本域另抄。
  //
  // 清理步的后果是删用户的键，所以「合法形态」的定义必须与读面/写面同源。这三条各钉一个曾经抄过的地方：
  // historyMaxAgeDays 上界、bark timeoutMs 上界、webhook timeout 区间。
  //
  // 改坏方向：把任一边改小 → 界内取值被当成越界删掉（用户的合法配置静默消失）；改大 → 越界值留在
  // 磁盘上，此后每次保存都被写面拒。本条双向都拦得住，因为断言的是「界内不动、界外删」。
  it("同源守卫：数值边界读 shared（界内取值不删、超出即删，两侧同源）", () => {
    // historyMaxAgeDays：上界与越一格。
    expect(clean({ channels: [BARK], historyMaxAgeDays: HISTORY_MAX_AGE_DAYS_LIMIT })).toEqual(
      expect.objectContaining({ historyMaxAgeDays: HISTORY_MAX_AGE_DAYS_LIMIT }),
    );
    expect(
      Object.hasOwn(
        clean({ channels: [BARK], historyMaxAgeDays: HISTORY_MAX_AGE_DAYS_LIMIT + 1 }),
        "historyMaxAgeDays",
      ),
    ).toBe(false);
    // bark timeoutMs：上界与越一格。
    expect(
      clean({ channels: [BROWSER, SYSTEM, { ...BARK, timeoutMs: BARK_TIMEOUT_MS_LIMIT }] })
        .channels,
    ).toEqual([BROWSER, SYSTEM, { ...BARK, timeoutMs: BARK_TIMEOUT_MS_LIMIT }]);
    expect(
      Object.hasOwn(
        channelsOnDisk(
          clean({ channels: [BROWSER, SYSTEM, { ...BARK, timeoutMs: BARK_TIMEOUT_MS_LIMIT + 1 }] }),
        )[2],
        "timeoutMs",
      ),
    ).toBe(false);
    // webhook timeoutSec：区间两端与区间外。
    for (const bound of [WEBHOOK_TIMEOUT.min, WEBHOOK_TIMEOUT.max]) {
      expect(
        clean({ channels: [BROWSER, SYSTEM, { ...HOOK, timeoutSec: bound }] }).channels,
      ).toEqual([BROWSER, SYSTEM, { ...HOOK, timeoutSec: bound }]);
    }
    expect(
      Object.hasOwn(
        channelsOnDisk(
          clean({ channels: [BROWSER, SYSTEM, { ...HOOK, timeoutSec: WEBHOOK_TIMEOUT.max + 1 }] }),
        )[2],
        "timeoutSec",
      ),
    ).toBe(false);
  });

  // 同源守卫（硬要求 #4 的第三半）：**枚举**取值域读 shared。
  //
  // level / auth / preset 三张表都在 shared（与写面、客户端设置页共用）。清理步若另抄一份，用户在设置页
  // 选得到的值会被升级当成非法删掉——症状是「设置页里能选，升级后没声了」。
  it("同源守卫：枚举取值域读 shared（白名单内的逐字保留、表外的删键）", () => {
    const bark = { ...BARK, level: BARK_LEVELS[BARK_LEVELS.length - 1] };
    const hook = {
      ...HOOK,
      auth: WEBHOOK_AUTHS[WEBHOOK_AUTHS.length - 1],
      preset: WEBHOOK_PRESETS[WEBHOOK_PRESETS.length - 1],
    };
    expect(clean({ channels: [BROWSER, SYSTEM, bark, hook] }).channels).toEqual([
      BROWSER,
      SYSTEM,
      bark,
      hook,
    ]);
    // 表外取值：删键但**条目留着**——level / preset 都不是必填键。auth 刻意不在这半边：它是取值域必填键，
    const out = clean({
      channels: [
        BROWSER,
        SYSTEM,
        { ...BARK, level: "nope" },
        { ...HOOK, id: "h:2", preset: "nope" },
      ],
    });
    expect(channelsOnDisk(out).slice(2)).toEqual([
      { type: "bark", id: "bark:1", baseUrl: "https://x", deviceKey: "k" },
      { type: "webhook", id: "h:2", url: "https://y" },
    ]);
  });
});

describe("旧文件归位", () => {
  it.each(ENTRIES)(
    "%s 搬成新布局的 %s：内容逐字保留，旧文件改名留痕",
    (legacyName, targetName, text) => {
      isolatedHome();
      writeLegacy(legacyName, text);

      migrateStorageLayout();

      expect(readFileSync(notifierFile(targetName), "utf8")).toBe(text);
      expect(existsSync(legacyFile(legacyName))).toBe(false);
      expect(readFileSync(`${legacyFile(legacyName)}.migrated.bak`, "utf8")).toBe(text);
    },
  );

  it("没有旧文件时也把初始形态落定（目标不存在会让「这一份处理过了」的判据永远不成立）", () => {
    isolatedHome();
    migrateStorageLayout();

    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe("");
    expect(readFileSync(notifierFile(STATUS_FILE_NAME), "utf8")).toBe("{}\n");
    // 序号文件的初始形态与流侧落盘同形（流侧写 `${seq}\n`）：首次读取要得到 0。
    expect(readFileSync(notifierFile(SEQ_FILE_NAME), "utf8")).toBe("0\n");
  });

  it("目标已存在时只归档旧文件、不覆盖目标（用户可能已经在新位置改过东西，拿历史盖回去就是用旧盖新）", () => {
    const home = isolatedHome();
    mkdirSync(dirname(notifierFile(HISTORY_FILE_NAME)), { recursive: true });
    writeFileSync(notifierFile(HISTORY_FILE_NAME), '{"ts":99}\n', "utf8");
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');

    migrateStorageLayout();

    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe('{"ts":99}\n');
    expect(readFileSync(`${legacyFile("dsh-notifier-history.jsonl")}.migrated.bak`, "utf8")).toBe(
      '{"ts":1}\n',
    );
    expect(readdirSync(home)).toContain("dsh-notifier-history.jsonl.migrated.bak");
  });

  it("重跑不累积归档名（旧文件第一次就改成了固定后缀，第二次已无源文件可归档）", () => {
    const home = isolatedHome();
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');

    migrateStorageLayout();
    migrateStorageLayout();

    expect(readdirSync(home).filter((name) => name.endsWith(".migrated.bak"))).toEqual([
      "dsh-notifier-history.jsonl.migrated.bak",
    ]);
    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe('{"ts":1}\n');
  });

  it("旧文件读不出来即抛（迁移没做完而启动照常，等于让各域按错误的形态去读数据）", () => {
    isolatedHome();
    // 同名目录：路径存在但没有可读内容——「搬不动」不能被当成「没有旧数据」。
    mkdirSync(legacyFile("dsh-notifier-history.jsonl"), { recursive: true });

    expect(() => migrateStorageLayout()).toThrow(/旧存储文件不可读/u);
  });

  // 归档是「这一份处理过了」的标记：改名失败却继续，旧数据就悬在两套布局之间（新位置有了副本，
  // 归档标记却没有），而用户看到的是「迁移成功」。
  it("旧文件改名失败即抛（归档没成功就不能算这一步做完了）", () => {
    isolatedHome();
    const legacy = legacyFile("dsh-notifier-history.jsonl");
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');
    // 归档目标被非空目录占住：rename 覆盖不了它。
    mkdirSync(`${legacy}.migrated.bak`, { recursive: true });
    writeFileSync(join(`${legacy}.migrated.bak`, "占位"), "", "utf8");

    expect(() => migrateStorageLayout()).toThrow(/旧存储文件改名失败/u);
  });
});

