/**
 * file-io 落盘真值回归（#1016）：同路径并发写必须 FIFO、失败不留临时名、权限不随 umask 漂移。
 *
 * 三条判据各自钉一个「测试全绿仍会发生」的真缺陷：
 *  1. **FIFO**：唯一临时名（pid+时间戳+随机后缀）只保证「读到的是某一路的完整 payload」，不保证**是哪一路**——
 *     `rename` 的先后在并发下由调度决定。实测同路径 2000 路并发写，20 轮里 16 轮把旧值覆盖回盘上（最低落到第 1983 路），
 *     而每一次都返回 `ok`：静默丢数据。落到序号文件上就是 seq 回退，客户端按 `seq <= lastSeq` 静默丢帧。
 *     故异步写按目标路径串行，终态必然精确等于**最后提交值**。串行本身还不够：链条 settle 后要**只在表项仍是自己时**
 *     删它，否则前一路落定时的 finally 会把已经排上后继的链摘掉，下一路就此与后继并发开跑（FIFO 静默漏）。
 *  2. **失败清临时名**：临时名带随机后缀，残留不会被下一次写覆盖，攒起来就是目录垃圾；且**原错误**交回调用方，
 *     不被清理的失败或固定兜底串顶替。
 *  3. **显式 mode**：`config.json` 内含 bark deviceKey 与 webhook 凭据，落盘权限不该跟着 umask 走。
 *     目录同理，且既存目录走的是掩码口径 `mode & 0o700`：只保留 owner 三位，group/other（连同 setuid/setgid/
 *     sticky 特殊位）清零（旧安装的 0755 被追溯收紧；运维刻意只读的目录不会被反向打开可写）。
 *
 * 拦的只有 `node:fs/promises` 的 `writeFile` / `rename` 两拍（挂起一拍 / 注入失败），`mkdir`、`rm`、读与
 * 同步 API 全走真实文件系统：并发与失败的判据必须落在真盘上，mock 只用来**制造**那个窗口，不用来替代落盘。
 */
import {
  chmodSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { writeTextAtomic, writeTextAtomicSync } from "../../../src/server/shared/file-io.ts";

/** 落盘闸门：默认全放行，按用例单独开一个窗口（挂起 / 注入失败）。 */
const gate = vi.hoisted(() => ({
  state: {
    /** 已进入的 `writeFile` 次数：等「第一路已经卡在写里」的凭据。 */
    writeCalls: 0,
    /** 下一次 `writeFile` 抛错。 */
    failNextWrite: false,
    /** 下一次 `rename` 抛错（制造「写成功、改名失败」——临时名已存在的那个窗口）。 */
    failNextRename: false,
    /**
     * 按**序号**（`writeCalls` 递增后的值，1 起）拦 `writeFile`。
     *
     * 按序号而不是「下一次」：判 FIFO 时需要同时挂起两路，且必须确定**哪一路**挂在第几个上——
     * 「拦下一次」在两路几乎同时落进 `writeFile` 时由调度决定谁消费掉闸门，判据就成了掷骰子。
     */
    holds: new Map<number, { promise: Promise<void>; release: () => void }>(),
  },
}));

vi.mock("node:fs/promises", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:fs/promises")>();
  return {
    ...actual,
    writeFile: async (...args: Parameters<typeof actual.writeFile>) => {
      gate.state.writeCalls += 1;
      if (gate.state.failNextWrite) {
        gate.state.failNextWrite = false;
        throw new Error("注入：写失败");
      }
      const held = gate.state.holds.get(gate.state.writeCalls);
      if (held !== undefined) await held.promise;
      return actual.writeFile(...args);
    },
    rename: async (...args: Parameters<typeof actual.rename>) => {
      if (gate.state.failNextRename) {
        gate.state.failNextRename = false;
        throw new Error("注入：改名失败");
      }
      return actual.rename(...args);
    },
  };
});

/** 拦下**第 ordinal 次**（1 起）`writeFile`，返回它的放行函数：制造「某一路卡在写里」的窗口。 */
function holdWrite(ordinal: number): () => void {
  let release = (): void => {};
  const promise = new Promise<void>((resolve) => {
    release = resolve;
  });
  gate.state.holds.set(ordinal, { promise, release });
  return release;
}

/** 轮询直到谓词为真；用于等「第一路的 `writeFile` 已被调用」。 */
async function waitFor(predicate: () => boolean, timeoutMs = 2000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (!predicate()) {
    if (Date.now() > deadline) throw new Error("等待 writeFile 调用超时");
    await new Promise((resolve) => setTimeout(resolve, 1));
  }
}

/** 谁先到算谁：写已完成，或等待窗口耗尽。 */
async function settleOrWait(pending: Promise<unknown>, ms: number): Promise<void> {
  await Promise.race([
    pending.then(
      () => undefined,
      () => undefined,
    ),
    new Promise<void>((resolve) => setTimeout(resolve, ms)),
  ]);
}

const dirs: string[] = [];

/** 新建隔离目录：落盘产物一律进 `mkdtemp`，绝不写进仓库或真实 `~/.dsh`。 */
function scratch(): string {
  const dir = mkdtempSync(join(tmpdir(), "dsh-notifier-fileio-"));
  dirs.push(dir);
  return dir;
}

/** 目录里剩下的临时名（实现约定：`<目标>.tmp-<pid>.<时间戳>.<随机>`）。 */
function temporaryLeftovers(dir: string): string[] {
  return readdirSync(dir).filter((name) => name.includes(".tmp-"));
}

beforeEach(() => {
  gate.state.writeCalls = 0;
  gate.state.failNextWrite = false;
  gate.state.failNextRename = false;
  gate.state.holds.clear();
});

afterEach(() => {
  for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
});

describe("writeTextAtomic 并发双写", () => {
  it("20 路同文件并发写全 ok、终态精确等于最后提交值（同路径 FIFO）", async () => {
    const dir = scratch();
    const file = join(dir, "concurrent.json");
    const payloads = Array.from({ length: 20 }, (_, i) => `${JSON.stringify({ i })}\n`);

    const results = await Promise.all(payloads.map((text) => writeTextAtomic(file, text)));
    for (const result of results) expect(result).toEqual({ ok: true });

    // 端到端镜像，判别力在下面两条挂起用例（20 路自身对 FIFO 无判别力：实测完全不打串行时也有绿有红）；
    // 顺带排掉半截混合（半截内容不在任何一个 payload 里）。
    expect(readFileSync(file, "utf8")).toBe(payloads[payloads.length - 1]);
  });

  it("挂起第一路的写再放行：两路同路径并发写，盘上留下的是后写者", async () => {
    const dir = scratch();
    const file = join(dir, "fifo.json");

    const release = holdWrite(1);
    const first = writeTextAtomic(file, "first");
    await waitFor(() => gate.state.writeCalls === 1);
    const second = writeTextAtomic(file, "second");
    // 有队列：second 排在 first 之后，窗口内写不完；无队列：second 当场写完并 rename 到目标。
    await settleOrWait(second, 200);
    release();

    expect(await Promise.all([first, second])).toEqual([{ ok: true }, { ok: true }]);
    expect(readFileSync(file, "utf8")).toBe("second");
  });

  /**
   * settle 守卫 `if (writeChains.get(file) === next)`（file-io.ts 的 finally）是 FIFO 的**承重件**。
   *
   * 漏掉它的那条时序：写 A 挂起 → 写 B 登记（表项已是 B）→ A 落定，finally 若无条件 `delete` 就把 B 的表项抹掉
   * → 此刻才到的写 C 看不到 B，与 B 并发开跑；两次 `rename` 的先后由调度决定，FIFO 静默漏。
   * 无条件 delete 时前两条用例照样全绿（它们不制造「A 落定那一刻已有 B 在等」），所以只能另起一条钉它。
   *
   * 构造：挂起第 1 次写（A）与第 2 次写（B），先放行 A，等 B 确实卡在写里（A 的 finally 此时早已跑完，
   * B 的表项该被守卫保住的正是这一刻），再发起第 3 路 C。判据是 B 挂着期间 C **一次都没被放行过**，
   * 以及盘上终态精确是 C 的。
   */
  it("前一路落定时已有后继在等：第三路仍排在第二路之后（settle 守卫不摘掉后继的表项）", async () => {
    const dir = scratch();
    const file = join(dir, "settle-guard.json");

    const releaseFirst = holdWrite(1);
    const first = writeTextAtomic(file, "first");
    await waitFor(() => gate.state.writeCalls === 1);
    const releaseSecond = holdWrite(2);
    const second = writeTextAtomic(file, "second");

    releaseFirst();
    // 此刻起 B 是唯一的写方（第三路还没发起），故 writeCalls 必然停在 2：B 卡在写里，
    // 且 A 的 finally 早已跑完——B 的表项该被守卫保住的正是这一刻。断言取在这里，两种实现下都确定。
    await waitFor(() => gate.state.writeCalls === 2);
    const third = writeTextAtomic(file, "third");
    // B 还没落定，C 必须继续排在它后面。
    await new Promise((resolve) => setTimeout(resolve, 100));
    const writesWhileHeld = gate.state.writeCalls;
    releaseSecond();

    expect(await Promise.all([first, second, third])).toEqual([
      { ok: true },
      { ok: true },
      { ok: true },
    ]);
    // 终态精确等于第三路：守卫漏掉时 C 与 B 并发开写，B 的 rename 落在 C 之后就把 B 的值盖回去了。
    expect(readFileSync(file, "utf8")).toBe("third");
    // 并发本身的可观测：B 挂着期间 C 一次都没自己开写过（writeCalls 只数到 B 自己那一次）。
    expect(writesWhileHeld).toBe(2);
  });

  it("同路径前一次写失败不毒化后继：后一次仍落盘成功", async () => {
    const dir = scratch();
    const file = join(dir, "poison.json");

    gate.state.failNextWrite = true;
    const failed = writeTextAtomic(file, "first");
    const recovered = writeTextAtomic(file, "second");
    const [first, second] = await Promise.all([failed, recovered]);

    // 一次失败只让**那一次**返回 ok:false：链若被毒化，序号与历史文件会在一次 EACCES/ENOSPC 之后永远写不进去。
    expect(first.ok).toBe(false);
    expect(second).toEqual({ ok: true });
    expect(readFileSync(file, "utf8")).toBe("second");
  });

  it("改名失败时清掉临时名（目录里不留 *.tmp-*）", async () => {
    const dir = scratch();
    const file = join(dir, "cleanup.json");

    gate.state.failNextRename = true;
    const result = await writeTextAtomic(file, "payload");

    expect(result.ok).toBe(false);
    expect(temporaryLeftovers(dir)).toEqual([]);
    // 原错误交回调用方：reason 必须是 rename 自己的文案，不是清理失败或固定兜底串顶替的。
    expect(result).toEqual({ ok: false, reason: expect.stringContaining("注入：改名失败") });
  });

  // POSIX 权限位语义在 win32 上不存在（NTFS 无 mode），故整条跳过而非放宽断言。
  it.skipIf(process.platform === "win32")(
    "新建文件 0600、插件自有目录 0700，父目录保持 umask 语义",
    async () => {
      const root = scratch();
      // 对照目录：与被建出的父目录同处一次 mkdir 递归、同一个 umask，权限相同即证明没被本包改过。
      const control = join(root, "control");
      mkdirSync(control);
      const own = join(root, "@wingsky-1", "dsh-notifier");

      expect(await writeTextAtomic(join(own, "config.json"), "{}\n")).toEqual({ ok: true });
      expect(statSync(join(own, "config.json")).mode & 0o777).toBe(0o600);
      expect(statSync(own).mode & 0o777).toBe(0o700);
      // DSH home 根与 @wingsky-1/ 是宿主与其它插件的共享面：只管自己那一级。
      expect(statSync(join(root, "@wingsky-1")).mode & 0o777).toBe(statSync(control).mode & 0o777);
    },
  );

  // 既存目录的权限口径是 `mode & 0o700`：**只保留 owner 三位，group/other 与特殊位清零**。
  // 这条断言钉的是「不被改成可写」这个不变式，而不是逐位不变——逐位不变是错的命题：
  // 旧安装的 0755/0777 目录正需要被追溯收紧，不收紧才是缺口。
  // 只读目录收成 0500 后**仍然只读**（掩码只做减法，永不新增权限位），所以「写不进去」这条判据不受影响。
  it.skipIf(process.platform === "win32")(
    "既存的只读目录不被改成可写：group/other 被清掉，owner 的写位不新增",
    async () => {
      const root = scratch();
      const own = join(root, "locked");
      mkdirSync(own, { mode: 0o555 });
      // umask 会从 mkdir 的 mode 里再抠一遍，先落成实际值再断言。
      const before = 0o555;
      chmodSync(own, before);

      const result = await writeTextAtomic(join(own, "config.json"), "{}\n");

      // 仍然只读：只读目录被收不紧成可写，运维排故障时才能拿它制造写失败。
      expect(result.ok).toBe(false);
      const mode = statSync(own).mode & 0o777;
      // group/other 被清掉：目录里躺着带凭据的 config.json，不该还有别人的读面。
      expect(mode & 0o077).toBe(0);
      // owner 位原样保留，且没有新增：before 的 owner 位一位不多、一位不少。
      expect(mode & 0o700).toBe(before & 0o700);
      expect(temporaryLeftovers(own)).toEqual([]);
    },
  );

  // 「既存目录完全不 chmod」留下的缺口：旧安装里躺着 0755（甚至 0777）的目录，里面是带凭据的 config.json。
  // 走一次写即被追溯收紧到 0700——masking 只保留 owner 三位，owner 的可写性原样保留，写本身照常成功。
  it.skipIf(process.platform === "win32")(
    "既存的 0755 目录走一次写即被追溯收紧到 0700（异步与同步两条路径同口径）",
    async () => {
      const root = scratch();
      const asyncOwn = join(root, "legacy-async");
      const syncOwn = join(root, "legacy-sync");
      for (const dir of [asyncOwn, syncOwn]) {
        mkdirSync(dir, { mode: 0o755 });
        chmodSync(dir, 0o755);
        expect(statSync(dir).mode & 0o777).toBe(0o755);
      }

      expect(await writeTextAtomic(join(asyncOwn, "config.json"), "{}\n")).toEqual({ ok: true });
      expect(writeTextAtomicSync(join(syncOwn, "version"), "0.2.7\n")).toEqual({ ok: true });

      expect(statSync(asyncOwn).mode & 0o777).toBe(0o700);
      expect(statSync(syncOwn).mode & 0o777).toBe(0o700);
    },
  );

  // sync 版不断言并发（同步函数进不了写链），只保同函数复用：单写往返 + 权限可用即证明同步路径同样走
  // 唯一临时名与显式 mode；它的「无并发」前提记在实现的函数注释里。
  it("同步版单写往返可用（与异步版同走 temporaryNameFor）", () => {
    const dir = scratch();
    const file = join(dir, "sync.json");
    const text = `${JSON.stringify({ hello: "world" })}\n`;

    expect(writeTextAtomicSync(file, text)).toEqual({ ok: true });
    expect(readFileSync(file, "utf8")).toBe(text);
    expect(temporaryLeftovers(dir)).toEqual([]);
  });

  it.skipIf(process.platform === "win32")("同步版落盘同样是文件 0600、目录 0700", () => {
    const root = scratch();
    const own = join(root, "sync-own");

    expect(writeTextAtomicSync(join(own, "version"), "0.2.7\n")).toEqual({ ok: true });
    expect(statSync(join(own, "version")).mode & 0o777).toBe(0o600);
    expect(statSync(own).mode & 0o777).toBe(0o700);
  });
});

packages/dsh-notifier/test/unit/pipeline.source:
/**
 * dsh-notifier pipeline 域 service 块 —— 种类词汇表、装配面与归档。
 *
 * 判据为什么是这些：
 *  - 词汇表（`kinds.ts`）是裁决的坐标系：事件开关、`kindRoutes`、`allowKinds`、bark 紧急度全按它
 *    查，所以「内置 / 外部」的分界与强度的运行时白名单必须各自只有一份答案；
 *  - 装配面是单例：重复装配、卸载后仍收请求、卸载不清节奏状态，都是「上一个用例的状态漏进下一个」
 *    这类最难查的现场；
 *  - 归档是「为什么我没收到」的唯一答案来源，压制分支与发出分支都得留下记录。
 *
 * 装配纪律：`installPipeline` 是模块级单例，故每个用例后必须 `releasePipeline()`——否则下一个
 * `installPipeline` 当场抛「只能装配一次」，且逐频道节奏状态会跨用例延续。
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../../src/server/config/impl/model/type.ts";
import type { DeliverReason } from "../../../src/server/shared/interface.ts";
import type {
  ChannelsPort,
  HistoryEntry,
  NotifyMessage,
  OutgoingFrame,
  PipelineDeps,
} from "../../../src/server/pipeline/deps.ts";
import {
  BUILTIN_KINDS,
  KIND_SEVERITY,
  NOTIFY_SEVERITIES,
  isBuiltinKind,
  isNotifySeverity,
} from "../../../src/server/pipeline/impl/service/kinds.ts";
import {
  installPipeline,
  releasePipeline,
  submit,
} from "../../../src/server/pipeline/interface.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/interface.ts";
import { makeLogger, pollUntil, settleMicrotasks } from "../../helpers.ts";

/** 出站频道配置与帧载荷：经设置模型 / 域依赖声明可达，不必请别的块再导出一个名字。 */
type ChannelConfig = NotifyConfig["channels"][number];
type BarkConfig = Extract<ChannelConfig, { type: "bark" }>;

/** 装配面夹具：只伪 `pipeline/deps.ts` 声明的那几个端口，顺手记下四件观测物。 */
interface Harness {
  readonly deps: PipelineDeps;
  readonly history: HistoryEntry[];
  readonly statuses: Array<{
    channelId: string;
    status: "ok" | "failed";
    error: DeliverReason | undefined;
  }>;
  readonly delivered: Array<{ message: NotifyMessage; targets: readonly DeliveryTarget[] }>;
  readonly frames: OutgoingFrame[];
  readonly logger: ReturnType<typeof makeLogger>;
  /** 换掉这一刻生效的设置（设置是活的：装配期算出的快照会变成静态数据）。 */
  readonly useConfig: (patch?: Partial<NotifyConfig>) => void;
  /** 换掉投递出口的行为（缺省：全部送到）。 */
  readonly onDeliver: (deliver: ChannelsPort["deliver"]) => void;
}

type DeliveryTarget = Parameters<ChannelsPort["deliver"]>[1][number];

function configAt(patch: Partial<NotifyConfig> = {}): NotifyConfig {
  return { ...DEFAULT_CONFIG, ...patch };
}

function requestOf(over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind: "done", title: "标题", body: "正文", ...over };
}

function barkChannel(over: Partial<BarkConfig> = {}): BarkConfig {
  return {
    type: "bark",
    id: "a",
    enabled: true,
    baseUrl: "http://127.0.0.1:40281/bark",
    deviceKey: "dk",
    ...over,
  };
}

/** 默认表里的内置频道：泛型只为把「按 type 找到的那条」收窄成对应型号——查找条件就是 type 相等。 */
function builtinOf<T extends "browser" | "system">(type: T): Extract<ChannelConfig, { type: T }> {
  const found = DEFAULT_CONFIG.channels.find((channel) => channel.type === type);
  if (found === undefined) throw new Error(`默认表里缺内置频道 ${type}`);
  return found as Extract<ChannelConfig, { type: T }>;
}

/**
 * 两条内置出口都停用：`channels` 是唯一关得掉它们的地方——顶层 `browserNotify` / `systemSound`
 * 一类键现在只是读面派生出来的只读投影，改它们不会让内置出口少投一次。
 */
function builtinsOff(): ChannelConfig[] {
  return [
    { ...builtinOf("browser"), enabled: false },
    { ...builtinOf("system"), enabled: false },
  ];
}

/** 只留 system 出口的设置：节流用例要「唯一目标」才数得清投递次数。 */
function systemOnly(patch: Partial<NotifyConfig> = {}): Partial<NotifyConfig> {
  return {
    // 内置两频道恒在 `channels` 里：停用 browser，只留 system（弹窗开、声音关，这一次有实际动作）。
    channels: [
      { ...builtinOf("browser"), enabled: false },
      { ...builtinOf("system"), enabled: true, popup: true, sound: false },
    ],
    ...patch,
  };
}

function assemble(over: Partial<PipelineDeps> = {}): Harness {
  const history: HistoryEntry[] = [];
  const statuses: Harness["statuses"][number][] = [];
  const delivered: Harness["delivered"][number][] = [];
  const frames: OutgoingFrame[] = [];
  const logger = makeLogger();
  const state: { config: NotifyConfig; deliver: ChannelsPort["deliver"] } = {
    config: DEFAULT_CONFIG,
    deliver: async (message, targets) => {
      delivered.push({ message, targets });
      return targets.map(() => ({ status: "ok", stage: "delivered" }));
    },
  };
  const deps: PipelineDeps = {
    enabled: true,
    frames: {
      emit: (payload) => {
        frames.push(payload);
      },
    },
    logger,
    config: { readConfig: () => state.config },
    stores: {
      appendHistory: (entry) => {
        history.push(entry);
      },
      recordStatus: (channelId, status, error) => {
        statuses.push({ channelId, status, error });
      },
    },
    channels: { deliver: (message, targets) => state.deliver(message, targets) },
    ...over,
  };
  installPipeline(deps);
  return {
    deps,
    history,
    statuses,
    delivered,
    frames,
    logger,
    useConfig: (patch = {}) => {
      state.config = configAt(patch);
    },
    onDeliver: (deliver) => {
      state.deliver = deliver;
    },
  };
}

afterEach(() => {
  releasePipeline();
  vi.useRealTimers();
});

describe("种类词汇表", () => {
  // 命名空间撞内置名被判成内置，等于绕过用户确认直接放行一条无归属的通知。
  it("isBuiltinKind 只认内置名；内置名一律不含冒号，与 `<命名空间>:<id>` 天然不相交", () => {
    for (const kind of BUILTIN_KINDS) {
      expect(isBuiltinKind(kind), kind).toBe(true);
    }
    // 撞上内置名的外部 kind 会被误判成内置，而误判方向恰好是「绕过用户确认直接放行」。
    for (const kind of ["ask:foo", "done:x", "ASK", "Ask", "ask ", " ask", "", "unknown"]) {
      expect(isBuiltinKind(kind), kind).toBe(false);
    }
    expect(BUILTIN_KINDS.filter((kind) => kind.includes(":"))).toEqual([]);
  });

  // 运行时白名单漏一档，合法强度会被静默判非法并回落缺省。
  it("强度白名单与值表互相覆盖：运行时白名单漏一档，合法强度会被静默判非法并回落缺省", () => {
    expect(NOTIFY_SEVERITIES).toEqual(["info", "success", "warning", "failure"]);
    for (const kind of BUILTIN_KINDS) {
      expect(NOTIFY_SEVERITIES, kind).toContain(KIND_SEVERITY[kind]);
    }
  });

  // 大小写或空白差异被放行，下游出口会拿到一个查不到映射的档位。
  it("isNotifySeverity 边界：大小写与未知档一律判非法（跨边界值不得被放行）", () => {
    for (const severity of NOTIFY_SEVERITIES) {
      expect(isNotifySeverity(severity), severity).toBe(true);
    }
    for (const value of ["", "Info", "INFO", "critical", " urgency", "info "]) {
      expect(isNotifySeverity(value), value).toBe(false);
    }
  });
});

describe("装配面：单例语义", () => {
  // 未装配时抛错会打断宿主事件链上别人的流程——本方法正是挂在事件链上的。
  it("未装配（或已卸载）时 submit 静默丢弃、release 幂等：宿主事件链上抛错会打断别人的流程", () => {
    expect(() => submit(requestOf())).not.toThrow();

    const harness = assemble();
    releasePipeline();
    expect(() => {
      submit(requestOf());
      releasePipeline();
    }).not.toThrow();
    expect(harness.history).toEqual([]);
    expect(harness.delivered).toEqual([]);
  });

  // 重复装配静默换掉能力面，会让同一进程里出现两套裁决配置。
  it("重复装配当场抛错：单例实例上再装一次是编程错误，不该静默换掉能力面", () => {
    assemble();
    expect(() => assemble()).toThrow(/只能装配一次/u);
  });
});

describe("归档：发出与压制只在载荷上分叉", () => {
  // 压制不落史，用户问「为什么没收到」时没有任何可查的证据。
  it("总开关关：记 suppressed=disabled 且零投递（用户看不到通知时，历史里要有理由）", () => {
    const harness = assemble({ enabled: false });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    expect(harness.history).toHaveLength(1);
    expect(harness.history[0]!.suppressed).toBe("disabled");
    expect(harness.history[0]!.channels).toBeUndefined();
  });

  // 频道全关是合法配置，把它记成发送成功会掩盖「一条都没发出去」。
  it("一个目标都没有：记 suppressed=no-target，而不是一条空的成功记录", () => {
    const harness = assemble();
    harness.useConfig({ channels: builtinsOff() });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    expect(harness.history[0]!.suppressed).toBe("no-target");
  });

  // 两处各取一次时刻，就会出现「历史 12:00:00、收到的通知 12:00:01」。
  it("发出归档：投递载荷与历史记录共用同一个 ts，文案逐字一致", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), barkChannel()] });
    const before = Date.now();
    submit(requestOf({ title: "标题", body: "正文" }));
    await settleMicrotasks();
    const after = Date.now();

    const entry = harness.history[0]!;
    const message = harness.delivered[0]!.message;
    // 两处各取一次时刻是真实的回归形态：历史显示 12:00:00，收到的通知却是 12:00:01。
    expect(entry.ts).toBe(message.ts);
    expect(entry.ts).toBeGreaterThanOrEqual(before);
    expect(entry.ts).toBeLessThanOrEqual(after);
    expect(message.title).toBe("标题");
    expect(message.body).toBe("正文");
    expect(entry.title).toBe("标题");
    expect(entry.message).toBe("正文");
    expect(entry.kind).toBe("done");
  });

  // 日志口径与归档口径不同词，排查时「按日志找记录」这一步就对不上。
  it("kindRoutes 指向已删除频道：warn 与归档同一口径（suppressed:no-target），不静默也不自称 skipped", () => {
    const harness = assemble();
    harness.useConfig({ channels: builtinsOff(), kindRoutes: { done: ["bark:gone"] } });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    const archived = harness.history[0]!.suppressed;
    expect(archived).toBe("no-target");
    expect(harness.logger.warns).toHaveLength(1);
    expect(harness.logger.warns[0]).toContain("kindRoutes[done]");
    expect(harness.logger.warns[0]).toContain("bark:gone");
    // 日志点名的那条口径就是历史里记下的那条：`SuppressReason` 里没有 skipped 这个词。
    expect(harness.logger.warns[0]).toContain(`suppressed:${archived}`);
    expect(harness.logger.warns[0]).not.toContain("skipped");
  });

  // 有别的目标时通知照常发出，此时谎称「本条按 suppressed 归档」会把排查引向一条不存在的记录。
  it("stale 但仍有其它目标：其余目标照常投递，warn 不谎称本条通知按 suppressed 归档", async () => {
    const harness = assemble();
    harness.useConfig({
      channels: [...builtinsOff(), barkChannel()],
      kindRoutes: { done: ["bark:gone", "bark:a"] },
    });
    submit(requestOf());
    await settleMicrotasks();

    expect(harness.history[0]!.channels).toEqual([{ channelId: "bark:a", status: "ok" }]);
    expect(harness.logger.warns).toHaveLength(1);
    expect(harness.logger.warns[0]).toContain("bark:gone");
    expect(harness.logger.warns[0]).not.toContain("suppressed:");
  });

  // 节奏状态跨装配期存活，会把上一次运行窗口的节流带进新一次装配。
  it("release 清空逐频道节奏状态：卸载再装配后同一频道重新计时，节流不跨装配期存活", async () => {
    const harness = assemble();
    harness.useConfig(systemOnly());
    vi.setSystemTime(new Date(2026, 0, 15, 12, 0, 0));

    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(1);

    // 同一时刻的第二条：落在 system 出口的 1 秒节流窗口里，不产生第二次投递。
    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(1);
    expect(harness.history).toHaveLength(2);

    releasePipeline();
    installPipeline(harness.deps);
    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(2);
  });

  // 归档面违约发生在投递之后：不在这里收口，「通知发出去了但历史里没有」就只剩一个未捕获拒绝，
  // 而它挂在宿主事件链上，抛出去会打断别人的流程。
  it("归档面违约经「投递失败」告警收口：既不抛穿，也不静默（这是这条通知唯一的痕迹）", async () => {
    const logger = makeLogger();
    assemble({
      logger,
      stores: {
        appendHistory: () => {
          throw new Error("历史文件不可写");
        },
        recordStatus: () => {},
      },
    });

    submit(requestOf());
    await pollUntil(() => logger.warns.length === 1, "归档违约经日志收口");
    expect(logger.warns[0]).toContain("投递失败");
    expect(logger.warns[0]).toContain("历史文件不可写");
  });
});

packages/dsh-notifier/test/integration/s.source:
/**
 * dsh-notifier — #912 症状2端到端：dispatch 到 stores 到 GET /status 到 statusText，
 * 以及 POST /test fire-and-forget 时序。
 *
 * 真裁决管线 + 真 stores（隔离 DSH_HOME 落盘）+ 真 journal 端点 + 真客户端 statusText。
 * 投递出口是假件（秒回 failed/skipped，不起子进程、不联网）；落盘进隔离临时目录。
 * 不改 skipped 值域（ok/failed 锁死）：skipped 那条走历史直达到 statusText。
 */
import { rmSync } from "node:fs";
import { afterAll, afterEach, beforeEach, describe, expect, it } from "vitest";

import { DEFAULT_CONFIG } from "../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../src/server/config/impl/model/type.ts";
import {
  HISTORY_FILE_NAME,
  STATUS_FILE_NAME,
  notifierFile,
} from "../../src/server/shared/interface.ts";
import type { NotifyMessage } from "../../src/server/pipeline/deps.ts";
import type { PipelineDeps } from "../../src/server/pipeline/deps.ts";
import type { DeliveryTarget } from "../../src/server/channels/interface.ts";
import type { DeliverResult } from "../../src/server/channels/impl/deliver/type.ts";
import { JournalEndpoints } from "../../src/server/api/impl/journal/index.ts";
import { ProbeEndpoints } from "../../src/server/api/impl/probe/index.ts";
import type { ChannelPort } from "../../src/server/api/deps.ts";
import { zh } from "../../src/client/locales.ts";
import { statusText } from "../../src/client/settings/parts/status.tsx";
import type { ChannelStatusMap } from "../../src/client/settings/parts/status.tsx";
import { jsonReq, makeLogger, makeRes, tempDshHome } from "../helpers.ts";
import { translateWithZh } from "../client-helpers.ts";

// 导入顺序纪律（同 stores/status.test.ts）：单例落盘路径在构造时定下，静态 import 会在
// 任何语句之前求值——顺序反了，落盘就写进真实 DSH home。impl 单例走 await import，且必须
// 在 tempDshHome() 之后。
const home = tempDshHome();
const historyFile = notifierFile(HISTORY_FILE_NAME);
const statusFile = notifierFile(STATUS_FILE_NAME);
const storeApi = await import("../../src/server/stores/interface.ts");
const pipelineApi = await import("../../src/server/pipeline/interface.ts");
// probe 构造要的 dry-run 出站与 config 纯函数（动态导入与上同纪）。
const { dryRunTarget } = await import("../../src/server/channels/interface.ts");
const { finalizeRequest, barkTarget, browserTarget, systemTarget, webhookTarget } =
  await import("../../src/server/pipeline/interface.ts");
const { resolveDraftChannels, normalizeConfig } =
  await import("../../src/server/config/interface.ts");

const installStores = storeApi.installStores;
const releaseStores = storeApi.releaseStores;
const appendHistory = storeApi.appendHistory;
const recordStatus = storeApi.recordStatus;
const readHistory = storeApi.readHistory;
const readStatus = storeApi.readStatus;
const clearHistory = storeApi.clearHistory;
const installPipeline = pipelineApi.installPipeline;
const releasePipeline = pipelineApi.releasePipeline;
const submit = pipelineApi.submit;

/** 装配真管线 + 真 stores，投递出口由调用方注入（假件，不联网）。 */
function assemble(
  deliver: (message: NotifyMessage, targets: DeliveryTarget[]) => Promise<DeliverResult[]>,
) {
  const logger = makeLogger();
  const config: NotifyConfig = { ...DEFAULT_CONFIG };
  installStores({ logger, config: { readConfig: () => ({ ...config }) } });
  const deps: PipelineDeps = {
    enabled: true,
    frames: { emit: () => {} },
    logger,
    config: { readConfig: () => ({ ...config }) },
    stores: { appendHistory, recordStatus },
    channels: { deliver },
  };
  installPipeline(deps);
  return new JournalEndpoints({ readHistory, clearHistory, readStatus });
}

beforeEach(() => {
  rmSync(historyFile, { force: true });
  rmSync(statusFile, { recursive: true, force: true });
});

afterEach(() => {
  releasePipeline();
  releaseStores();
});

afterAll(() => {
  home.dispose();
});

/** 等到历史出现 test 记录（落盘队列是异步的，等可见而不是等固定时长）。 */
async function pollTestHistory() {
  const deadline = Date.now() + 10_000;
  for (;;) {
    const records = await readHistory();
    const found = records.filter((record) => record.kind === "test");
    if (found.length > 0) return found;
    if (Date.now() > deadline) throw new Error("测试通知在 10s 内未落史");
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
}

/** 等到某频道的状态条目出现（内存镜像即时，等的是异步投递走完）。 */
async function pollStatusEntry(channelId: string) {
  const deadline = Date.now() + 10_000;
  for (;;) {
    const map = await readStatus();
    if (map[channelId] !== undefined) return map;
    if (Date.now() > deadline) throw new Error("频道状态在 10s 内未出现");
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
}

describe("dispatch 到 stores 到 GET /status 到 statusText（真 failed 翻页）", () => {
  it("失败投递经状态端点读回 failed，statusText 显示最近投递失败", async () => {
    const journal = assemble((_message, targets) =>
      Promise.resolve(
        targets.map(() => ({
          status: "failed",
          stage: "delivered",
          reason: { code: "reasonSystemPopupFailed", params: { bin: "notify-send" } },
          retryable: false,
        })),
      ),
    );
    submit({ kind: "test", title: "标题", body: "正文" });

    const historyFound = await pollTestHistory();
    // 三面一致其一：同一条 test 记录里 system 即失败（含投递原因码）
    const historyChannels = historyFound[0].channels ?? [];
    const failedItem = historyChannels.find((item) => item.channelId === "system");
    expect(failedItem?.status).toBe("failed");
    expect(failedItem?.reason?.code).toBe("reasonSystemPopupFailed");
    const map = await pollStatusEntry("system");
    const systemEntry = map.system;
    expect(systemEntry && systemEntry.lastStatus).toBe("failed");
    expect(systemEntry && typeof systemEntry.lastTs).toBe("number");

    const made = makeRes();
    await journal.readStatus(jsonReq({ method: "GET", url: "/api/dsh-notifier/status" }), made.res);
    expect(made.rec.status).toBe(200);
    const channels = made.json().channels as Record<string, { lastStatus: string; lastTs: number }>;
    const got = channels.system;
    expect(got && got.lastStatus).toBe("failed");
    expect(got && typeof got.lastTs).toBe("number");

    const text = statusText("system", channels as ChannelStatusMap, translateWithZh);
    expect(text).toContain(zh.chLastFail);
  });

  it("skipped 不写状态但落历史：状态端点无条目，statusText 经历史直达给解释", async () => {
    const journal = assemble((_message, targets) =>
      Promise.resolve(
        targets.map(() => ({ status: "skipped", reason: { code: "reasonSkipConfig" } })),
      ),
    );
    submit({ kind: "test", title: "标题", body: "正文" });

    const found = await pollTestHistory();
    const first = found[0];
    expect(first && first.channels).toContainEqual({
      channelId: "system",
      status: "skipped",
      reason: { code: "reasonSkipConfig" },
    });

    const made = makeRes();
    await journal.readStatus(jsonReq({ method: "GET", url: "/api/dsh-notifier/status" }), made.res);
    expect(made.rec.status).toBe(200);
    // skipped 没有“最后一次投递结论”：状态表里没有该频道的键（值域 ok/failed 锁死）。
    expect(made.json().channels).toEqual({});

    const records = await readHistory();
    const text = statusText("system", {}, translateWithZh, records);
    expect(text).toContain(zh.chNeverSent);
    expect(text).toContain(zh.reasonSkipConfig);
    expect(text).toContain(zh.chSkippedSeeHistory);
  });
});

describe("POST /test 时序：先 200 受理，投递终态随后才可见", () => {
  it("响应返回时历史为空；放行投递后历史与状态相继出现", async () => {
    let releaseGate: (() => void) | undefined;
    const gate = new Promise<void>((resolve) => {
      releaseGate = resolve;
    });
    const logger = makeLogger();
    const config: NotifyConfig = { ...DEFAULT_CONFIG };
    installStores({ logger, config: { readConfig: () => ({ ...config }) } });
    installPipeline({
      enabled: true,
      frames: { emit: () => {} },
      logger,
      config: { readConfig: () => ({ ...config }) },
      stores: { appendHistory, recordStatus },
      channels: {
        deliver: (_message, targets) =>
          gate.then((): DeliverResult[] =>
            targets.map(() => ({ status: "ok", stage: "delivered" })),
          ),
      },
    });
    const channels: ChannelPort = {
      probeCapabilities: () => Promise.reject(new Error("本用例不探测")),
      hostPlatform: () => "linux",
      undeterminedCapabilities: () => {
        throw new Error("本用例不探测");
      },
      dryRunTarget,
    };
    const probe = new ProbeEndpoints(
      {
        submit,
        finalizeRequest,
        barkTarget,
        browserTarget,
        systemTarget,
        webhookTarget,
      },
      channels,
      makeLogger(),
      {
        readConfig: () => ({ ...config }),
        readSettingsView: () => {
          throw new Error("本用例不读视图");
        },
        writeConfig: () => Promise.reject(new Error("本用例不写配置")),
        resolveDraftChannels,
        normalizeConfig,
      },
    );

    const made = makeRes();
    await probe.test(
      jsonReq({ method: "POST", url: "/api/dsh-notifier/test", body: {} }),
      made.res,
    );
    expect(made.rec.status).toBe(200);
    expect(made.json()).toEqual({ ok: true, sseConnections: 0 });
    // fire-and-forget：响应只承诺已受理，投递还在门后——此刻历史必须仍是空的。
    expect(await readHistory()).toEqual([]);

    if (releaseGate !== undefined) releaseGate();
    const released = await pollTestHistory();
    const releasedChannels = released[0].channels ?? [];
    const okItem = releasedChannels.find((item) => item.channelId === "browser");
    expect(okItem?.status).toBe("ok");
    const map = await pollStatusEntry("browser");
    const browserEntry = map.browser;
    expect(browserEntry && browserEntry.lastStatus).toBe("ok");
  });
});

