/**
 * dsh-notifier upgrade 域 legacy reader：正式历史来源是 DSH home 的 settings.yaml 与
 * settings.yaml.imported；describe 与 V0 JSON 只作低优先级兜底。
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import {
  CONFIG_FILE_NAME,
  legacyFile,
  notifierFile,
} from "../../../src/server/shared/interface.ts";
import { readLegacySettings } from "../../../src/server/upgrade/impl/legacy/index.ts";
import { migrateConfigShape } from "../../../src/server/upgrade/impl/steps/config-shape.ts";
import type { LegacySettingsFace } from "../../../src/server/upgrade/impl/legacy/type.ts";
import { tempDshHome } from "../../helpers.ts";

/** 本插件 0.2.3 在旧官方 settings 文档里的命名空间。 */
const NS = "dsh-notifier";

type FakeDescriptor = { ns: string; user?: unknown };
type FakeDescribeOptions = { redactSecrets?: boolean };

let home: { readonly dir: string; dispose: () => void };

beforeEach(() => {
  home = tempDshHome();
});

afterEach(() => {
  home.dispose();
});

/** 假 settings 读面只提供 describe；正式文件由 DSH_HOME 下的真实路径读取。 */
function makeSettings(entries: readonly FakeDescriptor[], throws = false): LegacySettingsFace {
  return {
    describe: () => {
      if (throws) throw new Error("settings 服务拒绝了这次调用");
      return entries as unknown as ReturnType<LegacySettingsFace["describe"]>;
    },
  };
}

function writeSettingsDocument(text: string, name = "settings.yaml"): string {
  const path = join(home.dir, name);
  writeFileSync(path, text, "utf8");
  return path;
}

function writeLegacyFile(name: string, body: unknown): void {
  writeFileSync(legacyFile(name), typeof body === "string" ? body : JSON.stringify(body), "utf8");
}

describe("正式 legacy settings 来源", () => {
  it("只有 settings.yaml.imported 时也能读到旧 notifier 分节", () => {
    writeSettingsDocument(
      "dsh-notifier:\n  notifyAsk: false\n  notifyTaskDone: true\n",
      "settings.yaml.imported",
    );

    expect(readLegacySettings(makeSettings([]))).toEqual({
      notifyAsk: false,
      notifyTaskDone: true,
    });
  });

  it("settings.yaml 高于 imported；普通对象递归合并，数组与标量整体替换", () => {
    writeSettingsDocument(
      `dsh-notifier:
  notifyTaskDone: true
  nested:
    importedOnly: 7
    shared: imported
    items:
      - imported
  scalarConflict: imported
`,
      "settings.yaml.imported",
    );
    writeSettingsDocument(
      `dsh-notifier:
  notifyTaskDone: false
  nested:
    currentOnly: 8
    shared: current
    items:
      - current
  scalarConflict: current
`,
    );

    expect(readLegacySettings(makeSettings([]))).toEqual({
      notifyTaskDone: false,
      nested: {
        currentOnly: 8,
        importedOnly: 7,
        shared: "current",
        items: ["current"],
      },
      scalarConflict: "current",
    });
  });

  it("正式双文件整体高于 describe 与 V0 JSON", () => {
    writeSettingsDocument("dsh-notifier:\n  notifyAsk: false\n  customKey: official\n");
    writeLegacyFile("dsh-notifier.json", { notifyAsk: true, customKey: "v0" });
    const settings = makeSettings([{ ns: NS, user: { notifyAsk: true, customKey: "describe" } }]);

    expect(readLegacySettings(settings)).toEqual({ notifyAsk: false, customKey: "official" });
  });

  it.each(["settings.yaml", "settings.yaml.imported"])("%s 存在但 YAML 损坏时明确失败", (name) => {
    writeSettingsDocument("dsh-notifier:\n\tnotifyAsk: false\n", name);

    expect(() => readLegacySettings(makeSettings([]))).toThrow(
      new RegExp(name.replace(".", "\\.")),
    );
  });

  it.each(["settings.yaml", "settings.yaml.imported"])("%s 存在但不可读时明确失败", (name) => {
    mkdirSync(join(home.dir, name));

    expect(() => readLegacySettings(makeSettings([]))).toThrow(
      new RegExp(name.replace(".", "\\.")),
    );
  });

  it.each([
    ["just a scalar\n", /顶层不是普通对象/],
    ["dsh-notifier: scalar\n", /分节不是普通对象/],
    ["dsh-notifier: &self\n  notifyAsk: false\n  self: *self\n", /分节无法序列化/],
  ])("正式来源内容无效时明确失败：%s", (text, error) => {
    writeSettingsDocument(text);

    expect(() => readLegacySettings(makeSettings([]))).toThrow(error);
  });

  it("重复读取正式来源不改写源文件", () => {
    const path = writeSettingsDocument(
      "dsh-notifier:\n  notifyAsk: false\n",
      "settings.yaml.imported",
    );
    const before = readFileSync(path, "utf8");

    const first = readLegacySettings(makeSettings([]));
    const second = readLegacySettings(makeSettings([]));

    expect(first).toEqual({ notifyAsk: false });
    expect(second).toEqual(first);
    expect(readFileSync(path, "utf8")).toBe(before);
  });

  it("重复运行配置形态割接得到逐字相同的结果", () => {
    writeSettingsDocument(
      "dsh-notifier:\n  notifyAsk: true\n  notifyTaskDone: false\n",
      "settings.yaml.imported",
    );
    writeSettingsDocument("dsh-notifier:\n  notifyAsk: false\n");
    const configFile = notifierFile(CONFIG_FILE_NAME);

    migrateConfigShape(makeSettings([]));
    const first = readFileSync(configFile, "utf8");
    migrateConfigShape(makeSettings([]));
    const second = readFileSync(configFile, "utf8");

    expect(JSON.parse(first)).toMatchObject({ notifyAsk: false, notifyTaskDone: false });
    expect(second).toBe(first);
  });
});

describe("低优先级兜底：describe → V0 JSON", () => {
  it("正式来源没有 notifier 分节时使用 describe", () => {
    writeSettingsDocument("other-plugin:\n  value: 1\n");
    const settings = makeSettings([{ ns: NS, user: { notifyAsk: false } }]);

    expect(readLegacySettings(settings)).toEqual({ notifyAsk: false });
  });

  it("describe 高于 V0 JSON", () => {
    writeLegacyFile("dsh-notifier.json", { notifyAsk: true });
    const settings = makeSettings([{ ns: NS, user: { notifyAsk: false } }]);

    expect(readLegacySettings(settings)).toEqual({ notifyAsk: false });
  });

  it("describe 条目存在但 user 不是普通对象时回退 V0 JSON", () => {
    writeLegacyFile("dsh-notifier.json", { notifyAsk: true });
    for (const user of [["notifyAsk"], "notifyAsk", 42, null]) {
      expect(readLegacySettings(makeSettings([{ ns: NS, user }]))).toEqual({ notifyAsk: true });
    }
  });

  it("读 describe 时要求脱敏", () => {
    const calls: Array<FakeDescribeOptions | undefined> = [];
    const settings: LegacySettingsFace = {
      describe: (options) => {
        calls.push(options);
        return [{ ns: NS, user: { notifyAsk: false } }] as unknown as ReturnType<
          LegacySettingsFace["describe"]
        >;
      },
    };

    expect(readLegacySettings(settings)).toEqual({ notifyAsk: false });
    expect(calls).toEqual([{ redactSecrets: true }]);
  });

  it("describe 调用抛错时回退 V0 JSON", () => {
    writeLegacyFile("dsh-notifier.json", { notifyAsk: true });

    expect(readLegacySettings(makeSettings([], true))).toEqual({ notifyAsk: true });
  });

  it("运行时额外 documentPath getter 被读取就抛，reader 不回退旧路径", () => {
    const settings = {
      describe: () =>
        [{ ns: NS, user: { notifyAsk: false } }] as unknown as ReturnType<
          LegacySettingsFace["describe"]
        >,
      get documentPath(): string {
        throw new Error("documentPath 不得被读取");
      },
    };

    expect(readLegacySettings(settings)).toEqual({ notifyAsk: false });
  });

  it("V0 的第二个候选名在 json 缺失时生效", () => {
    writeLegacyFile("dsh-notifier.json.migrated.bak", { notifyAsk: false });

    expect(readLegacySettings(makeSettings([]))).toEqual({ notifyAsk: false });
  });

  it("V0 JSON 损坏时明确失败并保留原文件", () => {
    writeLegacyFile("dsh-notifier.json", "{ 这不是 JSON");

    expect(() => readLegacySettings(makeSettings([]))).toThrow(/JSON 解析失败/);
    expect(existsSync(legacyFile("dsh-notifier.json"))).toBe(true);
  });

  it("V0 JSON 顶层不是普通对象时明确失败", () => {
    writeLegacyFile("dsh-notifier.json", [1, 2]);

    expect(() => readLegacySettings(makeSettings([]))).toThrow(/顶层不是普通对象/);
  });

  it("所有来源都不存在时返回空对象", () => {
    expect(readLegacySettings(makeSettings([]))).toEqual({});
  });
});

describe("旧键语义转换与安全边界", () => {
  it("正式来源剔除装配键并把旧全局音效键摊到两个出口", () => {
    writeSettingsDocument(
      "dsh-notifier:\n  enabled: true\n  configFile: /legacy/config.json\n  notifySound: false\n  notifyTaskDone: false\n",
    );

    expect(readLegacySettings(makeSettings([]))).toEqual({
      notifySound: false,
      notifyTaskDone: false,
      browserSound: false,
      systemSound: false,
    });
  });

  it("出口键已有值时不被旧全局声音键覆盖", () => {
    writeSettingsDocument(
      "dsh-notifier:\n  notifySound: true\n  browserSound: false\n",
      "settings.yaml.imported",
    );
    writeSettingsDocument("dsh-notifier:\n  browserSound: false\n");

    const legacy = readLegacySettings(makeSettings([]));
    expect(legacy.browserSound).toBe(false);
    expect(legacy.systemSound).toBe(true);
  });

  it("契约不认识的键原样保留", () => {
    writeSettingsDocument("dsh-notifier:\n  customKey: 42\n  notifyAsk: true\n");

    const legacy = readLegacySettings(makeSettings([]));
    expect(legacy.customKey).toBe(42);
    expect(legacy.notifyAsk).toBe(true);
  });

  it("原型链上的危险键名不搬运", () => {
    writeSettingsDocument(
      `{"dsh-notifier":{"notifyAsk":true,"__proto__":{"polluted":true},"constructor":"x","prototype":"y"}}`,
    );

    const out = readLegacySettings(makeSettings([]));
    expect(out).toEqual({ notifyAsk: true });
    expect(Object.getPrototypeOf(out)).toBe(Object.prototype);
  });
});

/**
 * dsh-notifier upgrade 域 0.2.3 → 0.2.4 的**投递理由形态割接**（#782 批 1）。
 *
 * 判据面：这一步把磁盘上的散文理由重写成结构化对象，而它动的是**用户数据**。写错的表现是
 * 「通知记录里理由变成 undefined」或「重跑把已经割接过的行又套一层」，用户只会看到历史页坏了。
 * 故逐条锁：旧形态被收编、新形态原样保留、坏内容不动那个文件、重跑幂等。
 */
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { afterEach, describe, expect, it, vi } from "vitest";

import {
  HISTORY_FILE_NAME,
  STATUS_FILE_NAME,
  notifierFile,
} from "../../../src/server/shared/interface.ts";
import * as fileIo from "../../../src/server/shared/file-io.ts";
import { migrateReasonShape } from "../../../src/server/upgrade/impl/steps/reason-shape.ts";
import { tempDshHome } from "../../helpers.ts";

const cleanups: Array<() => void> = [];

afterEach(() => {
  for (const dispose of cleanups.splice(0)) dispose();
});

function isolatedHome(): void {
  const home = tempDshHome();
  cleanups.push(home.dispose);
}

/** 写一份存储文件；先清掉同名目录（失败面用例会把目标位置占成目录）。 */
function write(file: string, text: string): void {
  rmSync(file, { recursive: true, force: true });
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, text, "utf8");
}

function read(file: string): string {
  return readFileSync(file, "utf8");
}

describe("status.json 的理由形态割接", () => {
  it("lastError 的散文收编成 reasonLegacy + detail，其余字段逐字保留", () => {
    isolatedHome();
    write(
      notifierFile(STATUS_FILE_NAME),
      `${JSON.stringify(
        {
          "bark:old": { lastTs: 9, lastStatus: "failed", lastError: "连接超时", failStreak: 3 },
          "bark:new": {
            lastTs: 10,
            lastStatus: "failed",
            lastError: { code: "reasonBarkHttp", params: { status: 401 } },
            failStreak: 1,
          },
          "bark:ok": { lastTs: 11, lastStatus: "ok", failStreak: 0 },
        },
        null,
        2,
      )}\n`,
    );

    migrateReasonShape();

    const stored = JSON.parse(read(notifierFile(STATUS_FILE_NAME))) as Record<
      string,
      Record<string, unknown>
    >;
    expect(stored["bark:old"]).toEqual({
      lastTs: 9,
      lastStatus: "failed",
      lastError: { code: "reasonLegacy", detail: "连接超时" },
      failStreak: 3,
    });
    // 已经是结构化对象的原样保留（重跑不叠加、不套壳）
    expect(stored["bark:new"].lastError).toEqual({
      code: "reasonBarkHttp",
      params: { status: 401 },
    });
    expect(stored["bark:ok"]).toEqual({ lastTs: 11, lastStatus: "ok", failStreak: 0 });
  });

  // 幂等不是「省一次 IO」：这条链每次升级都会重跑，重写一次的代价是用户的历史被第二次改形。
  it("重跑幂等：已经割接过的文件一个字都不动", () => {
    isolatedHome();
    const file = notifierFile(STATUS_FILE_NAME);
    write(
      file,
      `${JSON.stringify({ "bark:a": { lastTs: 1, lastStatus: "failed", lastError: "旧散文", failStreak: 1 } })}\n`,
    );
    migrateReasonShape();
    const once = read(file);

    migrateReasonShape();

    expect(read(file)).toBe(once);
  });

  // 等价判定含 params：只看 code+detail 的旧写法会把「已经割接好但带参数」的条目再写一次盘。
  it("带 params 的结构化条目不被改写（等价判据覆盖 params）", () => {
    isolatedHome();
    const file = notifierFile(STATUS_FILE_NAME);
    write(
      file,
      `${JSON.stringify({
        "bark:new": {
          lastTs: 1,
          lastStatus: "failed",
          lastError: { code: "reasonBarkHttp", params: { status: 401 }, detail: "nope" },
          failStreak: 1,
        },
      })}\n`,
    );
    const before = read(file);

    migrateReasonShape();

    expect(read(file)).toBe(before);
  });

  // 「内容没变」不等于「没写盘」：无条件重写会与并发 append 抢同一个文件，把那一行盖掉，而只比
  // 内容看不出来。判据不能用 inode（temp+rename 后 ext4 会复用刚释放的 inode 号，实测飘）也不
  // 能用 mtime（同一毫秒内不可分）——原来是**把写路径本身占死**，随机临时名下固定名占位不再生效，
  // 改成 mock 写面：第二次调用若真的落盘就必然触发 mock 并抛出，于是「不抛」就等价于「没碰盘」。
  it("无变化时连盘都不碰：写面 mock 后重跑不抛（真写一次就会触发 mock 并抛出）", () => {
    isolatedHome();
    const file = notifierFile(STATUS_FILE_NAME);
    write(
      file,
      `${JSON.stringify({ "bark:a": { lastTs: 1, lastStatus: "failed", lastError: "旧散文", failStreak: 1 } })}\n`,
    );
    migrateReasonShape();
    // 随机后缀下无法再用固定临时名占位：mock 写面让任何一次真写都抛（目录只读的 mock 等价物）。
    const spy = vi.spyOn(fileIo, "writeTextAtomicSync").mockImplementation(() => {
      throw new Error("unexpected write");
    });
    try {
      expect(() => migrateReasonShape()).not.toThrow();
    } finally {
      spy.mockRestore();
    }
  });

  // 写失败必须抛：迁移没做完而启动照常，等于让各域按错误形态去读数据（与 storage-layout 同口径）。
  // 直接让写面回失败 —— 不依赖固定临时名（随机后缀下占位固定名不再生效），也不靠只读目录、不依赖 root。
  // 随机名下不断言残留：失败是否留 tmp 是错误模型的事实，本补丁不动它。
  it("割接写失败即抛出（写面失败时抛出）", () => {
    isolatedHome();
    const file = notifierFile(STATUS_FILE_NAME);
    write(
      file,
      `${JSON.stringify({ "bark:a": { lastTs: 1, lastStatus: "failed", lastError: "旧散文", failStreak: 1 } })}\n`,
    );
    // 等价方案：mock 写面回失败（目录只读的 mock 等价物），保持「写失败即抛」语义。
    const spy = vi
      .spyOn(fileIo, "writeTextAtomicSync")
      .mockReturnValue({ ok: false, reason: "mocked EISDIR" });
    try {
      expect(() => migrateReasonShape()).toThrow(/割接写入失败/u);
    } finally {
      spy.mockRestore();
    }
  });

  // 读不出的旧文件不该拦住启动：读面本来就容错（半截 JSON 从空表开始），为它抛错是更坏的结果。
  it("内容读不出（坏 JSON）时不动那个文件", () => {
    isolatedHome();
    const file = notifierFile(STATUS_FILE_NAME);
    write(file, "{ 半截");

    migrateReasonShape();

    expect(read(file)).toBe("{ 半截");
  });

  it("文件不存在时什么都不做（storage-layout 负责建出初始形态）", () => {
    isolatedHome();
    const file = notifierFile(STATUS_FILE_NAME);

    migrateReasonShape();

    expect(existsSync(file)).toBe(false);
  });
});

describe("history.jsonl 的理由形态割接", () => {
  it("逐行换掉 channels[].reason，行数与其它字段都不变", () => {
    isolatedHome();
    const file = notifierFile(HISTORY_FILE_NAME);
    const oldLine = {
      ts: 1,
      kind: "done",
      title: "旧",
      message: "正文",
      channels: [
        { channelId: "bark:phone", status: "failed", reason: "timeout" },
        { channelId: "browser", status: "ok" },
      ],
    };
    write(file, `${JSON.stringify(oldLine)}\n`);

    migrateReasonShape();

    const lines = read(file).split("\n").filter(Boolean);
    expect(lines).toHaveLength(1);
    expect(JSON.parse(lines[0]!)).toEqual({
      ...oldLine,
      channels: [
        {
          channelId: "bark:phone",
          status: "failed",
          reason: { code: "reasonLegacy", detail: "timeout" },
        },
        { channelId: "browser", status: "ok" },
      ],
    });
  });

  // 坏行是常态（手改、半截写入）：整份重写时把它们弄丢，等于用一次升级抹掉用户的记录。
  it("坏行原样保留，只有需要改的行被改写", () => {
    isolatedHome();
    const file = notifierFile(HISTORY_FILE_NAME);
    const legacy = {
      ts: 2,
      kind: "done",
      channels: [{ channelId: "a", status: "failed", reason: "x" }],
    };
    write(file, `{ 坏行\n${JSON.stringify(legacy)}\n`);

    migrateReasonShape();

    const lines = read(file).split("\n").filter(Boolean);
    expect(lines).toHaveLength(2);
    expect(lines[0]).toBe("{ 坏行");
    expect(JSON.parse(lines[1]!).channels[0].reason).toEqual({
      code: "reasonLegacy",
      detail: "x",
    });
  });

  it("重跑幂等：全部已割接时文件逐字不变", () => {
    isolatedHome();
    const file = notifierFile(HISTORY_FILE_NAME);
    write(
      file,
      `${JSON.stringify({
        ts: 1,
        kind: "done",
        channels: [{ channelId: "a", status: "failed", reason: "旧散文" }],
      })}\n`,
    );
    migrateReasonShape();
    const once = read(file);

    migrateReasonShape();

    expect(read(file)).toBe(once);
  });
});

/**
 * dsh-notifier upgrade 域刻度读侧：存储版本（`version` 文件里的刻度）的**读策略**。
 *
 * 为什么判据落在包内而不在共享层：`shared/upgrade-chain.js` 只 `await ports.readScale()`，它
 * 一概不替消费方决定「读不到刻度怎么办」——回落起点还是中止启动、什么算合法版本号，都是本包
 * 自己的业务决定。本文件的四条判据就是那四个决定，链驱动自身（步骤筛选 / 逐步回写 / 对账告警）
 * 不在此重复。
 *
 * 落盘隔离：刻度路径经 `notifierFile()` 从 `DSH_HOME` 现拼（不在模块加载期定死），故每个用例
 * 一份 mkdtemp 临时 home，afterEach 连目录一起删——仓库内不留任何运行时产物。
 */
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import type { UpgradeDeps } from "../../../src/server/upgrade/deps.ts";
import {
  CONFIG_FILE_NAME,
  SEQ_FILE_NAME,
  VERSION_FILE_NAME,
  legacyFile,
  notifierFile,
} from "../../../src/server/shared/interface.ts";
import { installUpgrade, releaseUpgrade } from "../../../src/server/upgrade/interface.ts";
import { readStoredVersion } from "../../../src/server/upgrade/impl/version/index.ts";
import { makeLogger, tempDshHome } from "../../helpers.ts";

/** 旧存储位置里的序号文件名（刻度读不出来时，链若照跑就会把它搬进新落点并改名留痕）。 */
const LEGACY_SEQ_FILE = "notifier-seq.json";

/** 旧文件改名后缀：判据要的是「旧文件被处理过」，名字必须与实现同名的固定标记。 */
const MIGRATED_SUFFIX = ".migrated.bak";

let home: { readonly dir: string; dispose: () => void };

beforeEach(() => {
  home = tempDshHome();
});

afterEach(() => {
  // 装配标记是进程级单例状态：用例失败也要复位，否则后续用例会被「只能装配一次」连坐。
  releaseUpgrade();
  home.dispose();
});

/** 刻度文件的绝对路径（本包私有存储目录下）。 */
function versionPath(): string {
  return notifierFile(VERSION_FILE_NAME);
}

/** 落一份刻度：存储目录按需建（存量安装里它已在，全新安装里它不存在）。 */
function writeScale(text: string): string {
  const path = versionPath();
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text, "utf8");
  return path;
}

/**
 * 临时 home 的完整落盘清单（相对路径 + 类型 + 字节数 + 全文）。
 *
 * 「抛完之后磁盘一个字节都没动」这种否定判据只能钉在这样的快照上：单断「某文件不存在」说不清
 * 是这次没写、还是本来就没有；把内容也带上，才连「写了又改回原样」都盖得住。
 */
function diskSnapshot(root: string): string[] {
  const rows: string[] = [];
  const walk = (dir: string, prefix: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const where = prefix === "" ? entry.name : `${prefix}/${entry.name}`;
      if (entry.isDirectory()) {
        rows.push(`${where}/`);
        walk(join(dir, entry.name), where);
        continue;
      }
      rows.push(
        `${where} ${statSync(join(dir, entry.name)).size}B ${readFileSync(join(dir, entry.name), "utf8")}`,
      );
    }
  };
  walk(root, "");
  return rows.sort();
}

describe("读不到刻度：只有精确 ENOENT 从 0.0.0 起跑", () => {
  it("刻度文件不存在时返回 0.0.0，不中止启动（真 ENOENT 路径，不用接缝伪造）", () => {
    // 走真实同步读：全新安装的常态就是「存储目录都还没有」，接缝造不出这条路径。
    expect(existsSync(versionPath())).toBe(false);

    expect(readStoredVersion()).toBe("0.0.0");
  });
});

describe("读错误即中止启动（fail-closed，不把坏源伪装成全新安装）", () => {
  it("刻度路径是目录时抛读取失败，判词带出 Node 错误码 EISDIR", () => {
    // 路径与建目录分开写：mkdirSync 带 recursive 时返回 string | undefined，
    // 拿它的返回值当路径用会把 undefined 传进 statSync（TS2769）。
    const path = versionPath();
    mkdirSync(path, { recursive: true });

    expect(() => readStoredVersion()).toThrow(/存储版本文件读取失败/);
    expect(() => readStoredVersion()).toThrow(/EISDIR/);
    // 中止的另一半：抛错不许顺手把坏源补成一个能读的刻度（那正是把坏源伪装成全新安装）。
    // 目录也必须原样留在原地——换成文件即说明读面擅自改了现场。
    expect(statSync(path).isDirectory()).toBe(true);
  });

  it("抛错后磁盘一个字节都没动（不写盘、不留临时文件）", () => {
    mkdirSync(versionPath(), { recursive: true });
    const before = diskSnapshot(home.dir);

    expect(() => readStoredVersion()).toThrow(/存储版本文件读取失败/);

    expect(diskSnapshot(home.dir)).toEqual(before);
  });

  it("非 ENOENT 的读错误同样中止：EACCES 不回落起点", () => {
    // 接缝只为稳定覆盖 Node 错误码：EACCES 造不出稳定的真实目录形态（chmod 会被 root 绕过）。
    expect(() =>
      readStoredVersion(() => {
        throw Object.assign(new Error("permission denied"), { code: "EACCES" });
      }),
    ).toThrow(/存储版本文件读取失败（EACCES）/);
  });

  it("读错误不带 code 时按读取失败处理，判词里不出现空码段", () => {
    expect(() =>
      readStoredVersion(() => {
        throw new Error("读面炸了");
      }),
    ).toThrow("dsh-notifier: 存储版本文件读取失败 — 读面炸了");
  });
});

describe("空白刻度即中止启动（不是「没升级过」）", () => {
  it.each(["", "   ", "\n\t\n"])("刻度内容 %j → 抛存储版本文件为空", (text) => {
    writeScale(text);

    expect(() => readStoredVersion()).toThrow(/存储版本文件为空/);
  });
});

describe("非法版本号即中止启动（合法刻度长什么样是本包的白名单）", () => {
  it.each(["not-a-version", "0.2.3junk", "0.02.3", "0.2", "2.0.0", "1.0.0-rc.1"])(
    "刻度内容 %s → 抛非法或不支持的版本号",
    (text) => {
      writeScale(`${text}\n`);

      expect(() => readStoredVersion()).toThrow(/非法或不支持的版本号/);
    },
  );

  it.each(["0.2.3", "1.0.0", "1.12.7"])("白名单内的 %s 原样返回（别把合法值一起拒掉）", (text) => {
    writeScale(`${text}\n`);

    expect(readStoredVersion()).toBe(text);
  });

  it("首尾空白按 trim 去掉，中间内容逐字保留", () => {
    writeScale("  0.2.3  \n");

    expect(readStoredVersion()).toBe("0.2.3");
  });
});

describe("读侧中止的后果：一步迁移都不发生", () => {
  /** 链的入参：读刻度就中止，故存量读面在真跑到的路径上一次都不会被调用。 */
  function deps(): UpgradeDeps {
    return { logger: makeLogger(), legacySettings: { describe: () => [] } };
  }

  it("刻度读不出来时 upgrade 域装配中止：存量不读、目标不落、旧文件不改名", async () => {
    // 读侧一旦翻成 fail-safe（回落 0.0.0），0.2.3 → 0.2.4 那一步就会照跑：旧文件被搬进新落点、
    // 旧文件改名留痕。故「零迁移动作」只有钉住目标文件与归档名才看得见，单断「抛了」太弱。
    const legacySeq = legacyFile(LEGACY_SEQ_FILE);
    writeFileSync(legacySeq, "7\n", "utf8");
    mkdirSync(versionPath(), { recursive: true });

    await expect(installUpgrade(deps())).rejects.toThrow(/存储版本文件读取失败/);
    expect(existsSync(notifierFile(SEQ_FILE_NAME))).toBe(false);
    expect(existsSync(notifierFile(CONFIG_FILE_NAME))).toBe(false);
    expect([readFileSync(legacySeq, "utf8"), existsSync(`${legacySeq}${MIGRATED_SUFFIX}`)]).toEqual(
      ["7\n", false],
    );
  });
});

