/**
 * dsh-notifier upgrade 域 quiet-windows 块 —— 0.2.5 → 0.2.6 免打扰多时间窗割接。
 *
 * 判据面：这是动用户数据的第二步（第一步是 0.2.4 的配置形态割接）。搬错的表现是静默丢时段——
 * 用户配好的深夜窗口在升级后不再生效，而界面只会显示新形态的空列表。故逐条锁：旧起止逐字搬进
 * windows[0]、旧键删除、其余键不动；重跑逐字不动；半截旧形与坏文件不动（不替用户编窗口，
 * 不让一份读不懂的文件阻断启动）。
 */
import { existsSync, readFileSync } from "node:fs";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import {
  CONFIG_FILE_NAME,
  VERSION_FILE_NAME,
  notifierFile,
  writeTextAtomicSync,
} from "../../../src/server/shared/interface.ts";
import type { UpgradeDeps } from "../../../src/server/upgrade/deps.ts";
import { migrateQuietWindows } from "../../../src/server/upgrade/impl/steps/quiet-windows.ts";
import { STEPS } from "../../../src/server/upgrade/impl/steps/index.ts";
import { compareVersions } from "../../../../../shared/upgrade-chain.js";
import { installUpgrade, releaseUpgrade } from "../../../src/server/upgrade/interface.ts";
import { makeLogger, tempDshHome } from "../../helpers.ts";

let home: { readonly dir: string; dispose: () => void };

beforeEach(() => {
  home = tempDshHome();
});

afterEach(() => {
  releaseUpgrade();
  home.dispose();
});

/** 种一份磁盘上的配置文件。 */
function seedConfig(stored: Record<string, unknown>): void {
  writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), JSON.stringify(stored, null, 2) + "\n");
}

/**
 * 步骤表里最高的目标版本：链跑完的刻度应当正好落在它上面。
 * 写死版本号会让后续发版把这条用例打红，而它本意是「链跑到了表末」，不是「表末恰好是某个版本」。
 */
function newestTarget(): string {
  return STEPS.map((step) => step.targetVersion).reduce((newest, version) =>
    compareVersions(version, newest) > 0 ? version : newest,
  );
}

/** 磁盘上的配置文件内容。 */
function configOnDisk(): Record<string, unknown> {
  return JSON.parse(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")) as Record<
    string,
    unknown
  >;
}

describe("migrateQuietWindows：旧 start/end 搬进 windows[0] 并删旧键", () => {
  it("完整旧形：起止逐字搬进 windows[0]，旧键删除，其余键不动", () => {
    seedConfig({
      notifyAsk: false,
      quietHours: { enabled: true, start: "23:00", end: "07:00", allowKinds: ["error"] },
    });

    migrateQuietWindows();

    const quiet = configOnDisk().quietHours as Record<string, unknown>;
    expect(quiet).toEqual({
      enabled: true,
      windows: [{ start: "23:00", end: "07:00" }],
      allowKinds: ["error"],
    });
    expect(configOnDisk().notifyAsk).toBe(false);
  });

  it("幂等：已迁移的文件重跑逐字不动（压缩格式种文件，缩进会暴露白写一次）", () => {
    const before = JSON.stringify({
      quietHours: { enabled: true, windows: [{ start: "23:00", end: "07:00" }] },
    });
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), before);

    migrateQuietWindows();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });

  it("混合形态（windows 与旧键并存）：清旧键，windows 原样保留", () => {
    seedConfig({
      quietHours: {
        enabled: true,
        start: "23:00",
        end: "07:00",
        windows: [{ start: "12:00", end: "13:00" }],
      },
    });

    migrateQuietWindows();

    const quiet = configOnDisk().quietHours as Record<string, unknown>;
    expect(quiet).toEqual({ enabled: true, windows: [{ start: "12:00", end: "13:00" }] });
  });

  it("半截旧形（缺一半时钟键）：不动，不替用户编半个窗口", () => {
    const before = JSON.stringify({ quietHours: { enabled: true, start: "23:00" } });
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), before);

    migrateQuietWindows();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });

  it("没有 quietHours：文件逐字不动", () => {
    const before = JSON.stringify({ notifyAsk: false });
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), before);

    migrateQuietWindows();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });

  it("没有配置文件：不凭空建一份", () => {
    migrateQuietWindows();

    expect(existsSync(notifierFile(CONFIG_FILE_NAME))).toBe(false);
  });

  it("配置文件不是合法 JSON：不抛，文件不动", () => {
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), "{ 坏掉的\n");
    const before = readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8");

    expect(() => migrateQuietWindows()).not.toThrow();
    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });
});

describe("链级：刻度停在 0.2.5 的装机跑完这一步", () => {
  it("旧形文件被割接，刻度到步骤表末步", async () => {
    writeTextAtomicSync(notifierFile(VERSION_FILE_NAME), "0.2.5\n");
    seedConfig({ quietHours: { enabled: true, start: "23:00", end: "07:00" } });
    const face = {
      describe: () => {
        return [] as unknown as ReturnType<UpgradeDeps["legacySettings"]["describe"]>;
      },
    };
    const deps: UpgradeDeps = { logger: makeLogger(), legacySettings: face };

    await installUpgrade(deps);

    const quiet = configOnDisk().quietHours as Record<string, unknown>;
    expect(quiet).toEqual({ enabled: true, windows: [{ start: "23:00", end: "07:00" }] });
    expect(readFileSync(notifierFile(VERSION_FILE_NAME), "utf8").trim()).toBe(newestTarget());
  });
});

packages/dsh-notifier/test/unit/pipeline.source:
/**
 * dsh-notifier pipeline 域 finalize 块 —— 请求加工成待投递消息。
 *
 * 判据为什么是这些：
 *  - 强度缺省按 kind 补齐，外部 kind 则**缺席**而不是补一个中间档：出口的缺省路径已经定义了
 *    「未提供」的语义，这里再补一套就是第二个默认值来源；
 *  - 标题按码点截断、正文不截断：正文长度权威在各出口自己那里（bark 4096 / 页面 2048 /
 *    系统通知 256），在这里截会把系统通知的上限强加给所有出口。
 */
import { describe, expect, it } from "vitest";

import { finalizeRequest } from "../../../src/server/pipeline/impl/finalize/index.ts";
import { BUILTIN_KINDS } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { BuiltinKind } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/impl/service/type.ts";
import type { NotifySeverity } from "../../../src/server/pipeline/deps.ts";
import { wire } from "../../helpers.ts";

/**
 * 内置 kind → 缺省强度。独立写一遍而不是从源码导：值表漂移必须在这里红，抄源码就恒真了。
 * 表的完整性由「种类逐个对齐 `BUILTIN_KINDS`」那一条兜住。
 */
const KIND_SEVERITY_EXPECTED: ReadonlyArray<readonly [BuiltinKind, NotifySeverity]> = [
  ["ask", "warning"],
  ["question", "info"],
  ["done", "success"],
  ["subagent-done", "info"],
  ["error", "failure"],
  ["turn-end", "info"],
  ["test", "info"],
];

function requestOf(over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind: "done", title: "标题", body: "正文", ...over };
}

describe("finalizeRequest", () => {
  // 缺省强度串了档，用户看到的呈现与事件严重性不符（error 看起来像普通提示）。
  it("内置 kind 补缺省强度：error 必须是 failure（出错通知显示成普通提示就白通知了）", () => {
    for (const [kind, severity] of KIND_SEVERITY_EXPECTED) {
      expect(finalizeRequest(requestOf({ kind }), 1).severity, kind).toBe(severity);
    }
    expect(KIND_SEVERITY_EXPECTED.map(([kind]) => kind).sort()).toEqual([...BUILTIN_KINDS].sort());
  });

  // 非法强度被当成合法值传给出口，对端会收到它不认识的档位。
  it("调用方显式给的强度优先；非法强度视同未提供，回落 kind 缺省", () => {
    expect(finalizeRequest(requestOf({ kind: "error", severity: "info" }), 1).severity).toBe(
      "info",
    );
    expect(
      finalizeRequest(requestOf({ kind: "error", severity: wire<NotifySeverity>("critical") }), 1)
        .severity,
    ).toBe("failure");
  });

  // 给外部 kind 补一个「中间档」，等于替调用方决定了它没说的语义。
  it("外部 kind 没有缺省强度：不写 severity 键，调用方说了才写", () => {
    expect("severity" in finalizeRequest(requestOf({ kind: "demo:report" }), 1)).toBe(false);
    expect(
      finalizeRequest(requestOf({ kind: "demo:report", severity: "warning" }), 1).severity,
    ).toBe("warning");
    expect(
      "severity" in
        finalizeRequest(requestOf({ kind: "demo:report", severity: wire<NotifySeverity>("x") }), 1),
    ).toBe(false);
  });

  // 在定稿层截正文会把系统通知的 256 上限强加给所有出口，用户的正文被提前砍掉。
  it("标题按 64 码点截断且不腰斩 emoji；正文原样透传（长度权威在各出口）", () => {
    expect(
      Array.from(finalizeRequest(requestOf({ title: "题".repeat(65) }), 1).title),
    ).toHaveLength(64);
    const emoji = "🙂".repeat(64);
    expect(finalizeRequest(requestOf({ title: emoji }), 1).title).toBe(emoji);
    const longBody = "文".repeat(5000);
    expect(finalizeRequest(requestOf({ body: longBody }), 1).body).toBe(longBody);
  });

  // ts 或 kind 被改写，历史与投递载荷就对不上号，webhook 的 {{kind}} 也会跟着错。
  it("定稿不改内容：kind 与 ts 原样进消息（webhook 的 {{kind}}、bark 的 levels[kind] 都靠它）", () => {
    const message = finalizeRequest(
      requestOf({ kind: "demo:report", title: "T", body: "B" }),
      1_700_000_000_000,
    );
    expect(message.kind).toBe("demo:report");
    expect(message.ts).toBe(1_700_000_000_000);
    expect(message.title).toBe("T");
    expect(message.body).toBe("B");
  });
});

