/**
 * dsh-notifier src/shared —— 理由 code 闭集的直连判据。
 *
 * 这次收口的起因：客户端有一份 `const LEGACY_CODE = "reasonLegacy"`，注释自述「与服务端
 * REASON_LEGACY 同值」，而没有任何断言锁住两者相等——改一边就是一个读不出来的历史行。
 * 收口后两端消费同一个绑定，「同值」由构造保证；本文件再把值、成员与「客户端不再有第二份
 * 字面量」钉成可判红的判据。
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import { REASON_CODES, REASON_LEGACY } from "../../../src/shared/interface.ts";

const pkgDir = fileURLToPath(new URL("../../../", import.meta.url));

describe("REASON_LEGACY", () => {
  it("字面量与表内位置都钉住（旧散文的收编 code 只有一个）", () => {
    expect(REASON_LEGACY).toBe("reasonLegacy");
    expect(REASON_CODES[0]).toBe(REASON_LEGACY);
    expect(REASON_CODES).toContain(REASON_LEGACY);
  });
});

describe("REASON_CODES", () => {
  it("成员与顺序逐项钉住（新增 code 必须显式落在这张表上）", () => {
    expect([...REASON_CODES]).toEqual([
      "reasonLegacy",
      "reasonSkipConfig",
      "reasonSkipEnvironment",
      "reasonSystemPopupFailed",
      "reasonSystemSoundFailed",
      "reasonSystemToastScriptMissing",
      "reasonSystemToneUnwritable",
      "reasonBarkRequestFailed",
      "reasonBarkHttp",
      "reasonBarkRejected",
      "reasonBarkBodyUnreadable",
      "reasonWebhookTemplateInvalid",
      "reasonWebhookRequestFailed",
      "reasonWebhookHttp",
      "reasonUnknownTarget",
      "reasonChannelThrew",
      "reasonThrottled",
      "reasonDispatchCanceled",
    ]);
  });

  // 重复项不改变联合类型，却会让客户端的穷尽表看起来更全：漏一条文案仍能编译过。
  it("无重复项", () => {
    expect(new Set(REASON_CODES).size).toBe(REASON_CODES.length);
  });
});

describe("单点化：客户端不再抄一份同值字面量", () => {
  const clientSrc = () => readFileSync(join(pkgDir, "src/client/reason-text.ts"), "utf8");

  // 这一段只留「有没有 / 多没多」的最小结构锚，**不留计数**。为什么：本文件从 import.meta.url
  // 推导包目录去读盘，变异沙箱内读到的是被变异体包装过的同一份文件，于是「出现几次」这类断言
  // 锁的是环境而不是行为——CI 上它曾以 expected 5 to be 3 直接把该变异段的 dry run 判死。
  // 「客户端不再有第二份字面量」这件事无法用行为表达（两份字面量同值时行为完全一致），故只能
  // 靠结构锚；而 reasonLegacy 的行为判据在 test/client-unit/reason-text.test.ts 里（喂带 detail
  // 与不带 detail 两种输入，断主文案与 detail 去重），不在这里重复一遍。
  it("客户端引用共享绑定，LEGACY_CODE 已不存在", () => {
    const src = clientSrc();
    expect(src).not.toMatch(/LEGACY_CODE/u);
    expect(src).toContain("REASON_LEGACY");
    expect(src).toContain('from "../shared/interface.ts"');
  });

  it("客户端引用的是共享面而不是宿主实现（类型面同理）", () => {
    const src = clientSrc();
    expect(src).not.toContain("../server/");
    // 类型面必须仍是 import type：值引会把宿主实现拖进浏览器产物
    expect(src).toMatch(/import type \{[^}]*ReasonCode[^}]*\} from "\.\.\/shared\/interface\.ts"/u);
  });
});

describe("宿主实现侧：code 闭集是转出而不是第二份声明", () => {
  it("src/server/shared/reason.ts 只保留值函数与转出", () => {
    const src = readFileSync(join(pkgDir, "src/server/shared/reason.ts"), "utf8");
    expect(src).not.toMatch(/export const REASON_LEGACY/u);
    expect(src).not.toMatch(/export const REASON_CODES/u);
    expect(src).toMatch(/export \{ REASON_CODES, REASON_LEGACY \};/u);
    // 值函数仍在（它们依赖 ./text.ts，进不了零 import 的共享面）
    for (const fn of [
      "export function reason(",
      "export function reasonFromCause(",
      "export function normalizeReason(",
      "export function sameReasonShape(",
      "export function clampReasonDetail<",
    ]) {
      expect(src, fn).toContain(fn);
    }
  });
});

packages/dsh-notifier/test/unit/channels.source:
/**
 * dsh-notifier channels 域 browser 出口 —— 跨端通知帧的构造。
 *
 * 帧是本域唯一的线协议产物（宿主 → 客户端），判据只有两条：
 *  - 铃声决议：页面在「只响不弹」时没有能发系统提示音的实体，只能自播；决议错了表现为
 *    用户开了声音却一声不响，或不该响的时候响；
 *  - 上限与可选键：正文进帧前必须按页面侧的上限截断，而 `severity` 缺席要**不写键**而不是写
 *    `undefined`——线协议两侧对「这个键在不在」的解释不同。
 * 帧出口用假实现收帧，本块不需要真推送设施。
 */
import { describe, expect, it } from "vitest";

import { sendBrowser } from "../../../src/server/channels/impl/browser/index.ts";
import type { BrowserTarget, NotifyFrame } from "../../../src/server/channels/impl/browser/type.ts";
import type { NotifyMessage } from "../../../src/server/channels/impl/deliver/type.ts";

function messageOf(over: Partial<NotifyMessage> = {}): NotifyMessage {
  return { title: "标题", body: "正文", kind: "done", ts: 1_700_000_000_000, ...over };
}

/** 收帧的假出口：帧是这条出口的唯一产物，收到即投递完成。 */
function collector(): {
  frames: NotifyFrame[];
  targetOf: (over?: Partial<BrowserTarget>) => BrowserTarget;
} {
  const frames: NotifyFrame[] = [];
  return {
    frames,
    targetOf: (over = {}) => ({
      type: "browser",
      popup: true,
      sound: true,
      whenVisible: false,
      emitFrame: (frame) => {
        frames.push(frame);
      },
      ...over,
    }),
  };
}

describe("sendBrowser", () => {
  // 只响不弹时页面里没有能发系统提示音的实体，判错就是「开了声音却一声不响」。
  it("铃声决议：false 静音，跟随系统按弹不弹分叉，显式音色走自播", () => {
    const { frames, targetOf } = collector();
    const first = sendBrowser(targetOf({ sound: false }), messageOf());
    sendBrowser(targetOf({ sound: true, popup: true }), messageOf());
    sendBrowser(targetOf({ sound: true, popup: false }), messageOf());
    sendBrowser(targetOf({ sound: "ding", popup: true }), messageOf());

    expect(frames.map((frame) => frame.sound)).toEqual([
      { mode: "silent" },
      { mode: "system" },
      { mode: "selfplay" },
      { mode: "selfplay", tone: "ding" },
    ]);
    expect(frames.map((frame) => frame.pop)).toEqual([true, true, false, true]);
    // 交给帧出口即完成：页面弹没弹不是宿主能证明的事，证据上限只能是 accepted。
    expect(first).toEqual({ status: "ok", stage: "accepted" });
  });

  // 写成 undefined 的 severity 键会被客户端读成「显式声明了空强度」；正文超限则显示被截断或整条丢弃。
  it("按页面侧上限截断标题与正文，severity 缺席就不写这个键，可见性随帧下发", () => {
    const { frames, targetOf } = collector();
    sendBrowser(targetOf(), messageOf({ title: "题".repeat(100), body: "文".repeat(3000) }));
    sendBrowser(targetOf({ whenVisible: true }), messageOf({ severity: "warning" }));

    expect(Array.from(frames[0]!.title)).toHaveLength(64);
    expect(Array.from(frames[0]!.body)).toHaveLength(2048);
    expect("severity" in frames[0]!).toBe(false);
    expect(frames[1]!.severity).toBe("warning");
    // 可见性只有页面知道，故随帧下发：渲染端回查配置会读到可能已经变过的那一份。
    expect(frames.map((frame) => frame.whenVisible)).toEqual([false, true]);
  });

  // 什么都不发也是一次投递，只是没有动作：发空帧会推进序号、进重放缓冲、并让页面认领主标签租约，
  // 而记成 ok 会让历史里多出一条没发生过的成功。判据必须把「出口自己的回答」钉死在结果上。
  it("弹窗与声音都关：不发帧，收成 skipped 而不是伪造一次投递成功", () => {
    const { frames, targetOf } = collector();
    const result = sendBrowser(targetOf({ popup: false, sound: false }), messageOf());

    // 成因经 code 带出去（与 system 出口同一个 code）：两个出口的「用户都关了」是同一件事
    expect(result).toEqual({
      status: "skipped",
      reason: { code: "reasonSkipConfig" },
    });
    expect(frames).toEqual([]);
  });
});

packages/dsh-notifier/test/unit/shared/p.source:
/**
 * dsh-notifier shared 域 paths 块 —— 存储布局与 DSH_HOME 解析。
 *
 * 为什么值得单独一测：文件名是**迁移契约**的一半（升级模块要把旧文件搬到这些名字上），
 * 陈旧路径与陈旧文件名都会静默丢数据——升级读空、旧文件留在原地、用户看到「通知记录没了」。
 * 路径随 `DSH_HOME` 走是另一半：隔离验证与测试换掉该变量即换掉全部落盘位置，漏一处就写进真实 `~/.dsh`。
 */
import { globSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterEach, describe, expect, it } from "vitest";

import {
  CONFIG_FILE_NAME,
  HISTORY_FILE_NAME,
  SEQ_FILE_NAME,
  STATUS_FILE_NAME,
  VERSION_FILE_NAME,
  legacyFile,
  notifierFile,
  toastScriptPath,
} from "../../../src/server/shared/interface.ts";
import { tempDshHome, withEnv } from "../../helpers.ts";

/** 本文件内建过的隔离环境，逐个在 afterEach 还原（漏一个就会污染后续用例的落盘位置）。 */
const cleanups: Array<() => void> = [];

afterEach(() => {
  for (const dispose of cleanups.splice(0)) dispose();
});

describe("存储文件名即迁移契约", () => {
  it("五个文件名逐字固定", () => {
    expect([
      CONFIG_FILE_NAME,
      HISTORY_FILE_NAME,
      STATUS_FILE_NAME,
      SEQ_FILE_NAME,
      VERSION_FILE_NAME,
    ]).toEqual(["config.json", "history.jsonl", "status.json", "seq.json", "version"]);
  });

  it("插件私有目录按 npm 包名分区，不与其它插件争用 DSH home 根", () => {
    const home = tempDshHome();
    cleanups.push(home.dispose);
    expect(notifierFile(CONFIG_FILE_NAME)).toBe(
      join(home.dir, "@wingsky-1", "dsh-notifier", "config.json"),
    );
  });

  it("旧布局在 DSH home 根：迁移的读端与写端必须同时可命名，否则迁移会读空", () => {
    const home = tempDshHome();
    cleanups.push(home.dispose);
    expect(legacyFile("dsh-notifier.json")).toBe(join(home.dir, "dsh-notifier.json"));
  });
});

describe("DSH_HOME 语义（与 shared/dsh-home.js、官方 resolveDshHome 同源）", () => {
  it("空白 DSH_HOME 视同未设置，回落 <home>/.dsh", () => {
    // 两个 home 变量都设：POSIX 读 HOME，Windows 按 libuv 语义读 USERPROFILE。
    cleanups.push(
      withEnv({ DSH_HOME: "   ", HOME: "/dsh-home-probe", USERPROFILE: "/dsh-home-probe" }),
    );
    expect(notifierFile(VERSION_FILE_NAME)).toBe(
      join("/dsh-home-probe", ".dsh", "@wingsky-1", "dsh-notifier", "version"),
    );
  });
});

describe("系统通知脚本位置", () => {
  it("反推尾段与脚本在 src 下的真实位置一致（脚本搬家而函数没跟上即红）", () => {
    // 该函数按**包入口所在目录**反推：产物形态是内联的 lib/index.js，资源随 bundle-host 按
    // src 相对结构复制到 lib/ 下，故尾段必须等于脚本相对 src 的路径。断言「该路径存在」是假红
    // ——直跑 src 时包入口在 src 顶层，反推落点本就不存在；断言写死字面量则要人肉同步。
    const srcRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..", "src");
    const scripts = globSync("**/*.ps1", { cwd: srcRoot });
    expect(scripts).toHaveLength(1);
    expect(toastScriptPath().replaceAll("\\", "/").endsWith(`/${scripts[0]!}`)).toBe(true);
  });
});
